                                </div>
                                <div class="card-body">
                                    <div id="pamir-variables-display" class="pamir-variables">
                                        <div class="text-center text-muted p-3">
                                            No Pamir data loaded. Import a project to see variables.
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <!-- Quote Line Items Grid -->
                            <div class="card">
