                                    <i class="fas fa-play"></i> Launch
                                </button>
                            </div>
                        </div>
                    </div>
                `);
            }
        }
    }
}

// Launch modular system
// Charter-compliant function to launch modular system
function launchModularSystem() {
    // Delegate to the new charter-compliant launcher
    launchCharterModule('Customers');
}

// Charter-compliant module launcher according to the Modular App Charter
function launchCharterModule(moduleName) {
    console.log(`Launching Charter Module: ${moduleName}...`);

    // Check if platform is initialized
    if (!window.modularApp) {
        console.log('Platform not ready, initializing...');
        setTimeout(() => launchCharterModule(moduleName), 100);
        return;
    }

    // Check platform health using charter-compliant method
    const healthy = performPlatformHealthCheck();

    if (!healthy) {
        console.log('Platform components still loading, using available functionality...');
    }

    // Launch the specific module according to charter
    switch(moduleName) {
        case 'Customers':
            launchCustomersModule();
            break;
        case 'Contacts':
            launchGenericModule('Contacts', ContactsModule);
            break;
        case 'Employees':
            launchGenericModule('Employees', EmployeesModule);
            break;
        case 'Projects':
            launchGenericModule('Projects', ProjectsModule);
            break;
        case 'Quotes':
            launchGenericModule('Quotes', QuotesModule);
            break;
        case 'Tenders':
            launchGenericModule('Tenders', TendersModule);
            break;
        case 'Orders':
            launchGenericModule('Orders', OrdersModule);
            break;
        case 'StockItems':
            launchGenericModule('StockItems', StockItemsModule);
            break;
        case 'Tasks':
            launchGenericModule('Tasks', TasksModule);
            break;
        case 'PhoneCalls':
            launchGenericModule('PhoneCalls', PhoneCallsModule);
            break;
        case 'Emails':
            launchGenericModule('Emails', EmailsModule);
            break;
        case 'Meetings':
            launchGenericModule('Meetings', MeetingsModule);
            break;
        case 'Products':
            launchProductsModule();
            break;
        case 'UnitsOfMeasure':
            launchGenericModule('UnitsOfMeasure', UnitsOfMeasureModule);
            break;
        case 'ItemTypes':
            launchGenericModule('ItemTypes', ItemTypesModule);
            break;
        case 'Categories':
            launchGenericModule('Categories', CategoriesModule);
            break;
        case 'CompanyTypes':
            launchGenericModule('CompanyTypes', CompanyTypesModule);
            break;
        case 'AccountTypes':
            launchGenericModule('AccountTypes', AccountTypesModule);
            break;
        case 'AccountRelationships':
            launchGenericModule('AccountRelationships', AccountRelationshipsModule);
            break;
        default:
            console.warn(`Module ${moduleName} not implemented yet`);
    }
}

function launchCustomersModule() {
    console.log('Loading Customers module...');

    const customersTab = document.getElementById('customers');
    const contentDiv = document.getElementById('customers-content');

    if (customersTab && contentDiv) {
        // Show the customers tab
        customersTab.classList.add('active');
        document.querySelectorAll('.tab-content').forEach(t => {
            if (t.id !== 'customers') t.classList.remove('active');
        });

        // Use legacy CustomerManager for now (charter allows gradual migration)
        if (!contentDiv.hasChildNodes() && window.CustomerManager) {
            console.log('CustomerManager: Initializing...');
            const customerManager = new CustomerManager(contentDiv);
            console.log('CustomerManager: Ready');
        }
    }
}

function launchProductsModule() {
    console.log('Loading Products module...');
    // TODO: Implement charter-compliant Products module
    console.log('Products module: Coming soon');
}

function launchGenericModule(moduleName, moduleClass) {
    console.log(`Loading ${moduleName} module...`);

    const tabId = moduleName.toLowerCase();
    const tab = document.getElementById(tabId) || document.querySelector(`[data-tab="${tabId}"]`);
    const contentDiv = document.getElementById(`${tabId}-content`);

    if (tab && contentDiv) {
        // Show the tab
        tab.classList.add('active');
        document.querySelectorAll('.tab-content').forEach(t => {
            if (t.id !== `${tabId}-content`) t.classList.remove('active');
        });

        // Load the module if available and not already loaded
        if (!contentDiv.hasChildNodes() && window[moduleClass]) {
            console.log(`${moduleName}: Initializing...`);
            const moduleInstance = new window[moduleClass](contentDiv);
            console.log(`${moduleName}: Ready`);
        } else if (!window[moduleClass]) {
            console.log(`${moduleName} module: Coming soon`);
        }
    } else {
        console.warn(`Tab or content area not found for ${moduleName}`);
    }
}

// Charter-compliant platform health check
function performPlatformHealthCheck() {
    // Use the new charter-compliant platform loader
    if (window.platformLoader) {
        const status = window.platformLoader.getHealthStatus();

        if (status.healthy) {
            console.log('✅ Charter Platform health check passed - All components loaded');
        } else {
            console.log('Platform components ready:', status.loaded);
            console.log('Platform components loading:', status.missing);
        }

        return status.healthy;
    }

    // Fallback to checking if ModularApp is available
    if (window.modularApp) {
        return window.modularApp.checkPlatformHealth();
    }

    console.warn('⚠️ Platform loader not available');
    return false;
}

// Global error handler for uncaught errors
window.addEventListener('error', (event) => {
    console.error('Global error:', event.error);
    if (window.app) {
        window.app.showAlert('A system error occurred. Please refresh the page if problems persist.', 'danger');
    }
});

