// Millennium Timber Roof ERP - Single Page Application
// Version 3.0 - NEW Address Search Field Added

console.log('Loading Millennium ERP v3.0 - Google Maps Integration');

// Global Google Maps initialization callback
function initializeGoogleMaps() {
    console.log('[Google Maps] API loaded successfully via callback');
    window.googleMapsLoaded = true;

    // Dispatch event to notify components that Google Maps is ready
    window.dispatchEvent(new CustomEvent('googleMapsLoaded'));
}

// Global app namespace
var MillenniumApp = {
    currentModule: null,
    selectedRecords: [],
    dataTable: null,
    googleMapsLoaded: false,

    // Initialize the application
    init: function() {
        this.bindEvents();
    },

    // Bind global events
    bindEvents: function() {
        // Navigation menu links
        $(document).on('click', '.nav-menu-link', function(e) {
            e.preventDefault();
            var module = $(this).data('module');
            MillenniumApp.loadModule(module);

            // Update active state
            $('.nav-menu-link').removeClass('active');
            $(this).addClass('active');

            // Close dropdown menu after selection
            $('#navMenuButton').dropdown('hide');
        });

        // Module cards on welcome screen
        $('.module-card').on('click', function() {
            var module = $(this).data('module');
            MillenniumApp.loadModule(module);
            $('.nav-menu-link[data-module="' + module + '"]').addClass('active');
        });
    },

    // Load module content
    loadModule: function(module) {
        this.currentModule = module;

        switch(module) {
            case 'customer':
                CustomerModule.loadList();
                break;
            case 'users':
                UsersModule.loadList();
                break;
            case 'settings':
                SettingsModule.loadList();
                break;
            default:
                this.showComingSoon(module);
        }
    },

    // Show coming soon message
    showComingSoon: function(module) {
        var html = '<div class="text-center py-5">' +
                   '<i class="fas fa-tools fa-5x text-muted mb-3"></i>' +
                   '<h3>Module Under Construction</h3>' +
                   '<p class="text-muted">The ' + module + ' module is coming soon!</p>' +
                   '</div>';
        $('#mainContent').html(html);
    },

    // Show notification
    showNotification: function(message, type) {
        type = type || 'info';
        var alertClass = 'alert-' + (type === 'error' ? 'danger' : type);

        var alertHtml = `
        <div class="alert ${alertClass} alert-dismissible fade show" style="position: fixed; top: 20px; right: 20px; z-index: 9999; min-width: 300px;">
            <strong>${type.charAt(0).toUpperCase() + type.slice(1)}:</strong> ${message}
            <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
        </div>`;

        $('body').append(alertHtml);

        // Auto dismiss after 5 seconds
        setTimeout(function() {
            $('.alert').last().alert('close');
        }, 5000);
    },

    // Format currency
    formatCurrency: function(amount) {
        return 'R ' + parseFloat(amount || 0).toFixed(2).replace(/\d(?=(\d{3})+\.)/g, '$&,');
    },

    // Universal column resizing function
    enableColumnResizing: function(tableSelector) {
        var self = this;
        var isResizing = false;
        var startX, startWidth, currentTh, table, tableContainer;

        // Function to add/restore resize handles
        function addResizeHandles() {
            // Ensure table has proper container for responsive behavior
            var $table = $(tableSelector);
            var $container = $table.closest('.dataTables_wrapper');

            // Set up container with responsive width that allows grid to resize with screen
            if ($container.length) {
                $container.css({
                    'width': '100%',
                    'overflow-x': 'auto',
                    'position': 'relative',
                    'box-sizing': 'border-box'
                });

                // Make sure the table can grow inside the container
                $table.css({
                    'min-width': '100%',
                    'width': 'auto'
                });
            }

            // Restore saved column widths
            var tableId = $(tableSelector).attr('id');
            if (tableId) {
                var savedWidths = localStorage.getItem(tableId + '_columnWidths');
                if (savedWidths) {
                    try {
                        var columnWidths = JSON.parse(savedWidths);
                        $(tableSelector + ' thead th').each(function(index) {
                            if (columnWidths[index]) {
                                $(this).css({
                                    'width': columnWidths[index] + 'px',
                                    'min-width': columnWidths[index] + 'px',
                                    'max-width': columnWidths[index] + 'px'
                                });
                            }
                        });
                    } catch (e) {
                        console.log('Failed to restore column widths:', e);
                    }
                }
            }

            // Add resize handles to column headers
            $(tableSelector + ' thead th').each(function(index) {
                if (index === 0) return; // Skip checkbox column

                var $th = $(this);
                // Remove existing handles first
                $th.find('.resize-handle').remove();

                var $handle = $('<div class="resize-handle"></div>');
                $th.css('position', 'relative');
                $th.append($handle);

                $handle.on('mousedown', function(e) {
                    isResizing = true;
                    currentTh = $th;
                    startX = e.pageX;
                    startWidth = $th.outerWidth();
                    table = $(tableSelector).DataTable();
                    tableContainer = $table.closest('.dataTables_wrapper')[0];

                    $('body').addClass('col-resizing');
                    $('body').css('user-select', 'none');
                    e.preventDefault();
                    e.stopPropagation();
                });
            });
        }

        // Initial handle setup
        addResizeHandles();

        // Re-add handles after every DataTables redraw (for pagination, sorting, filtering, etc.)
        $(tableSelector).on('draw.dt', function() {
            addResizeHandles();
        });

        // Handle mouse movement for resizing
        $(document).off('mousemove.columnResize').on('mousemove.columnResize', function(e) {
            if (!isResizing || !currentTh) return;

            var diff = e.pageX - startX;
            var newWidth = Math.max(50, startWidth + diff);

            // Set column width
            currentTh.css({
                'width': newWidth + 'px',
                'min-width': newWidth + 'px',
                'max-width': newWidth + 'px'
            });

            // Save column width to localStorage
            var tableId = $(tableSelector).attr('id');
            if (tableId) {
                var columnWidths = {};
                $(tableSelector + ' thead th').each(function(index) {
                    var width = $(this).outerWidth();
                    if (width > 0) {
                        columnWidths[index] = width;
                    }
                });
                localStorage.setItem(tableId + '_columnWidths', JSON.stringify(columnWidths));
            }
        });

        // Handle mouse up to stop resizing
        $(document).off('mouseup.columnResize').on('mouseup.columnResize', function(e) {
            if (isResizing) {
                isResizing = false;
                currentTh = null;
                table = null;
                tableContainer = null;

                // Clean up cursor and selection
                $('body').removeClass('col-resizing');
                $('body').css('user-select', '');

                // Force cursor reset
                setTimeout(function() {
                    $('body').css('cursor', '');
                    $(tableSelector + ' thead th').css('cursor', '');
                }, 10);
            }
        });

        // Handle mouse leave to ensure cleanup
        $(document).off('mouseleave.columnResize').on('mouseleave.columnResize', function(e) {
            if (isResizing) {
                isResizing = false;
                currentTh = null;
                table = null;
                tableContainer = null;

                $('body').removeClass('col-resizing');
                $('body').css('user-select', '');
                setTimeout(function() {
                    $('body').css('cursor', '');
                    $(tableSelector + ' thead th').css('cursor', '');
                }, 10);
            }
        });
    }
};

// Customer Module
var CustomerModule = {
    customers: [],
    selectedId: null,
    currentFilters: null,
    importedData: null,

    // Load customer list view
    loadList: function() {
        // Hide welcome screen
        $('.welcome-screen').hide();

        // Show customer Blazor component
        $('#customer-blazor-host').show();

        // Note: Blazor component handles its own data loading, grid, and events
    },

    // Initialize DataTable
    initDataTable: function() {
        MillenniumApp.dataTable = $('#customerGrid').DataTable({
            responsive: true,
            scrollX: true,
            autoWidth: false,
            columns: [
                { 
                    data: null,
                    title: '<input type="checkbox" class="form-check-input" id="selectAllCustomers">',
                    width: "30px",
                    orderable: false,
