    // Update button state
    updateButtonState: function() {
        var selected = $('.row-select:checked');
        $('#btnEdit').prop('disabled', selected.length !== 1);
        $('#btnDelete').prop('disabled', selected.length === 0);

        if (selected.length === 1) {
            this.selectedId = selected.val();
        }
    },

