                <button class="nav-link active" id="company-types-tab" data-bs-toggle="tab" data-bs-target="#company-types" type="button" role="tab">
                    <i class="fas fa-building"></i> Company Types
                </button>
            </li>
            <li class="nav-item" role="presentation">
                <button class="nav-link" id="account-types-tab" data-bs-toggle="tab" data-bs-target="#account-types" type="button" role="tab">
                    <i class="fas fa-tags"></i> Account Types
                </button>
            </li>
        </ul>

        <div class="tab-content" id="settingsTabContent">
            <!-- Company Types Tab -->
            <div class="tab-pane fade show active" id="company-types" role="tabpanel">
                <div class="card mt-3">
                    <div class="card-body">
                        <div class="action-bar mb-3">
                            <div class="d-flex align-items-center gap-2 flex-wrap">
                                <button class="btn btn-primary btn-sm" onclick="SettingsModule.newCompanyType()">
                                    <i class="fas fa-plus"></i> New
                                </button>
                                <button class="btn btn-outline-primary btn-sm" id="btnEditCompanyType" onclick="SettingsModule.editCompanyType()" disabled>
                                    <i class="fas fa-edit"></i> Edit
                                </button>
                                <button class="btn btn-outline-danger btn-sm" id="btnDeleteCompanyType" onclick="SettingsModule.deleteCompanyType()" disabled>
                                    <i class="fas fa-trash"></i> Delete
                                </button>
                                <div class="action-separator"></div>
                                <button class="btn btn-outline-secondary btn-sm" onclick="SettingsModule.refreshCompanyTypes()">
                                    <i class="fas fa-sync"></i> Refresh
                                </button>
                                <div class="ms-auto action-search">
                                    <div class="input-group input-group-sm">
                                        <span class="input-group-text"><i class="fas fa-search"></i></span>
                                        <input type="text" class="form-control" id="companyTypeSearch" placeholder="Search company types...">
                                    </div>
                                </div>
                            </div>
                        </div>
                        <table id="companyTypesGrid" class="table table-hover table-striped mb-0" style="width:100%"></table>
                    </div>
                </div>
            </div>

            <!-- Account Types Tab -->
            <div class="tab-pane fade" id="account-types" role="tabpanel">
                <div class="card mt-3">
                    <div class="card-body">
                        <div class="action-bar mb-3">
                            <div class="d-flex align-items-center gap-2 flex-wrap">
                                <button class="btn btn-primary btn-sm" onclick="SettingsModule.newAccountType()">
                                    <i class="fas fa-plus"></i> New
                                </button>
                                <button class="btn btn-outline-primary btn-sm" id="btnEditAccountType" onclick="SettingsModule.editAccountType()" disabled>
                                    <i class="fas fa-edit"></i> Edit
                                </button>
                                <button class="btn btn-outline-danger btn-sm" id="btnDeleteAccountType" onclick="SettingsModule.deleteAccountType()" disabled>
                                    <i class="fas fa-trash"></i> Delete
                                </button>
                                <div class="action-separator"></div>
                                <button class="btn btn-outline-secondary btn-sm" onclick="SettingsModule.refreshAccountTypes()">
                                    <i class="fas fa-sync"></i> Refresh
                                </button>
                                <div class="ms-auto action-search">
                                    <div class="input-group input-group-sm">
                                        <span class="input-group-text"><i class="fas fa-search"></i></span>
                                        <input type="text" class="form-control" id="accountTypeSearch" placeholder="Search account types...">
                                    </div>
                                </div>
                            </div>
                        </div>
                        <table id="accountTypesGrid" class="table table-hover table-striped mb-0" style="width:100%"></table>
                    </div>
                </div>
            </div>
        </div>
        `;
    },

    // Initialize DataTables
    initDataTables: function() {
        // Company Types DataTable
        this.companyTypesTable = $('#companyTypesGrid').DataTable({
            scrollX: true,
            columns: [
                { 
                    data: null,
                    title: '<input type="checkbox" class="form-check-input" id="selectAllCompanyTypes">',
                    width: "30px",
                    orderable: false,
                    render: function(data, type, row) {
                        return '<input type="checkbox" class="form-check-input company-type-select" value="' + row.Id + '">';
                    }
                },
                { data: 'Code', title: "Code" },
                { data: 'Name', title: "Name" },
                { data: 'Description', title: "Description" },
                { 
                    data: 'IsActive',
                    title: "Status",
                    render: function(data) {
                        return data ? '<span class="badge bg-success">Active</span>' : '<span class="badge bg-secondary">Inactive</span>';
                    }
                }
            ],
            dom: 'rtip',
            pageLength: 25,
            lengthChange: false,
            searching: false,
            order: [[1, 'asc']],
            responsive: true,
            autoWidth: false,
            language: {
                emptyTable: "No company types found"
            },
            initComplete: function() {
                MillenniumApp.enableColumnResizing('#companyTypesGrid');
            }
        });

        // Account Types DataTable
        this.accountTypesTable = $('#accountTypesGrid').DataTable({
            scrollX: true,
            columns: [
                { 
                    data: null,
                    title: '<input type="checkbox" class="form-check-input" id="selectAllAccountTypes">',
                    width: "30px",
                    orderable: false,
                    render: function(data, type, row) {
                        return '<input type="checkbox" class="form-check-input account-type-select" value="' + row.Id + '">';
                    }
                },
                { data: 'Code', title: "Code" },
                { data: 'Name', title: "Name" },
                { data: 'Description', title: "Description" },
                { 
                    data: 'IsActive',
                    title: "Status",
                    render: function(data) {
                        return data ? '<span class="badge bg-success">Active</span>' : '<span class="badge bg-secondary">Inactive</span>';
                    }
                }
            ],
            dom: 'rtip',
            pageLength: 25,
            lengthChange: false,
            searching: false,
            order: [[1, 'asc']],
            responsive: true,
            autoWidth: false,
            language: {
                emptyTable: "No account types found"
            },
            initComplete: function() {
                MillenniumApp.enableColumnResizing('#accountTypesGrid');
            }
        });
    },

    // Bind events
    bindEvents: function() {
        // Search functionality
        $('#companyTypeSearch').on('keyup', function() {
            SettingsModule.companyTypesTable.search(this.value).draw();
        });

        $('#accountTypeSearch').on('keyup', function() {
            SettingsModule.accountTypesTable.search(this.value).draw();
        });

        // Selection events
        $('#selectAllCompanyTypes').on('change', function() {
            $('.company-type-select').prop('checked', this.checked);
            SettingsModule.updateCompanyTypeButtons();
        });

        $('#selectAllAccountTypes').on('change', function() {
            $('.account-type-select').prop('checked', this.checked);
            SettingsModule.updateAccountTypeButtons();
        });

        $(document).on('change', '.company-type-select', function() {
            SettingsModule.updateCompanyTypeButtons();
        });

        $(document).on('change', '.account-type-select', function() {
            SettingsModule.updateAccountTypeButtons();
        });

        // Double click to edit
        $('#companyTypesGrid tbody').on('dblclick', 'tr', function() {
            var data = SettingsModule.companyTypesTable.row(this).data();
            if (data) {
                SettingsModule.editCompanyType(data.Id);
            }
        });

        $('#accountTypesGrid tbody').on('dblclick', 'tr', function() {
            var data = SettingsModule.accountTypesTable.row(this).data();
            if (data) {
                SettingsModule.editAccountType(data.Id);
            }
        });
    },

    // Load data from APIs
    loadData: function() {
        // Load Company Types
        $.get('/api/LookupsApi/company-types')
            .done(data => {
                this.companyTypes = data;
                this.companyTypesTable.clear().rows.add(data).draw();
            })
            .fail(() => {
                MillenniumApp.showNotification('Failed to load company types', 'error');
            });

        // Load Account Types
        $.get('/api/LookupsApi/account-types')
            .done(data => {
                this.accountTypes = data;
                this.accountTypesTable.clear().rows.add(data).draw();
            })
            .fail(() => {
                MillenniumApp.showNotification('Failed to load account types', 'error');
            });
    },

    // Refresh methods
    refreshCompanyTypes: function() {
        $.get('/api/LookupsApi/company-types')
            .done(data => {
                this.companyTypes = data;
                this.companyTypesTable.clear().rows.add(data).draw();
                MillenniumApp.showNotification('Company types refreshed', 'success');
            })
            .fail(() => {
                MillenniumApp.showNotification('Failed to refresh company types', 'error');
            });
    },

    refreshAccountTypes: function() {
        $.get('/api/LookupsApi/account-types')
            .done(data => {
                this.accountTypes = data;
                this.accountTypesTable.clear().rows.add(data).draw();
                MillenniumApp.showNotification('Account types refreshed', 'success');
            })
            .fail(() => {
                MillenniumApp.showNotification('Failed to refresh account types', 'error');
            });
    },

    // Update button states
    updateCompanyTypeButtons: function() {
        var selected = $('.company-type-select:checked').length;
        $('#btnEditCompanyType').prop('disabled', selected !== 1);
        $('#btnDeleteCompanyType').prop('disabled', selected === 0);
    },

    updateAccountTypeButtons: function() {
        var selected = $('.account-type-select:checked').length;
        $('#btnEditAccountType').prop('disabled', selected !== 1);
        $('#btnDeleteAccountType').prop('disabled', selected === 0);
    },

    // Company Type Methods
    newCompanyType: function() {
        this.selectedCompanyTypeId = null;
        this.showCompanyTypeForm();
    },

    editCompanyType: function(id) {
        if (!id) {
            var selected = $('.company-type-select:checked');
            if (selected.length !== 1) return;
            id = selected.val();
        }

        this.selectedCompanyTypeId = id;

        // Find the company type
        var companyType = this.companyTypes.find(ct => ct.Id == id);
        if (companyType) {
            this.showCompanyTypeForm(companyType);
        }
    },

    showCompanyTypeForm: function(data) {
        var isEdit = !!data;
        var modalHtml = `
        <div class="modal fade" id="companyTypeModal" tabindex="-1">
            <div class="modal-dialog">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">${isEdit ? 'Edit' : 'New'} Company Type</h5>
                        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
                    </div>
                    <div class="modal-body">
                        <div class="mb-3">
                            <label class="form-label">Code <span class="text-danger">*</span></label>
                            <input type="text" class="form-control" id="ctCode" value="${data ? data.Code : ''}" required>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Name <span class="text-danger">*</span></label>
                            <input type="text" class="form-control" id="ctName" value="${data ? data.Name : ''}" required>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Description</label>
                            <textarea class="form-control" id="ctDescription" rows="3">${data ? data.Description || '' : ''}</textarea>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Sort Order</label>
                            <input type="number" class="form-control" id="ctSortOrder" value="${data ? data.SortOrder || 0 : 0}">
                        </div>
                        <div class="form-check">
                            <input type="checkbox" class="form-check-input" id="ctIsActive" ${!data || data.IsActive ? 'checked' : ''}>
                            <label class="form-check-label" for="ctIsActive">Active</label>
                        </div>
                    </div>
                    <div class="modal-footer">
                        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button>
                        <button type="button" class="btn btn-primary" onclick="SettingsModule.saveCompanyType()">Save</button>
                    </div>
                </div>
            </div>
        </div>
        `;

        // Remove existing modal if any
        $('#companyTypeModal').remove();
        $('body').append(modalHtml);

        var modal = new bootstrap.Modal(document.getElementById('companyTypeModal'));
        modal.show();
    },

    saveCompanyType: function() {
        var data = {
            Code: $('#ctCode').val().trim(),
            Name: $('#ctName').val().trim(),
            Description: $('#ctDescription').val().trim(),
            SortOrder: parseInt($('#ctSortOrder').val()) || 0,
            IsActive: $('#ctIsActive').is(':checked')
        };

        if (!data.Code || !data.Name) {
            MillenniumApp.showNotification('Please fill in required fields', 'error');
            return;
        }

        var url = this.selectedCompanyTypeId ? 
            '/api/LookupsApi/company-types/' + this.selectedCompanyTypeId : 
            '/api/LookupsApi/company-types';
        var method = this.selectedCompanyTypeId ? 'PUT' : 'POST';

        $.ajax({
            url: url,
            method: method,
            contentType: 'application/json',
            data: JSON.stringify(data),
            success: () => {
                MillenniumApp.showNotification('Company Type saved successfully', 'success');
                bootstrap.Modal.getInstance(document.getElementById('companyTypeModal')).hide();
                this.loadData();
            },
            error: () => {
                MillenniumApp.showNotification('Failed to save Company Type', 'error');
            }
        });
    },

    deleteCompanyType: function() {
        var selected = $('.company-type-select:checked');
        if (selected.length === 0) return;

        if (!confirm('Are you sure you want to deactivate ' + selected.length + ' company type(s)?')) return;

        var promises = [];
        selected.each(function() {
            promises.push($.ajax({
                url: '/api/LookupsApi/company-types/' + $(this).val(),
                method: 'DELETE'
            }));
        });

        Promise.all(promises).then(() => {
            MillenniumApp.showNotification('Company Types deactivated successfully', 'success');
            this.loadData();
        }).catch(() => {
            MillenniumApp.showNotification('Failed to deactivate some company types', 'error');
        });
    },

    // Account Type Methods
    newAccountType: function() {
        this.selectedAccountTypeId = null;
        this.showAccountTypeForm();
    },

    editAccountType: function(id) {
        if (!id) {
            var selected = $('.account-type-select:checked');
            if (selected.length !== 1) return;
            id = selected.val();
        }

        this.selectedAccountTypeId = id;

        // Find the account type
        var accountType = this.accountTypes.find(at => at.Id == id);
        if (accountType) {
            this.showAccountTypeForm(accountType);
        }
    },

    showAccountTypeForm: function(data) {
        var isEdit = !!data;
        var modalHtml = `
        <div class="modal fade" id="accountTypeModal" tabindex="-1">
            <div class="modal-dialog">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">${isEdit ? 'Edit' : 'New'} Account Type</h5>
                        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
                    </div>
                    <div class="modal-body">
                        <div class="mb-3">
                            <label class="form-label">Code <span class="text-danger">*</span></label>
                            <input type="text" class="form-control" id="atCode" value="${data ? data.Code : ''}" required>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Name <span class="text-danger">*</span></label>
                            <input type="text" class="form-control" id="atName" value="${data ? data.Name : ''}" required>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Description</label>
                            <textarea class="form-control" id="atDescription" rows="3">${data ? data.Description || '' : ''}</textarea>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Sort Order</label>
                            <input type="number" class="form-control" id="atSortOrder" value="${data ? data.SortOrder || 0 : 0}">
                        </div>
                        <div class="form-check">
                            <input type="checkbox" class="form-check-input" id="atIsActive" ${!data || data.IsActive ? 'checked' : ''}>
                            <label class="form-check-label" for="atIsActive">Active</label>
                        </div>
                    </div>
                    <div class="modal-footer">
                        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button>
                        <button type="button" class="btn btn-info" onclick="SettingsModule.saveAccountType()">Save</button>
                    </div>
                </div>
            </div>
        </div>
        `;

        // Remove existing modal if any
        $('#accountTypeModal').remove();
        $('body').append(modalHtml);

        var modal = new bootstrap.Modal(document.getElementById('accountTypeModal'));
        modal.show();
    },

    saveAccountType: function() {
        var data = {
            Code: $('#atCode').val().trim(),
            Name: $('#atName').val().trim(),
            Description: $('#atDescription').val().trim(),
            SortOrder: parseInt($('#atSortOrder').val()) || 0,
            IsActive: $('#atIsActive').is(':checked')
        };

        if (!data.Code || !data.Name) {
            MillenniumApp.showNotification('Please fill in required fields', 'error');
            return;
        }

        var url = this.selectedAccountTypeId ? 
            '/api/LookupsApi/account-types/' + this.selectedAccountTypeId : 
            '/api/LookupsApi/account-types';
        var method = this.selectedAccountTypeId ? 'PUT' : 'POST';

        $.ajax({
            url: url,
            method: method,
            contentType: 'application/json',
            data: JSON.stringify(data),
            success: () => {
                MillenniumApp.showNotification('Account Type saved successfully', 'success');
                bootstrap.Modal.getInstance(document.getElementById('accountTypeModal')).hide();
                this.loadData();
            },
            error: () => {
                MillenniumApp.showNotification('Failed to save Account Type', 'error');
            }
        });
    },

    deleteAccountType: function() {
        var selected = $('.account-type-select:checked');
        if (selected.length === 0) return;

        if (!confirm('Are you sure you want to deactivate ' + selected.length + ' account type(s)?')) return;

        var promises = [];
        selected.each(function() {
            promises.push($.ajax({
                url: '/api/LookupsApi/account-types/' + $(this).val(),
                method: 'DELETE'
            }));
        });

        Promise.all(promises).then(() => {
            MillenniumApp.showNotification('Account Types deactivated successfully', 'success');
            this.loadData();
        }).catch(() => {
            MillenniumApp.showNotification('Failed to deactivate some account types', 'error');
        });
    }
};

// Initialize app when document ready
$(document).ready(function() {
    MillenniumApp.init();

