        max-width: 90vw;
    }
}

/* Responsive - Small Mobile */
@media (max-width: 576px) {
    .top-navbar {
        padding: 0.5rem;
    }

    .btn-sm {
        font-size: 0.75rem;
        padding: 0.25rem 0.5rem;
    }

    .form-container {
