import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Stack,
  Text,
  DetailsList,
  DetailsListLayoutMode,
  ConstrainMode,
  Selection,
  CommandBar,
  MessageBar,
  MessageBarType,
  Spinner,
  SpinnerSize,
  SearchBox,
  Panel,
  Checkbox,
  Dialog,
  DialogType,
  DialogFooter,
  PrimaryButton,
  DefaultButton,
  IconButton,
  Separator,
} from '@fluentui/react';
import type { IColumn, ICommandBarItemProps } from '@fluentui/react';
import { customerService } from '../services';
import type { Customer } from '../types';
import type { GridView, GridFilter } from '../types/gridView';
import { CustomerFormFullScreen } from '../components/CustomerFormFullScreen';
import { DeleteDialog } from '../components/DeleteDialog';
import { ViewManager } from '../components/ViewManager';
import { FilterBuilder } from '../components/FilterBuilder';
import * as XLSX from 'xlsx';

export const CustomersPage = () => {
  const navigate = useNavigate();
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [filteredCustomers, setFilteredCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | undefined>();
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [customerToDelete, setCustomerToDelete] = useState<Customer | undefined>();
  const [searchText, setSearchText] = useState('');
  const [isColumnPanelOpen, setIsColumnPanelOpen] = useState(false);
  const [isExportDialogOpen, setIsExportDialogOpen] = useState(false);
  const [isFilterBuilderOpen, setIsFilterBuilderOpen] = useState(false);
  const [sortColumn, setSortColumn] = useState<string>('');
  const [isSortedDescending, setIsSortedDescending] = useState(false);

  const defaultVisibleColumns: { [key: string]: boolean } = {
    accountNo: true,
    accountName: true,
    companyType: true,
    email: true,
    phone: true,
    city: true,
    customerStatus: true,
    isActive: true,
    mobile: false,
    website: false,
    vatRegistrationNo: false,
    companyRegistrationNo: false,
    streetAddress: false,
    province: false,
    postalCode: false,
    country: false,
  };

  const defaultColumnOrder = [
    'accountNo', 'accountName', 'companyType', 'email', 'phone', 
    'city', 'customerStatus', 'isActive', 'mobile', 'website', 
    'vatRegistrationNo', 'companyRegistrationNo', 'streetAddress', 
    'province', 'postalCode', 'country'
  ];

  const defaultView: GridView = {
    id: 'default-view',
    name: 'All Customers',
    isDefault: true,
    entityType: 'customer',
    columnVisibility: defaultVisibleColumns,
    columnOrder: defaultColumnOrder,
    filters: [],
  };

  const loadViews = (): GridView[] => {
    try {
      const saved = localStorage.getItem('customers-views');
      if (saved) {
        const views = JSON.parse(saved);
        return views.length > 0 ? views : [defaultView];
      }
    } catch (err) {
      console.warn('Failed to load views:', err);
    }
    return [defaultView];
  };

  const [views, setViews] = useState<GridView[]>(loadViews());
  const [currentView, setCurrentView] = useState<GridView>(
    views.find(v => v.isDefault) || defaultView
  );

  const [selection] = useState(
    new Selection({
      onSelectionChanged: () => {
        const selected = selection.getSelection()[0] as Customer | undefined;
        setSelectedCustomer(selected);
      },
    })
  );

  useEffect(() => {
    loadCustomers();
  }, []);

  useEffect(() => {
    applyFilters();
  }, [customers, searchText, currentView, sortColumn, isSortedDescending]);

  const loadCustomers = async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await customerService.getAll();
      setCustomers(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load customers');
    } finally {
      setLoading(false);
    }
  };

  const applyFilters = () => {
    let filtered = [...customers];

    // Apply global search
    if (searchText) {
      const search = searchText.toLowerCase();
      filtered = filtered.filter((customer) => {
        return (
          Object.values(customer).some((value) =>
            String(value).toLowerCase().includes(search)
          ) ||
          (customer.companyType?.name?.toLowerCase() || '').includes(search)
        );
      });
    }

    // Apply view filters with proper AND/OR logic
    if (currentView.filters && currentView.filters.length > 0) {
      filtered = filtered.filter((customer) => {
        let result = true;
        let currentLogic: 'AND' | 'OR' = 'AND';

        for (let i = 0; i < currentView.filters.length; i++) {
          const filter = currentView.filters[i];
          const fieldValue = filter.field === 'companyType'
            ? customer.companyType?.name
            : customer[filter.field as keyof Customer];

          const value = String(fieldValue ?? '').toLowerCase();
          const filterValue = filter.value.toLowerCase();

          let filterResult = false;
          switch (filter.operator) {
            case 'equals':
              filterResult = value === filterValue;
              break;
            case 'notEquals':
              filterResult = value !== filterValue;
              break;
            case 'contains':
              filterResult = value.includes(filterValue);
              break;
            case 'notContains':
              filterResult = !value.includes(filterValue);
              break;
            case 'beginsWith':
              filterResult = value.startsWith(filterValue);
              break;
            case 'endsWith':
              filterResult = value.endsWith(filterValue);
              break;
            case 'isEmpty':
              filterResult = !value;
              break;
            case 'isNotEmpty':
              filterResult = !!value;
              break;
            default:
              filterResult = true;
          }

          // Apply the filter result based on the previous logic operator
          if (i === 0) {
            result = filterResult;
          } else {
            if (currentLogic === 'AND') {
              result = result && filterResult;
            } else {
              result = result || filterResult;
            }
          }

          // Set the logic operator for the next iteration
          currentLogic = filter.logicOperator || 'AND';
        }

        return result;
      });
    }

    // Apply sorting
    if (sortColumn) {
      filtered.sort((a, b) => {
        let aValue: any;
        let bValue: any;

        if (sortColumn === 'companyType') {
          aValue = a.companyType?.name;
          bValue = b.companyType?.name;
        } else {
          aValue = a[sortColumn as keyof Customer];
          bValue = b[sortColumn as keyof Customer];
        }

        // Normalize undefined/null values for consistent sorting
        if (aValue === undefined || aValue === null) {
          aValue = typeof bValue === 'boolean' ? false : typeof bValue === 'number' ? 0 : '';
        }
        if (bValue === undefined || bValue === null) {
          bValue = typeof aValue === 'boolean' ? false : typeof aValue === 'number' ? 0 : '';
        }

        // Handle different types
        let comparison = 0;
        if (typeof aValue === 'string' && typeof bValue === 'string') {
          comparison = aValue.localeCompare(bValue);
        } else if (typeof aValue === 'number' && typeof bValue === 'number') {
          comparison = aValue - bValue;
        } else if (typeof aValue === 'boolean' && typeof bValue === 'boolean') {
          comparison = (aValue ? 1 : 0) - (bValue ? 1 : 0);
        }

        // If values are equal, use accountName as secondary sort for deterministic ordering
        if (comparison === 0 && sortColumn !== 'accountName') {
          const aName = a.accountName || '';
          const bName = b.accountName || '';
          comparison = aName.localeCompare(bName);
        }

        return isSortedDescending ? -comparison : comparison;
      });
    }

    setFilteredCustomers(filtered);
  };

  const handleNew = () => {
    setSelectedCustomer(undefined);
    setIsFormOpen(true);
  };

  const handleEdit = () => {
    if (selectedCustomer) {
      setIsFormOpen(true);
    }
  };

  const handleRowDoubleClick = (customer: Customer) => {
    setSelectedCustomer(customer);
    setIsFormOpen(true);
  };

  const handleDelete = () => {
    if (selectedCustomer) {
      setCustomerToDelete(selectedCustomer);
      setIsDeleteDialogOpen(true);
    }
  };

  const confirmDelete = async () => {
    if (customerToDelete) {
      try {
        await customerService.delete(customerToDelete.id);
        setIsDeleteDialogOpen(false);
        setCustomerToDelete(undefined);
        await loadCustomers();
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to delete customer');
      }
    }
  };

  const exportToExcel = (customersToExport: Customer[]) => {
    const exportData = customersToExport.map((customer) => ({
      'Account No': customer.accountNo,
      'Account Name': customer.accountName,
      'Company Type': customer.companyType?.name || '',
      'Email': customer.email || '',
      'Phone': customer.phone || '',
      'City': customer.city || '',
      'Province': customer.province || '',
      'Status': customer.customerStatus,
      'Active': customer.isActive ? 'Yes' : 'No',
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Customers');
    XLSX.writeFile(wb, `Customers_Export_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleExportSelected = () => {
    const selected = selection.getSelection() as Customer[];
    if (selected.length > 0) {
      exportToExcel(selected);
    }
    setIsExportDialogOpen(false);
  };

  const handleExportAll = () => {
    exportToExcel(filteredCustomers);
    setIsExportDialogOpen(false);
  };

  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet);
        console.log('Imported data:', jsonData);
      } catch (err) {
        setError('Failed to import Excel file');
      }
    };
    reader.readAsBinaryString(file);
    event.target.value = '';
  };

  const handleViewChange = (view: GridView) => {
    setCurrentView(view);
  };

  const handleSaveView = (view: GridView) => {
    const updatedViews = views.find(v => v.id === view.id)
      ? views.map(v => v.id === view.id ? view : v)
      : [...views, view];

    setViews(updatedViews);
    setCurrentView(view);
    localStorage.setItem('customers-views', JSON.stringify(updatedViews));
  };

  const handleDeleteView = (viewId: string) => {
    const updatedViews = views.filter(v => v.id !== viewId);
    setViews(updatedViews);
    localStorage.setItem('customers-views', JSON.stringify(updatedViews));
  };

  const handleSetDefaultView = (viewId: string) => {
    const updatedViews = views.map(v => ({
      ...v,
      isDefault: v.id === viewId,
    }));
    setViews(updatedViews);
    localStorage.setItem('customers-views', JSON.stringify(updatedViews));
  };

  const handleFiltersChange = (filters: GridFilter[]) => {
    const updatedView = { ...currentView, filters };
    setCurrentView(updatedView);
  };

  const updateCurrentViewColumns = (visibility: { [key: string]: boolean }, order: string[]) => {
    const updatedView = {
      ...currentView,
      columnVisibility: visibility,
      columnOrder: order,
    };
    setCurrentView(updatedView);
  };

  const moveColumnUp = (columnKey: string) => {
    const currentIndex = currentView.columnOrder.indexOf(columnKey);
    if (currentIndex > 0) {
      const newOrder = [...currentView.columnOrder];
      [newOrder[currentIndex - 1], newOrder[currentIndex]] = [newOrder[currentIndex], newOrder[currentIndex - 1]];
      updateCurrentViewColumns(currentView.columnVisibility, newOrder);
    }
  };

  const moveColumnDown = (columnKey: string) => {
    const currentIndex = currentView.columnOrder.indexOf(columnKey);
    if (currentIndex < currentView.columnOrder.length - 1) {
      const newOrder = [...currentView.columnOrder];
      [newOrder[currentIndex], newOrder[currentIndex + 1]] = [newOrder[currentIndex + 1], newOrder[currentIndex]];
      updateCurrentViewColumns(currentView.columnVisibility, newOrder);
    }
  };

  const onColumnClick = (_?: React.MouseEvent<HTMLElement>, column?: IColumn) => {
    if (!column) return;

    const columnKey = column.key;
    if (sortColumn === columnKey) {
      // Toggle sort direction
      setIsSortedDescending(!isSortedDescending);
    } else {
      // Sort by new column, ascending
      setSortColumn(columnKey);
      setIsSortedDescending(false);
    }
  };

  const availableFields = [
    { key: 'accountNo', name: 'Account No', type: 'text' as const },
    { key: 'accountName', name: 'Account Name', type: 'text' as const },
    { key: 'companyType', name: 'Company Type', type: 'text' as const },
    { key: 'email', name: 'Email', type: 'text' as const },
    { key: 'phone', name: 'Phone', type: 'text' as const },
    { key: 'mobile', name: 'Mobile', type: 'text' as const },
    { key: 'city', name: 'City', type: 'text' as const },
    { key: 'province', name: 'Province', type: 'text' as const },
    { key: 'customerStatus', name: 'Status', type: 'text' as const },
    { key: 'isActive', name: 'Active', type: 'boolean' as const },
  ];

  const allColumns: IColumn[] = [
    {
      key: 'accountNo',
      name: 'Account No',
      fieldName: 'accountNo',
      minWidth: 100,
      maxWidth: 150,
      isResizable: true,
      isSorted: sortColumn === 'accountNo',
      isSortedDescending: sortColumn === 'accountNo' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'accountName',
      name: 'Account Name',
      fieldName: 'accountName',
      minWidth: 200,
      maxWidth: 300,
      isResizable: true,
      isSorted: sortColumn === 'accountName',
      isSortedDescending: sortColumn === 'accountName' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'companyType',
      name: 'Company Type',
      minWidth: 150,
      maxWidth: 200,
      isResizable: true,
      isSorted: sortColumn === 'companyType',
      isSortedDescending: sortColumn === 'companyType' && isSortedDescending,
      onColumnClick: onColumnClick,
      onRender: (item: Customer) => <Text>{item.companyType?.name || '-'}</Text>,
    },
    {
      key: 'email',
      name: 'Email',
      fieldName: 'email',
      minWidth: 200,
      maxWidth: 300,
      isResizable: true,
      isSorted: sortColumn === 'email',
      isSortedDescending: sortColumn === 'email' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'phone',
      name: 'Phone',
      fieldName: 'phone',
      minWidth: 150,
      maxWidth: 200,
      isResizable: true,
      isSorted: sortColumn === 'phone',
      isSortedDescending: sortColumn === 'phone' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'city',
      name: 'City',
      fieldName: 'city',
      minWidth: 120,
      maxWidth: 180,
      isResizable: true,
      isSorted: sortColumn === 'city',
      isSortedDescending: sortColumn === 'city' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'customerStatus',
      name: 'Status',
      fieldName: 'customerStatus',
      minWidth: 120,
      maxWidth: 150,
      isResizable: true,
      isSorted: sortColumn === 'customerStatus',
      isSortedDescending: sortColumn === 'customerStatus' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'isActive',
      name: 'Active',
      fieldName: 'isActive',
      minWidth: 80,
      maxWidth: 100,
      isResizable: true,
      isSorted: sortColumn === 'isActive',
      isSortedDescending: sortColumn === 'isActive' && isSortedDescending,
      onColumnClick: onColumnClick,
      onRender: (item: Customer) => <Text>{item.isActive ? 'Yes' : 'No'}</Text>,
    },
    {
      key: 'mobile',
      name: 'Mobile',
      fieldName: 'mobile',
      minWidth: 120,
      maxWidth: 180,
      isResizable: true,
      isSorted: sortColumn === 'mobile',
      isSortedDescending: sortColumn === 'mobile' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'website',
      name: 'Website',
      fieldName: 'website',
      minWidth: 200,
      maxWidth: 300,
      isResizable: true,
      isSorted: sortColumn === 'website',
      isSortedDescending: sortColumn === 'website' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'vatRegistrationNo',
      name: 'VAT No',
      fieldName: 'vatRegistrationNo',
      minWidth: 120,
      maxWidth: 180,
      isResizable: true,
      isSorted: sortColumn === 'vatRegistrationNo',
      isSortedDescending: sortColumn === 'vatRegistrationNo' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'companyRegistrationNo',
      name: 'Company Reg No',
      fieldName: 'companyRegistrationNo',
      minWidth: 150,
      maxWidth: 200,
      isResizable: true,
      isSorted: sortColumn === 'companyRegistrationNo',
      isSortedDescending: sortColumn === 'companyRegistrationNo' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'streetAddress',
      name: 'Street Address',
      fieldName: 'streetAddress',
      minWidth: 200,
      maxWidth: 300,
      isResizable: true,
      isSorted: sortColumn === 'streetAddress',
      isSortedDescending: sortColumn === 'streetAddress' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'province',
      name: 'Province',
      fieldName: 'province',
      minWidth: 100,
      maxWidth: 150,
      isResizable: true,
      isSorted: sortColumn === 'province',
      isSortedDescending: sortColumn === 'province' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'postalCode',
      name: 'Postal Code',
      fieldName: 'postalCode',
      minWidth: 100,
      maxWidth: 120,
      isResizable: true,
      isSorted: sortColumn === 'postalCode',
      isSortedDescending: sortColumn === 'postalCode' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'country',
      name: 'Country',
      fieldName: 'country',
      minWidth: 100,
      maxWidth: 150,
      isResizable: true,
      isSorted: sortColumn === 'country',
      isSortedDescending: sortColumn === 'country' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
  ];

  const orderedColumns = currentView.columnOrder.map(key => allColumns.find(col => col.key === key)).filter(Boolean) as IColumn[];
  const columns = orderedColumns.filter((col) => currentView.columnVisibility[col.key]);

  const commandBarItems: ICommandBarItemProps[] = [
    {
      key: 'new',
      text: 'New',
      iconProps: { iconName: 'Add' },
      onClick: handleNew,
    },
    {
      key: 'edit',
      text: 'Edit',
      iconProps: { iconName: 'Edit' },
      disabled: !selectedCustomer,
      onClick: handleEdit,
    },
    {
      key: 'delete',
      text: 'Delete',
      iconProps: { iconName: 'Delete' },
      disabled: !selectedCustomer,
      onClick: handleDelete,
    },
    {
      key: 'refresh',
      text: 'Refresh',
      iconProps: { iconName: 'Refresh' },
      onClick: loadCustomers,
    },
    {
      key: 'export',
      text: 'Export to Excel',
      iconProps: { iconName: 'ExcelDocument' },
      onClick: () => setIsExportDialogOpen(true),
    },
    {
      key: 'import',
      text: 'Import from Excel',
      iconProps: { iconName: 'ExcelLogoInverse' },
      onClick: () => document.getElementById('customers-import-input')?.click(),
    },
    {
      key: 'mergeDuplicates',
      text: 'Merge Duplicates',
      iconProps: { iconName: 'Merge' },
      onClick: () => navigate('/duplicates?entity=Customers'),
    },
  ];

  const commandBarFarItems: ICommandBarItemProps[] = [
    {
      key: 'search',
      onRender: () => (
        <SearchBox
          placeholder="Search all columns..."
          value={searchText}
          onChange={(_, value) => setSearchText(value || '')}
          onClear={() => setSearchText('')}
          styles={{ root: { width: 300 } }}
        />
      ),
    },
  ];

  if (isFormOpen) {
    return (
      <CustomerFormFullScreen
        customer={selectedCustomer}
        onDismiss={() => {
          setIsFormOpen(false);
          setSelectedCustomer(undefined);
        }}
        onSave={() => {
          loadCustomers();
          setIsFormOpen(false);
          setSelectedCustomer(undefined);
        }}
      />
    );
  }

  return (
    <Stack tokens={{ childrenGap: 16 }}>
      <Text variant="xxLarge">Customers</Text>

      <CommandBar items={commandBarItems} farItems={commandBarFarItems} />

      <input
        id="customers-import-input"
        type="file"
        accept=".xlsx,.xls"
        style={{ display: 'none' }}
        onChange={handleImport}
      />

      {error && (
        <MessageBar messageBarType={MessageBarType.error} onDismiss={() => setError(null)}>
          {error}
        </MessageBar>
      )}

      {/* Power Apps-style Grid Header */}
      <Stack
        horizontal
        verticalAlign="center"
        tokens={{ childrenGap: 12 }}
        styles={{
          root: {
            padding: 12,
            backgroundColor: '#faf9f8',
            borderRadius: 4,
            border: '1px solid #edebe9',
          },
        }}
      >
        <ViewManager
          currentView={currentView}
          views={views}
          onViewChange={handleViewChange}
          onSaveView={handleSaveView}
          onDeleteView={handleDeleteView}
          onSetDefaultView={handleSetDefaultView}
        />
        <Separator vertical styles={{ root: { height: 32 } }} />
        <IconButton
          iconProps={{ iconName: 'ColumnOptions' }}
          title="Edit columns"
          onClick={() => setIsColumnPanelOpen(true)}
        />
        <IconButton
          iconProps={{ iconName: 'Filter' }}
          title="Edit filters"
          onClick={() => setIsFilterBuilderOpen(true)}
        />
      </Stack>

      {loading ? (
        <Stack horizontalAlign="center" tokens={{ padding: 40 }}>
          <Spinner size={SpinnerSize.large} label="Loading customers..." />
        </Stack>
      ) : (
        <div style={{ overflowX: 'auto', overflowY: 'visible' }}>
          <DetailsList
            items={filteredCustomers}
            columns={columns}
            layoutMode={DetailsListLayoutMode.fixedColumns}
            constrainMode={ConstrainMode.unconstrained}
            selection={selection}
            selectionPreservedOnEmptyClick={true}
            isHeaderVisible={true}
            onItemInvoked={handleRowDoubleClick}
          />
        </div>
      )}

      {/* Column Settings Panel */}
      <Panel
        isOpen={isColumnPanelOpen}
        onDismiss={() => setIsColumnPanelOpen(false)}
        headerText="Column Settings"
      >
        <Stack tokens={{ childrenGap: 12 }} styles={{ root: { marginTop: 16 } }}>
          {currentView.columnOrder.map((key, index) => {
            const col = allColumns.find(c => c.key === key);
            if (!col) return null;
            return (
              <Stack key={col.key} horizontal verticalAlign="center" tokens={{ childrenGap: 8 }}>
                <Checkbox
                  label={col.name}
                  checked={currentView.columnVisibility[col.key]}
                  onChange={(_, checked) =>
                    updateCurrentViewColumns(
                      { ...currentView.columnVisibility, [col.key]: checked || false },
                      currentView.columnOrder
                    )
                  }
                  styles={{ root: { flex: 1 } }}
                />
                <Stack horizontal tokens={{ childrenGap: 4 }}>
                  <DefaultButton
                    iconProps={{ iconName: 'Up' }}
                    disabled={index === 0}
                    onClick={() => moveColumnUp(col.key)}
                    styles={{ root: { minWidth: 32, padding: '0 8px' } }}
                  />
                  <DefaultButton
                    iconProps={{ iconName: 'Down' }}
                    disabled={index === currentView.columnOrder.length - 1}
                    onClick={() => moveColumnDown(col.key)}
                    styles={{ root: { minWidth: 32, padding: '0 8px' } }}
                  />
                </Stack>
              </Stack>
            );
          })}
        </Stack>
      </Panel>

      {/* Filter Builder Panel */}
      <FilterBuilder
        isOpen={isFilterBuilderOpen}
        onDismiss={() => setIsFilterBuilderOpen(false)}
        filters={currentView.filters}
        onFiltersChange={handleFiltersChange}
        availableFields={availableFields}
      />

      <Dialog
        hidden={!isExportDialogOpen}
        onDismiss={() => setIsExportDialogOpen(false)}
        dialogContentProps={{
          type: DialogType.normal,
          title: 'Export to Excel',
          subText: 'Choose which records to export',
        }}
      >
        <DialogFooter>
          <PrimaryButton
            onClick={handleExportSelected}
            text={`Export Selected (${selection.getSelectedCount()})`}
            disabled={selection.getSelectedCount() === 0}
          />
          <DefaultButton onClick={handleExportAll} text={`Export All (${filteredCustomers.length})`} />
          <DefaultButton onClick={() => setIsExportDialogOpen(false)} text="Cancel" />
        </DialogFooter>
      </Dialog>

      <DeleteDialog
        isOpen={isDeleteDialogOpen}
        title="Delete Customer"
        message={`Are you sure you want to delete ${customerToDelete?.accountName}?`}
        onConfirm={confirmDelete}
        onCancel={() => setIsDeleteDialogOpen(false)}
      />
    </Stack>
  );
};

