// Enhanced Location Field - Combines Google autocomplete with interactive map
class EnhancedLocationField {
    constructor(containerId, options = {}) {
        this.containerId = containerId;
        this.container = document.getElementById(containerId);
        this.options = options;
        this.onLocationSelect = options.onLocationSelect || (() => {});
        this.currentLocation = null;
        this.map = null;
        this.marker = null;
        this.autocomplete = null;

        // Default to Pretoria, South Africa
        this.defaultCenter = { lat: -25.7479, lng: 28.2293 };

        this.init();
    }

    init() {
        this.render();
        this.setupEventListeners();
        this.initializeComponents();
    }

    render() {
        this.container.innerHTML = `
            <div class="enhanced-location-field">
                <!-- Address Input with Autocomplete -->
                <div class="address-input-section mb-3">
                    <div class="input-group">
                        <input type="text" class="form-control" id="location-address-input" 
                               placeholder="Type address...">
                        <button class="btn btn-outline-primary" type="button" id="use-current-location-btn">
                            <i class="fas fa-crosshairs"></i> My Location
                        </button>
                        <button class="btn btn-outline-secondary" type="button" id="clear-location-btn">
                            <i class="fas fa-times"></i>
                        </button>
                    </div>
                    <div class="form-text text-muted">
                        <i class="fas fa-info-circle"></i> Type to search addresses or click "My Location" for GPS positioning
                    </div>
                </div>

                <!-- Interactive Map -->
                <div class="map-section">
                    <div id="enhanced-location-map" style="height: 250px; border: 2px solid #dee2e6; border-radius: 0.375rem; position: relative;">
                        <div class="map-loading d-flex justify-content-center align-items-center h-100" id="map-loading">
                            <div class="text-center">
                                <div class="spinner-border text-primary mb-2" role="status"></div>
                                <div class="small">Loading map...</div>
                            </div>
                        </div>
                    </div>

                    <!-- Map Controls -->
                    <div class="map-controls mt-2 d-flex justify-content-between">
                        <div class="location-info">
                            <small class="text-muted" id="location-coordinates">Click on map to drop pin</small>
                        </div>
                        <div class="map-actions">
                            <button type="button" class="btn btn-sm btn-outline-success" id="save-location-btn" disabled>
                                <i class="fas fa-save"></i> Save Location
                            </button>
                        </div>
                    </div>
                </div>

                <!-- Saved Location Display -->
                <div class="saved-location-section mt-3" id="saved-location-display" style="display: none;">
                    <div class="alert alert-success">
                        <div class="row align-items-center">
                            <div class="col">
                                <strong><i class="fas fa-map-marker-alt"></i> Location Saved</strong>
                                <div id="saved-location-text" class="small"></div>
                            </div>
                            <div class="col-auto">
                                <button type="button" class="btn btn-sm btn-success" id="navigate-btn">
                                    <i class="fas fa-directions"></i> Navigate
                                </button>
                                <button type="button" class="btn btn-sm btn-outline-secondary" id="edit-location-btn">
                                    <i class="fas fa-edit"></i> Edit
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        `;
    }

    setupEventListeners() {
        // Use current location button
        document.getElementById('use-current-location-btn').addEventListener('click', () => {
            this.getCurrentLocation();
        });

        // Clear location button
        document.getElementById('clear-location-btn').addEventListener('click', () => {
            this.clearLocation();
        });

        // Save location button
        document.getElementById('save-location-btn').addEventListener('click', () => {
            this.saveLocation();
        });

        // Navigate button
        document.getElementById('navigate-btn').addEventListener('click', () => {
            this.navigateToLocation();
        });

        // Edit location button
        document.getElementById('edit-location-btn').addEventListener('click', () => {
            this.showEditMode();
        });
    }

    initializeComponents() {
        console.log('[Google Maps Address Search] Initializing...');

        // Wait for Google Maps to load
        if (typeof google !== 'undefined' && google.maps) {
            console.log('[Google Maps Address Search] Google Maps already loaded, initializing now');
            this.initializeMap();
            this.initializeAutocomplete();
        } else {
            console.log('[Google Maps Address Search] Google Maps not loaded yet, waiting for callback...');
            // Listen for the googleMapsLoaded event
            window.addEventListener('googleMapsLoaded', () => {
                console.log('[Google Maps Address Search] Google Maps loaded via callback, initializing now');
                this.initializeMap();
                this.initializeAutocomplete();
            }, { once: true });

            // Fallback timeout in case the callback doesn't work
            setTimeout(() => {
                if (typeof google !== 'undefined' && google.maps) {
                    console.log('[Google Maps Address Search] Google Maps loaded via timeout fallback');
                    this.initializeMap();
                    this.initializeAutocomplete();
                } else {
                    console.log('[Google Maps Address Search] Google Maps failed to load, showing error');
                    this.showMapError();
                }
            }, 5000);
        }
    }

    initializeMap() {
        const mapContainer = document.getElementById('enhanced-location-map');
        const loadingElement = document.getElementById('map-loading');

        loadingElement.style.display = 'none';

        this.map = new google.maps.Map(mapContainer, {
            center: this.defaultCenter,
            zoom: 13,
            mapTypeControl: true,
            streetViewControl: true,
            fullscreenControl: false,
            zoomControl: true
        });

        // Click to drop pin
        this.map.addListener('click', (event) => {
            this.dropPin(event.latLng);
        });
    }

    initializeAutocomplete() {
        const addressInput = document.getElementById('location-address-input');

        this.autocomplete = new google.maps.places.Autocomplete(addressInput, {
            componentRestrictions: { country: 'za' }, // South Africa
            fields: ['place_id', 'geometry', 'name', 'formatted_address', 'address_components']
        });

        // Bind to map bounds
        if (this.map) {
            this.autocomplete.bindTo('bounds', this.map);
        }

        // Handle place selection
        this.autocomplete.addListener('place_changed', () => {
            const place = this.autocomplete.getPlace();
            if (place.geometry) {
                this.selectPlace(place);
            }
        });
    }

    selectPlace(place) {
        const location = place.geometry.location;
        const address = place.formatted_address || place.name;

        // Center map and zoom in
        this.map.setCenter(location);
        this.map.setZoom(16);

        // Drop pin at location
        this.dropPin(location, address);

        // Update input field
        document.getElementById('location-address-input').value = address;
    }

    dropPin(latLng, address = null) {
        // Remove existing marker
        if (this.marker) {
            this.marker.setMap(null);
        }

        // Get coordinates
        const lat = typeof latLng.lat === 'function' ? latLng.lat() : latLng.lat;
        const lng = typeof latLng.lng === 'function' ? latLng.lng() : latLng.lng;

        // Create new marker
        this.marker = new google.maps.Marker({
            position: { lat, lng },
            map: this.map,
            animation: google.maps.Animation.DROP,
            title: 'Selected Location'
        });

        // Store location data
        this.currentLocation = {
            lat: lat,
            lng: lng,
            address: address
        };

        // Update coordinates display
        document.getElementById('location-coordinates').textContent = 
            `📍 ${lat.toFixed(6)}, ${lng.toFixed(6)}`;

        // Enable save button
        document.getElementById('save-location-btn').disabled = false;

        // Get address if not provided
        if (!address) {
            this.reverseGeocode(lat, lng);
        }

        // Add click listener to marker
        this.marker.addListener('click', () => {
            this.showMarkerInfo();
        });
    }

    reverseGeocode(lat, lng) {
        const geocoder = new google.maps.Geocoder();
        geocoder.geocode({ location: { lat, lng } }, (results, status) => {
            if (status === 'OK' && results[0]) {
                const address = results[0].formatted_address;
                this.currentLocation.address = address;
                document.getElementById('location-address-input').value = address;
            }
        });
    }

    getCurrentLocation() {
        const button = document.getElementById('use-current-location-btn');
        const originalContent = button.innerHTML;

        button.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Finding...';
        button.disabled = true;

        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                (position) => {
                    const location = {
                        lat: position.coords.latitude,
                        lng: position.coords.longitude
                    };

                    // Center map and drop pin
                    this.map.setCenter(location);
                    this.map.setZoom(17);
                    this.dropPin(location);

                    // Reset button
                    button.innerHTML = originalContent;
                    button.disabled = false;
                },
                (error) => {
                    console.error('Geolocation error:', error);
                    this.showLocationError('Could not get your location. Please ensure location access is enabled.');

                    // Reset button
                    button.innerHTML = originalContent;
                    button.disabled = false;
                },
                {
                    enableHighAccuracy: true,
                    timeout: 10000,
                    maximumAge: 300000
                }
            );
        } else {
            this.showLocationError('Geolocation is not supported by this browser.');
            button.innerHTML = originalContent;
            button.disabled = false;
        }
    }

    clearLocation() {
        // Clear input
        document.getElementById('location-address-input').value = '';

        // Remove marker
        if (this.marker) {
            this.marker.setMap(null);
            this.marker = null;
        }

        // Clear location data
        this.currentLocation = null;

        // Reset displays
        document.getElementById('location-coordinates').textContent = 'Click on map to drop pin';
        document.getElementById('save-location-btn').disabled = true;

        // Hide saved location display
        this.hideSavedLocation();

        // Reset map to default center
        if (this.map) {
            this.map.setCenter(this.defaultCenter);
            this.map.setZoom(13);
        }
    }

    saveLocation() {
        if (!this.currentLocation) {
            this.showLocationError('No location selected to save.');
            return;
        }

        const locationData = {
            ...this.currentLocation,
            coordinates: `${this.currentLocation.lat.toFixed(6)}, ${this.currentLocation.lng.toFixed(6)}`,
            timestamp: new Date().toISOString()
        };

        this.showSavedLocation(locationData);
        this.onLocationSelect(locationData);
    }

    showSavedLocation(locationData) {
        const savedSection = document.getElementById('saved-location-display');
        const savedText = document.getElementById('saved-location-text');

        savedText.innerHTML = `
            <div>${locationData.address || locationData.coordinates}</div>
            <div class="text-muted">${locationData.coordinates}</div>
        `;

        // Show saved confirmation but keep map visible
        savedSection.style.display = 'block';

        // Update save button text to show saved status
        const saveBtn = document.getElementById('save-location-btn');
        const originalText = saveBtn.innerHTML;
        saveBtn.innerHTML = '<i class="fas fa-check"></i> Location Saved!';
        saveBtn.classList.replace('btn-primary', 'btn-success');

        // Reset button after 2 seconds
        setTimeout(() => {
            saveBtn.innerHTML = originalText;
            saveBtn.classList.replace('btn-success', 'btn-primary');
        }, 2000);
    }

    showEditMode() {
        // Show input/map sections and hide saved section only if user wants to edit
        document.querySelector('.address-input-section').style.display = 'block';
        document.querySelector('.map-section').style.display = 'block';
        // Keep saved location visible if it exists, just allow editing alongside it
        if (!this.currentLocation) {
            document.getElementById('saved-location-display').style.display = 'none';
        }
    }

    hideSavedLocation() {
        document.getElementById('saved-location-display').style.display = 'none';
        document.querySelector('.address-input-section').style.display = 'block';
        document.querySelector('.map-section').style.display = 'block';
    }

    navigateToLocation() {
        if (this.currentLocation) {
            const url = `https://www.google.com/maps/dir/?api=1&destination=${this.currentLocation.lat},${this.currentLocation.lng}`;
            window.open(url, '_blank');
        }
    }

    showMarkerInfo() {
        if (this.currentLocation && this.marker) {
            const infoWindow = new google.maps.InfoWindow({
                content: `
                    <div style="padding: 10px;">
                        <strong>Selected Location</strong><br>
                        <small>${this.currentLocation.address || 'Custom Location'}</small><br>
                        <small class="text-muted">${this.currentLocation.lat.toFixed(6)}, ${this.currentLocation.lng.toFixed(6)}</small><br>
                        <button onclick="window.open('https://www.google.com/maps/dir/?api=1&destination=${this.currentLocation.lat},${this.currentLocation.lng}', '_blank')" 
                                class="btn btn-sm btn-primary mt-2">
                            <i class="fas fa-directions"></i> Navigate
                        </button>
                    </div>
                `
            });
            infoWindow.open(this.map, this.marker);
        }
    }

    showLocationError(message) {
        // Create temporary error alert
        const errorAlert = document.createElement('div');
        errorAlert.className = 'alert alert-warning alert-dismissible fade show mt-2';
        errorAlert.innerHTML = `
            <i class="fas fa-exclamation-triangle"></i> ${message}
            <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
        `;

        this.container.appendChild(errorAlert);

        // Auto-remove after 5 seconds
        setTimeout(() => {
            if (errorAlert.parentNode) {
                errorAlert.remove();
            }
        }, 5000);
    }

    showMapError() {
        document.getElementById('enhanced-location-map').innerHTML = `
            <div class="d-flex justify-content-center align-items-center h-100 bg-light">
                <div class="text-center">
                    <i class="fas fa-exclamation-circle fa-2x text-warning mb-2"></i>
                    <div>Map temporarily unavailable</div>
                    <small class="text-muted">Use "My Location" for GPS positioning</small>
                </div>
            </div>
        `;
    }

    // Public methods for external use
    loadSavedLocation(locationData) {
        if (locationData && locationData.lat && locationData.lng) {
            this.currentLocation = locationData;

            if (this.map) {
                this.map.setCenter({ lat: locationData.lat, lng: locationData.lng });
                this.map.setZoom(16);
                this.dropPin({ lat: locationData.lat, lng: locationData.lng }, locationData.address);
            }

            if (locationData.address) {
                document.getElementById('location-address-input').value = locationData.address;
            }

            this.showSavedLocation(locationData);
        }
    }

    getLocationData() {
        return this.currentLocation;
    }
}

frontend/src/components/CustomerFormFull.content:
import { useState, useEffect } from 'react';
import {
  Stack,
  Text,
  TextField,
  Dropdown,
  Checkbox,
  MessageBar,
  MessageBarType,
  DefaultButton,
  CommandBar,
  PrimaryButton,
} from '@fluentui/react';
import type { IDropdownOption, ICommandBarItemProps } from '@fluentui/react';
import { customerService, companyService } from '../services';
import type { Customer, CreateCustomerDto, UpdateCustomerDto, Company } from '../types';

interface CustomerFormFullScreenProps {
  customer?: Customer;
  onDismiss: () => void;
  onSave: () => void;
  onDelete?: () => void;
}

export const CustomerFormFullScreen = ({
  customer,
  onDismiss,
  onSave,
  onDelete,
}: CustomerFormFullScreenProps) => {
  const [activeTab, setActiveTab] = useState<string>('basic');
  const [formData, setFormData] = useState<Partial<CreateCustomerDto>>({
    accountNo: '',
    accountName: '',
    companyTypeId: undefined,
    email: '',
    phone: '',
    mobile: '',
    website: '',
    vatRegistrationNo: '',
    companyRegistrationNo: '',
    streetAddress: '',
    city: '',
    province: '',
    postalCode: '',
    country: 'South Africa',
    latitude: null,
    longitude: null,
    customerStatus: 'Prospect',
    paymentTerms: 'Net 30',
    creditLimit: 0,
    currentBalance: 0,
    discount: 0,
    taxExempt: false,
    isActive: true,
  });
  const [companyTypes, setCompanyTypes] = useState<Company[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [mapInitialized, setMapInitialized] = useState(false);
  const [map, setMap] = useState<google.maps.Map | null>(null);
  const [marker, setMarker] = useState<google.maps.Marker | null>(null);
  const [autocomplete, setAutocomplete] = useState<google.maps.places.Autocomplete | null>(null);

  useEffect(() => {
    loadCompanyTypes();
    initializeGoogleMaps();
  }, []);

  useEffect(() => {
    if (customer) {
      setFormData({
        accountNo: customer.accountNo,
        accountName: customer.accountName,
        companyTypeId: customer.companyTypeId || undefined,
        email: customer.email || '',
        phone: customer.phone || '',
        mobile: customer.mobile || '',
        website: customer.website || '',
        vatRegistrationNo: customer.vatRegistrationNo || '',
        companyRegistrationNo: customer.companyRegistrationNo || '',
        streetAddress: customer.streetAddress || '',
        city: customer.city || '',
        province: customer.province || '',
        postalCode: customer.postalCode || '',
        country: customer.country || 'South Africa',
        latitude: customer.latitude,
        longitude: customer.longitude,
        customerStatus: customer.customerStatus,
        paymentTerms: customer.paymentTerms || 'Net 30',
        creditLimit: customer.creditLimit || 0,
        currentBalance: customer.currentBalance || 0,
        discount: customer.discount || 0,
        taxExempt: customer.taxExempt || false,
        isActive: customer.isActive,
      });

      if (customer.latitude && customer.longitude && map) {
        const position = { lat: customer.latitude, lng: customer.longitude };
        map.setCenter(position);
        if (marker) {
          marker.setPosition(position);
        }
      }
    }
    setError(null);
  }, [customer, map, marker]);

  const loadCompanyTypes = async () => {
    try {
      const data = await companyService.getAll(true);
      setCompanyTypes(data);
    } catch (err) {
      console.error('Failed to load company types:', err);
    }
  };

  const initializeGoogleMaps = () => {
    if (typeof google === 'undefined' || !google.maps) {
      const script = document.createElement('script');
      script.src = `https://maps.googleapis.com/maps/api/js?key=${
        import.meta.env.VITE_GOOGLE_MAPS_API_KEY || ''
      }&libraries=places`;
      script.async = true;
      script.onload = () => setupMap();
      document.head.appendChild(script);
    } else {
      setupMap();
    }
  };

  const setupMap = () => {
    const mapElement = document.getElementById('customer-map');
    if (!mapElement) {
      setTimeout(setupMap, 100);
      return;
    }

    const defaultCenter = { lat: -26.2041, lng: 28.0473 };
    const mapInstance = new google.maps.Map(mapElement, {
      center: defaultCenter,
      zoom: 12,
      mapTypeControl: true,
      streetViewControl: true,
      fullscreenControl: true,
    });

    const markerInstance = new google.maps.Marker({
      map: mapInstance,
      draggable: true,
      position: defaultCenter,
    });

    markerInstance.addListener('dragend', () => {
      const position = markerInstance.getPosition();
      if (position) {
        setFormData({
          ...formData,
          latitude: position.lat(),
          longitude: position.lng(),
        });
      }
    });

    const input = document.getElementById('address-autocomplete') as HTMLInputElement;
    if (input) {
      const autocompleteInstance = new google.maps.places.Autocomplete(input, {
        componentRestrictions: { country: 'za' },
        fields: ['address_components', 'geometry', 'formatted_address'],
      });

      autocompleteInstance.addListener('place_changed', () => {
        const place = autocompleteInstance.getPlace();
        if (place.geometry?.location) {
          const position = place.geometry.location;
          mapInstance.setCenter(position);
          mapInstance.setZoom(15);
          markerInstance.setPosition(position);

          setFormData({
            ...formData,
            streetAddress: place.formatted_address || '',
            latitude: position.lat(),
            longitude: position.lng(),
          });

          if (place.address_components) {
            const components = place.address_components;
            const city = components.find((c) => c.types.includes('locality'))?.long_name;
            const province = components.find((c) =>
              c.types.includes('administrative_area_level_1')
            )?.long_name;
            const postalCode = components.find((c) => c.types.includes('postal_code'))?.long_name;

            setFormData((prev) => ({
              ...prev,
              city: city || prev.city || '',
              province: province || prev.province || '',
              postalCode: postalCode || prev.postalCode || '',
            }));
          }

          input.value = '';
        }
      });

      setAutocomplete(autocompleteInstance);
    }

    setMap(mapInstance);
    setMarker(markerInstance);
    setMapInitialized(true);
  };

  const handleUseMyLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const pos = {
            lat: position.coords.latitude,
            lng: position.coords.longitude,
          };

          if (map) {
            map.setCenter(pos);
          }
          if (marker) {
            marker.setPosition(pos);
          }

          setFormData({
            ...formData,
            latitude: pos.lat,
            longitude: pos.lng,
          });
        },
        () => {
          setError('Failed to get your location');
        }
      );
    }
  };

  const companyTypeOptions: IDropdownOption[] = [
    { key: '', text: '(None)' },
    ...companyTypes.map((ct) => ({ key: ct.id, text: ct.name })),
  ];

  const statusOptions: IDropdownOption[] = [
    { key: 'Prospect', text: 'Prospect' },
    { key: 'Active', text: 'Active' },
    { key: 'Credit Approved', text: 'Credit Approved' },
    { key: 'On Hold', text: 'On Hold' },
    { key: 'Inactive', text: 'Inactive' },
  ];

  const handleSubmit = async () => {
    try {
      setSaving(true);
      setError(null);

      if (customer) {
        const updateDto: UpdateCustomerDto = { ...formData };
        await customerService.update(customer.id, updateDto);
      } else {
        const createDto: CreateCustomerDto = formData as CreateCustomerDto;
        await customerService.create(createDto);
      }

      onSave();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save customer');
      setSaving(false);
    }
  };

  const handleSaveAndNew = async () => {
    try {
      setSaving(true);
      setError(null);

      if (customer) {
        const updateDto: UpdateCustomerDto = { ...formData };
        await customerService.update(customer.id, updateDto);
      } else {
        const createDto: CreateCustomerDto = formData as CreateCustomerDto;
        await customerService.create(createDto);
      }

      setFormData({
        accountNo: '',
        accountName: '',
        companyTypeId: undefined,
        email: '',
        phone: '',
        mobile: '',
        website: '',
        vatRegistrationNo: '',
        companyRegistrationNo: '',
        streetAddress: '',
        city: '',
        province: '',
        postalCode: '',
        country: 'South Africa',
        latitude: null,
        longitude: null,
        customerStatus: 'Prospect',
        paymentTerms: 'Net 30',
        creditLimit: 0,
        currentBalance: 0,
        discount: 0,
        taxExempt: false,
        isActive: true,
      });
      setSaving(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save customer');
      setSaving(false);
    }
  };

  const commandBarItems: ICommandBarItemProps[] = [
    {
      key: 'save',
      text: 'Save',
      iconProps: { iconName: 'Save' },
      onClick: handleSubmit,
      disabled: saving,
    },
    {
      key: 'saveAndNew',
      text: 'Save & New',
      iconProps: { iconName: 'SaveAndClose' },
      onClick: handleSaveAndNew,
      disabled: saving,
    },
    ...(customer && onDelete
      ? [
          {
            key: 'delete',
            text: 'Delete',
            iconProps: { iconName: 'Delete' },
            onClick: onDelete,
            disabled: saving,
          },
        ]
      : []),
    {
      key: 'cancel',
      text: 'Cancel',
      iconProps: { iconName: 'Cancel' },
      onClick: onDismiss,
      disabled: saving,
    },
  ];

  return (
    <Stack tokens={{ childrenGap: 16 }} styles={{ root: { height: '100%' } }}>
      <Text variant="xxLarge" styles={{ root: { padding: '20px 20px 0 20px' } }}>
        {customer ? 'Edit Customer' : 'New Customer'}
      </Text>

      <CommandBar items={commandBarItems} />

      <Stack styles={{ root: { flex: 1, overflowY: 'auto', padding: '0 20px 20px 20px' } }}>
        {error && (
          <MessageBar messageBarType={MessageBarType.error} onDismiss={() => setError(null)}>
            {error}
          </MessageBar>
        )}

      <Stack styles={{ root: { flex: 1, display: 'flex', flexDirection: 'column' } }}>
        {/* Horizontal Tabs */}
        <Stack horizontal styles={{ root: { borderBottom: '1px solid #edebe9' } }}>
          <DefaultButton
            text="Basic Information"
            iconProps={{ iconName: 'Info' }}
            onClick={() => setActiveTab('basic')}
            styles={{
              root: {
                height: 48,
                padding: '0 24px',
                borderRadius: 0,
                border: 'none',
                backgroundColor: activeTab === 'basic' ? '#0078d4' : 'transparent',
                color: activeTab === 'basic' ? 'white' : '#323130',
                fontWeight: activeTab === 'basic' ? 600 : 400,
              },
              rootHovered: {
                backgroundColor: activeTab === 'basic' ? '#106ebe' : '#f3f2f1',
                color: activeTab === 'basic' ? 'white' : '#323130',
              },
            }}
          />
          <DefaultButton
            text="Contact Information"
            iconProps={{ iconName: 'Contact' }}
            onClick={() => setActiveTab('contact')}
            styles={{
              root: {
                height: 48,
                padding: '0 24px',
                borderRadius: 0,
                border: 'none',
                backgroundColor: activeTab === 'contact' ? '#0078d4' : 'transparent',
                color: activeTab === 'contact' ? 'white' : '#323130',
                fontWeight: activeTab === 'contact' ? 600 : 400,
              },
              rootHovered: {
                backgroundColor: activeTab === 'contact' ? '#106ebe' : '#f3f2f1',
                color: activeTab === 'contact' ? 'white' : '#323130',
              },
            }}
          />
          <DefaultButton
            text="Address & Location"
            iconProps={{ iconName: 'MapPin' }}
            onClick={() => setActiveTab('address')}
            styles={{
              root: {
                height: 48,
                padding: '0 24px',
                borderRadius: 0,
                border: 'none',
                backgroundColor: activeTab === 'address' ? '#0078d4' : 'transparent',
                color: activeTab === 'address' ? 'white' : '#323130',
                fontWeight: activeTab === 'address' ? 600 : 400,
              },
              rootHovered: {
                backgroundColor: activeTab === 'address' ? '#106ebe' : '#f3f2f1',
                color: activeTab === 'address' ? 'white' : '#323130',
              },
            }}
          />
          <DefaultButton
            text="Financial Information"
            iconProps={{ iconName: 'Money' }}
            onClick={() => setActiveTab('financial')}
            styles={{
              root: {
                height: 48,
                padding: '0 24px',
                borderRadius: 0,
                border: 'none',
                backgroundColor: activeTab === 'financial' ? '#0078d4' : 'transparent',
                color: activeTab === 'financial' ? 'white' : '#323130',
                fontWeight: activeTab === 'financial' ? 600 : 400,
              },
              rootHovered: {
                backgroundColor: activeTab === 'financial' ? '#106ebe' : '#f3f2f1',
                color: activeTab === 'financial' ? 'white' : '#323130',
              },
            }}
          />
        </Stack>

        {/* Tab Content */}
        <Stack styles={{ root: { flex: 1, overflowY: 'auto', padding: '20px 0' } }}>
          {activeTab === 'basic' && (
          <Stack
            horizontal
            tokens={{ childrenGap: 32 }}
            styles={{ root: { marginTop: 16, overflowY: 'auto' } }}
          >
            <Stack tokens={{ childrenGap: 16 }} styles={{ root: { flex: 1 } }}>
              <TextField
                label="Account No"
                required
                value={formData.accountNo}
                onChange={(_, value) => setFormData({ ...formData, accountNo: value || '' })}
              />

              <TextField
                label="Account Name"
                required
                value={formData.accountName}
                onChange={(_, value) => setFormData({ ...formData, accountName: value || '' })}
              />

              <Dropdown
                label="Company Type"
                options={companyTypeOptions}
                selectedKey={formData.companyTypeId || ''}
                onChange={(_, option) =>
                  setFormData({
                    ...formData,
                    companyTypeId: option?.key ? Number(option.key) : undefined,
                  })
                }
              />

              <TextField
                label="VAT Registration No"
                value={formData.vatRegistrationNo}
                onChange={(_, value) =>
                  setFormData({ ...formData, vatRegistrationNo: value || '' })
                }
              />

              <TextField
                label="Company Registration No"
                value={formData.companyRegistrationNo}
                onChange={(_, value) =>
                  setFormData({ ...formData, companyRegistrationNo: value || '' })
                }
              />
            </Stack>

            <Stack tokens={{ childrenGap: 16 }} styles={{ root: { flex: 1 } }}>
              <Dropdown
                label="Customer Status"
                required
                options={statusOptions}
                selectedKey={formData.customerStatus}
                onChange={(_, option) =>
                  setFormData({ ...formData, customerStatus: option?.key as string })
                }
              />

              <TextField
                label="Payment Terms"
                value={formData.paymentTerms}
                onChange={(_, value) => setFormData({ ...formData, paymentTerms: value || '' })}
              />

              <TextField
                label="Credit Limit"
                type="number"
                value={String(formData.creditLimit)}
                onChange={(_, value) =>
                  setFormData({ ...formData, creditLimit: Number(value) || 0 })
                }
              />

              <TextField
                label="Discount %"
                type="number"
                value={String(formData.discount)}
                onChange={(_, value) => setFormData({ ...formData, discount: Number(value) || 0 })}
              />

              <Checkbox
                label="Tax Exempt"
                checked={formData.taxExempt}
                onChange={(_, checked) => setFormData({ ...formData, taxExempt: checked || false })}
              />

              <Checkbox
                label="Active"
                checked={formData.isActive}
                onChange={(_, checked) => setFormData({ ...formData, isActive: checked || false })}
              />
            </Stack>
          </Stack>
          )}

          {activeTab === 'contact' && (
          <Stack tokens={{ childrenGap: 16 }} styles={{ root: { marginTop: 16, maxWidth: 600 } }}>
            <TextField
              label="Email"
              required
              type="email"
              value={formData.email}
              onChange={(_, value) => setFormData({ ...formData, email: value || '' })}
            />

            <TextField
              label="Phone"
              required
              value={formData.phone}
              onChange={(_, value) => setFormData({ ...formData, phone: value || '' })}
            />

            <TextField
              label="Mobile"
              value={formData.mobile}
              onChange={(_, value) => setFormData({ ...formData, mobile: value || '' })}
            />

            <TextField
              label="Website"
              value={formData.website}
              onChange={(_, value) => setFormData({ ...formData, website: value || '' })}
            />
          </Stack>
          )}

          {activeTab === 'address' && (
          <Stack tokens={{ childrenGap: 16 }} styles={{ root: { marginTop: 16 } }}>
            <Stack horizontal tokens={{ childrenGap: 8 }} verticalAlign="end">
              <TextField
                id="address-autocomplete"
                label="Search Address"
                placeholder="Start typing an address..."
                styles={{ root: { flex: 1 } }}
              />
              <DefaultButton
                text="Use My Location"
                iconProps={{ iconName: 'MyLocation' }}
                onClick={handleUseMyLocation}
              />
            </Stack>

            <div
              id="customer-map"
              style={{
                height: '400px',
                width: '100%',
                border: '1px solid #ccc',
                borderRadius: '4px',
              }}
            />

            <Stack horizontal tokens={{ childrenGap: 16 }}>
              <Stack tokens={{ childrenGap: 16 }} styles={{ root: { flex: 1 } }}>
                <TextField
                  label="Street Address"
                  required
                  multiline
                  rows={2}
                  value={formData.streetAddress}
                  onChange={(_, value) => setFormData({ ...formData, streetAddress: value || '' })}
                />

                <TextField
                  label="City"
                  required
                  value={formData.city}
                  onChange={(_, value) => setFormData({ ...formData, city: value || '' })}
                />
              </Stack>

              <Stack tokens={{ childrenGap: 16 }} styles={{ root: { flex: 1 } }}>
                <TextField
                  label="Province"
                  required
                  value={formData.province}
                  onChange={(_, value) => setFormData({ ...formData, province: value || '' })}
                />

                <TextField
                  label="Postal Code"
                  required
                  value={formData.postalCode}
                  onChange={(_, value) => setFormData({ ...formData, postalCode: value || '' })}
                />
              </Stack>
            </Stack>

            <TextField
              label="Country"
              required
              value={formData.country}
              onChange={(_, value) => setFormData({ ...formData, country: value || '' })}
            />

            {formData.latitude && formData.longitude && (
              <Text variant="small">
                Coordinates: {formData.latitude.toFixed(6)}, {formData.longitude.toFixed(6)}
              </Text>
            )}
          </Stack>
          )}

          {activeTab === 'financial' && (
          <Stack
            tokens={{ childrenGap: 16 }}
            styles={{ root: { marginTop: 16, maxWidth: 600 } }}
          >
            <TextField
              label="Current Balance"
              type="number"
              value={String(formData.currentBalance)}
              onChange={(_, value) =>
                setFormData({ ...formData, currentBalance: Number(value) || 0 })
              }
              prefix="ZAR"
            />

            <TextField
              label="Credit Limit"
              type="number"
              value={String(formData.creditLimit)}
              onChange={(_, value) =>
                setFormData({ ...formData, creditLimit: Number(value) || 0 })
              }
              prefix="ZAR"
            />

            <TextField
              label="Discount %"
              type="number"
              value={String(formData.discount)}
              onChange={(_, value) => setFormData({ ...formData, discount: Number(value) || 0 })}
            />

            <TextField
              label="Payment Terms"
              value={formData.paymentTerms}
              onChange={(_, value) => setFormData({ ...formData, paymentTerms: value || '' })}
            />

            <Checkbox
              label="Tax Exempt"
              checked={formData.taxExempt}
              onChange={(_, checked) => setFormData({ ...formData, taxExempt: checked || false })}
            />
          </Stack>
          )}
        </Stack>
      </Stack>
    </Stack>
    </Stack>
  );
};

frontend/src/services/userService.ts.content:
import { api } from './api';
import type { User, CreateUserDto, UpdateUserDto } from '../types';

export const userService = {
  getAll: () => api.get<User[]>('/users'),

  getById: (id: number) => api.get<User>(`/users/${id}`),

  create: (data: CreateUserDto) => api.post<User>('/users', data),

  update: (id: number, data: UpdateUserDto) => api.put<User>(`/users/${id}`, data),

  delete: (id: number) => api.delete(`/users/${id}`),
};

