        return CreatedAtAction(nameof(GetById), new { id = tender.Id }, MapToDto(tender));
    }

    [HttpPut("{id}")]
    public async Task<ActionResult<TenderDto>> Update(Guid id, [FromBody] UpdateTenderDto updateDto)
