    api.get<LookupOption[]>('/lookups/accounts/recent'),

  getRecentEmployees: () => 
    api.get<LookupOption[]>('/lookups/employees/recent'),

  getRecentContacts: () => 
    api.get<LookupOption[]>('/lookups/contacts/recent'),
};

