import { useState, useEffect } from 'react';
import {
  Stack,
  Text,
  TextField,
  Checkbox,
  MessageBar,
  MessageBarType,
  DefaultButton,
  CommandBar,
  DatePicker,
  Dropdown,
} from '@fluentui/react';
import type { ICommandBarItemProps, IDropdownOption } from '@fluentui/react';
import { productionService, customerService, pickingTeamService, sawService, jigService } from '../services';
import type { Production, Customer, PickingTeam, Saw, Jig } from '../types/millennium';

interface ProductionFormProps {
  production?: Production;
  onDismiss: () => void;
  onSave: () => void;
  onDelete?: () => void;
}

export const ProductionForm = ({
  production,
  onDismiss,
  onSave,
  onDelete,
}: ProductionFormProps) => {
  const [activeTab, setActiveTab] = useState<string>('basic');
  const [formData, setFormData] = useState<Partial<Production>>({
    name: '',
    customer: '',
    orderNo: '',
    jigStart: '',
    jigEnd: '',
    jigLeader: '',
    jigHelper1: '',
    jigHelper2: '',
    jigHelper3: '',
    jigHelper4: '',
    pickStart: '',
    pickEnd: '',
    pickingMaster: '',
    pickingHelper1: '',
    pickingHelper2: '',
    pickingHelper3: '',
    sawStart: '',
    sawEnd: '',
    sawOperator: '',
    sawHelper1: '',
    sawHelper2: '',
    productionComplete: false,
    productionPlannedDate: '',
    totalCuts: 0,
    totalTimberCubes: 0,
    trussCost: 0,
    trussSelling: 0,
    workUnitsEfinks: 0,
    newEstimateDefinks: 0,
    pickingTeamId: null,
    sawId: null,
    jigId: null,
  });
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [pickingTeams, setPickingTeams] = useState<PickingTeam[]>([]);
  const [saws, setSaws] = useState<Saw[]>([]);
  const [jigs, setJigs] = useState<Jig[]>([]);

  useEffect(() => {
    loadCustomers();
    loadPickingTeams();
    loadSaws();
    loadJigs();
  }, []);

  const loadCustomers = async () => {
    try {
      const data = await customerService.getAll();
      setCustomers(data);
    } catch (err) {
      console.error('Failed to load customers:', err);
    }
  };

  const loadPickingTeams = async () => {
    try {
      const data = await pickingTeamService.getAll();
      setPickingTeams(data);
    } catch (err) {
      console.error('Failed to load picking teams:', err);
    }
  };

  const loadSaws = async () => {
    try {
      const data = await sawService.getAll();
      setSaws(data);
    } catch (err) {
      console.error('Failed to load saws:', err);
    }
  };

  const loadJigs = async () => {
    try {
      const data = await jigService.getAll();
      setJigs(data);
    } catch (err) {
      console.error('Failed to load jigs:', err);
    }
  };

  const customerOptions: IDropdownOption[] = [
    { key: '', text: '(None)' },
    ...customers.map((c) => ({ key: c.id, text: c.accountName })),
  ];

  const pickingTeamOptions: IDropdownOption[] = [
    { key: '', text: '(None)' },
    ...pickingTeams.map((pt) => ({ key: pt.id, text: pt.name })),
  ];

  const sawOptions: IDropdownOption[] = [
    { key: '', text: '(None)' },
    ...saws.map((s) => ({ key: s.id, text: s.name })),
  ];

  const jigOptions: IDropdownOption[] = [
    { key: '', text: '(None)' },
    ...jigs.map((j) => ({ key: j.id, text: j.name })),
  ];

  useEffect(() => {
    if (production) {
      setFormData({
        name: production.name || '',
        customer: production.customer || '',
        orderNo: production.orderNo || '',
        jigStart: production.jigStart || '',
        jigEnd: production.jigEnd || '',
        jigLeader: production.jigLeader || '',
        jigHelper1: production.jigHelper1 || '',
        jigHelper2: production.jigHelper2 || '',
        jigHelper3: production.jigHelper3 || '',
        jigHelper4: production.jigHelper4 || '',
        pickStart: production.pickStart || '',
        pickEnd: production.pickEnd || '',
        pickingMaster: production.pickingMaster || '',
        pickingHelper1: production.pickingHelper1 || '',
        pickingHelper2: production.pickingHelper2 || '',
        pickingHelper3: production.pickingHelper3 || '',
        sawStart: production.sawStart || '',
        sawEnd: production.sawEnd || '',
        sawOperator: production.sawOperator || '',
        sawHelper1: production.sawHelper1 || '',
        sawHelper2: production.sawHelper2 || '',
        productionComplete: production.productionComplete || false,
        productionPlannedDate: production.productionPlannedDate || '',
        totalCuts: production.totalCuts || 0,
        totalTimberCubes: production.totalTimberCubes || 0,
        trussCost: production.trussCost || 0,
        trussSelling: production.trussSelling || 0,
        workUnitsEfinks: production.workUnitsEfinks || 0,
        newEstimateDefinks: production.newEstimateDefinks || 0,
        pickingTeamId: production.pickingTeamId || null,
        sawId: production.sawId || null,
        jigId: production.jigId || null,
      });
    }
    setError(null);
  }, [production]);

  const handleSubmit = async () => {
    try {
      setSaving(true);
      setError(null);

      if (production) {
        await productionService.update(production.id, formData);
      } else {
        await productionService.create(formData);
      }

      onSave();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save production');
      setSaving(false);
    }
  };

  const handleSaveAndNew = async () => {
    try {
      setSaving(true);
      setError(null);

      if (production) {
        await productionService.update(production.id, formData);
      } else {
        await productionService.create(formData);
      }

      setFormData({
        name: '',
        customer: '',
        orderNo: '',
        jigStart: '',
        jigEnd: '',
        jigLeader: '',
        jigHelper1: '',
        jigHelper2: '',
        jigHelper3: '',
        jigHelper4: '',
        pickStart: '',
        pickEnd: '',
        pickingMaster: '',
        pickingHelper1: '',
        pickingHelper2: '',
        pickingHelper3: '',
        sawStart: '',
        sawEnd: '',
        sawOperator: '',
        sawHelper1: '',
        sawHelper2: '',
        productionComplete: false,
        productionPlannedDate: '',
        totalCuts: 0,
        totalTimberCubes: 0,
        trussCost: 0,
        trussSelling: 0,
        workUnitsEfinks: 0,
        newEstimateDefinks: 0,
        pickingTeamId: null,
        sawId: null,
        jigId: null,
      });
      setSaving(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save production');
      setSaving(false);
    }
  };

  const commandBarItems: ICommandBarItemProps[] = [
    {
      key: 'save',
      text: 'Save',
      iconProps: { iconName: 'Save' },
      onClick: handleSubmit,
      disabled: saving,
    },
    {
      key: 'saveAndNew',
      text: 'Save & New',
      iconProps: { iconName: 'SaveAndClose' },
      onClick: handleSaveAndNew,
      disabled: saving,
    },
    ...(production && onDelete
      ? [
          {
            key: 'delete',
            text: 'Delete',
            iconProps: { iconName: 'Delete' },
            onClick: onDelete,
            disabled: saving,
          },
        ]
