            RequestDeliveryBy = quote.RequestDeliveryBy,

            // Reference Fields
            OpportunityId = quote.OpportunityId,
            PriceLevelId = quote.PriceLevelId,
            TransactionCurrencyId = quote.TransactionCurrencyId,

            // Contact Information
            ContactName = quote.ContactName,
