  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [contactToDelete, setContactToDelete] = useState<D365Contact | undefined>();
  const [searchText, setSearchText] = useState('');
  const [isColumnPanelOpen, setIsColumnPanelOpen] = useState(false);
  const [isExportDialogOpen, setIsExportDialogOpen] = useState(false);
  const [isFilterBuilderOpen, setIsFilterBuilderOpen] = useState(false);
  const [sortColumn, setSortColumn] = useState<string>('');
  const [isSortedDescending, setIsSortedDescending] = useState(false);

  const {
    currentPage,
    pageSize,
    paginatedItems: paginatedContacts,
    setCurrentPage,
    setPageSize,
  } = usePagination({ items: filteredContacts, initialPageSize: 50 });

  const defaultVisibleColumns: { [key: string]: boolean } = {
    fullName: true,
    emailAddress1: true,
    telephone1: true,
    mobilePhone: true,
    jobTitle: true,
    address1City: false,
    address1StateOrProvince: false,
    address1PostalCode: false,
    address1Country: false,
  };

  const defaultColumnOrder = [
    'fullName', 'emailAddress1', 'telephone1', 'mobilePhone', 'jobTitle',
    'address1City', 'address1StateOrProvince', 'address1PostalCode', 'address1Country'
  ];

  const defaultView: GridView = {
    id: 'default-view',
    name: 'All Contacts',
    isDefault: true,
    entityType: 'd365contact',
    columnVisibility: defaultVisibleColumns,
    columnOrder: defaultColumnOrder,
    filters: [],
  };

  const loadViews = (): GridView[] => {
    try {
      const saved = localStorage.getItem('d365contacts-views');
      if (saved) {
        const views = JSON.parse(saved);
        return views.length > 0 ? views : [defaultView];
      }
    } catch (err) {
      console.warn('Failed to load views:', err);
    }
    return [defaultView];
  };

  const [views, setViews] = useState<GridView[]>(loadViews());
  const [currentView, setCurrentView] = useState<GridView>(
    views.find(v => v.isDefault) || defaultView
  );

  const [selection] = useState(
    new Selection({
      onSelectionChanged: () => {
        const selected = selection.getSelection()[0] as D365Contact | undefined;
        setSelectedContact(selected);
      },
    })
  );

  useEffect(() => {
    loadContacts();
  }, []);

  useEffect(() => {
    applyFilters();
  }, [contacts, searchText, currentView, sortColumn, isSortedDescending]);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchText, currentView.filters, pageSize, setCurrentPage]);

  const loadContacts = async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await d365ContactService.getAll();
      setContacts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load contacts');
    } finally {
      setLoading(false);
    }
  };

  const applyFilters = () => {
    let filtered = [...contacts];

    if (searchText) {
      const search = searchText.toLowerCase();
      filtered = filtered.filter((contact) => {
        return Object.values(contact).some((value) =>
          String(value).toLowerCase().includes(search)
        );
      });
    }

    if (currentView.filters && currentView.filters.length > 0) {
      filtered = filtered.filter((contact) => {
        let result = true;
        let currentLogic: 'AND' | 'OR' = 'AND';

        for (let i = 0; i < currentView.filters.length; i++) {
          const filter = currentView.filters[i];
          const fieldValue = contact[filter.field as keyof D365Contact];
          const value = String(fieldValue ?? '').toLowerCase();
          const filterValue = filter.value.toLowerCase();

          let filterResult = false;
          switch (filter.operator) {
            case 'equals':
              filterResult = value === filterValue;
              break;
            case 'notEquals':
              filterResult = value !== filterValue;
              break;
            case 'contains':
              filterResult = value.includes(filterValue);
              break;
            case 'notContains':
              filterResult = !value.includes(filterValue);
              break;
            case 'beginsWith':
              filterResult = value.startsWith(filterValue);
              break;
            case 'endsWith':
              filterResult = value.endsWith(filterValue);
              break;
            case 'isEmpty':
              filterResult = !value;
              break;
            case 'isNotEmpty':
              filterResult = !!value;
              break;
            default:
              filterResult = true;
          }

          if (i === 0) {
            result = filterResult;
          } else {
            if (currentLogic === 'AND') {
              result = result && filterResult;
            } else {
              result = result || filterResult;
            }
          }

          currentLogic = filter.logicOperator || 'AND';
        }

        return result;
      });
    }

    if (sortColumn) {
      filtered.sort((a, b) => {
        let aValue: any = a[sortColumn as keyof D365Contact];
        let bValue: any = b[sortColumn as keyof D365Contact];

        if (aValue === undefined || aValue === null) {
          aValue = typeof bValue === 'boolean' ? false : typeof bValue === 'number' ? 0 : '';
        }
        if (bValue === undefined || bValue === null) {
          bValue = typeof aValue === 'boolean' ? false : typeof aValue === 'number' ? 0 : '';
        }

        let comparison = 0;
        if (typeof aValue === 'string' && typeof bValue === 'string') {
          comparison = aValue.localeCompare(bValue);
        } else if (typeof aValue === 'number' && typeof bValue === 'number') {
          comparison = aValue - bValue;
        } else if (typeof aValue === 'boolean' && typeof bValue === 'boolean') {
          comparison = (aValue ? 1 : 0) - (bValue ? 1 : 0);
        }

        if (comparison === 0 && sortColumn !== 'fullName') {
          const aName = a.fullName || '';
          const bName = b.fullName || '';
          comparison = aName.localeCompare(bName);
        }

        return isSortedDescending ? -comparison : comparison;
      });
    }

    setFilteredContacts(filtered);
  };

  const handleNew = () => {
    setSelectedContact(undefined);
    setIsFormOpen(true);
  };

  const handleEdit = () => {
    if (selectedContact) {
      setIsFormOpen(true);
    }
  };

  const handleRowDoubleClick = (contact: D365Contact) => {
    setSelectedContact(contact);
    setIsFormOpen(true);
  };

  const handleDelete = () => {
    if (selectedContact) {
      setContactToDelete(selectedContact);
      setIsDeleteDialogOpen(true);
    }
  };

  const confirmDelete = async () => {
    if (contactToDelete) {
      try {
        await d365ContactService.delete(contactToDelete.id);
        setIsDeleteDialogOpen(false);
        setContactToDelete(undefined);
        await loadContacts();
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to delete contact');
      }
    }
  };

  const exportToExcel = (contactsToExport: D365Contact[]) => {
    const exportData = contactsToExport.map((contact) => ({
      'Full Name': contact.fullName || '',
      'First Name': contact.firstName || '',
      'Last Name': contact.lastName || '',
      'Email': contact.emailAddress1 || '',
      'Phone': contact.telephone1 || '',
      'Mobile': contact.mobilePhone || '',
      'Job Title': contact.jobTitle || '',
      'City': contact.address1City || '',
      'State/Province': contact.address1StateOrProvince || '',
      'Postal Code': contact.address1PostalCode || '',
      'Country': contact.address1Country || '',
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Contacts');
    XLSX.writeFile(wb, `D365_Contacts_Export_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleExportSelected = () => {
    const selected = selection.getSelection() as D365Contact[];
    if (selected.length > 0) {
      exportToExcel(selected);
    }
    setIsExportDialogOpen(false);
  };

  const handleExportAll = () => {
    exportToExcel(filteredContacts);
    setIsExportDialogOpen(false);
  };

  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet);
        console.log('Imported data:', jsonData);
      } catch (err) {
        setError('Failed to import Excel file');
      }
    };
    reader.readAsBinaryString(file);
    event.target.value = '';
  };

  const handleViewChange = (view: GridView) => {
    setCurrentView(view);
  };

  const handleSaveView = (view: GridView) => {
    const updatedViews = views.find(v => v.id === view.id)
      ? views.map(v => v.id === view.id ? view : v)
      : [...views, view];

    setViews(updatedViews);
    setCurrentView(view);
    localStorage.setItem('d365contacts-views', JSON.stringify(updatedViews));
  };

  const handleDeleteView = (viewId: string) => {
    const updatedViews = views.filter(v => v.id !== viewId);
    setViews(updatedViews);
    localStorage.setItem('d365contacts-views', JSON.stringify(updatedViews));
  };

  const handleSetDefaultView = (viewId: string) => {
    const updatedViews = views.map(v => ({
      ...v,
      isDefault: v.id === viewId,
    }));
    setViews(updatedViews);
    localStorage.setItem('d365contacts-views', JSON.stringify(updatedViews));
  };

  const handleFiltersChange = (filters: GridFilter[]) => {
    const updatedView = { ...currentView, filters };
    setCurrentView(updatedView);
  };

  const updateCurrentViewColumns = (visibility: { [key: string]: boolean }, order: string[]) => {
    const updatedView = {
      ...currentView,
      columnVisibility: visibility,
      columnOrder: order,
    };
    setCurrentView(updatedView);
  };

  const moveColumnUp = (columnKey: string) => {
    const currentIndex = currentView.columnOrder.indexOf(columnKey);
    if (currentIndex > 0) {
      const newOrder = [...currentView.columnOrder];
      [newOrder[currentIndex - 1], newOrder[currentIndex]] = [newOrder[currentIndex], newOrder[currentIndex - 1]];
      updateCurrentViewColumns(currentView.columnVisibility, newOrder);
    }
  };

  const moveColumnDown = (columnKey: string) => {
    const currentIndex = currentView.columnOrder.indexOf(columnKey);
    if (currentIndex < currentView.columnOrder.length - 1) {
      const newOrder = [...currentView.columnOrder];
      [newOrder[currentIndex], newOrder[currentIndex + 1]] = [newOrder[currentIndex + 1], newOrder[currentIndex]];
      updateCurrentViewColumns(currentView.columnVisibility, newOrder);
    }
  };

  const onColumnClick = (_?: React.MouseEvent<HTMLElement>, column?: IColumn) => {
    if (!column) return;

    const columnKey = column.key;
    if (sortColumn === columnKey) {
      setIsSortedDescending(!isSortedDescending);
    } else {
      setSortColumn(columnKey);
      setIsSortedDescending(false);
    }
  };

  const availableFields = [
    { key: 'fullName', name: 'Full Name', type: 'text' as const },
    { key: 'firstName', name: 'First Name', type: 'text' as const },
    { key: 'lastName', name: 'Last Name', type: 'text' as const },
    { key: 'emailAddress1', name: 'Email', type: 'text' as const },
    { key: 'telephone1', name: 'Phone', type: 'text' as const },
    { key: 'mobilePhone', name: 'Mobile', type: 'text' as const },
    { key: 'jobTitle', name: 'Job Title', type: 'text' as const },
  ];

  const allColumns: IColumn[] = [
    {
      key: 'fullName',
      name: 'Full Name',
      fieldName: 'fullName',
      minWidth: 150,
      maxWidth: 250,
      isResizable: true,
      isSorted: sortColumn === 'fullName',
      isSortedDescending: sortColumn === 'fullName' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'emailAddress1',
      name: 'Email',
      fieldName: 'emailAddress1',
      minWidth: 150,
      maxWidth: 250,
      isResizable: true,
      isSorted: sortColumn === 'emailAddress1',
      isSortedDescending: sortColumn === 'emailAddress1' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'telephone1',
      name: 'Phone',
      fieldName: 'telephone1',
      minWidth: 120,
      maxWidth: 150,
      isResizable: true,
      isSorted: sortColumn === 'telephone1',
      isSortedDescending: sortColumn === 'telephone1' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'mobilePhone',
      name: 'Mobile',
      fieldName: 'mobilePhone',
      minWidth: 120,
      maxWidth: 150,
      isResizable: true,
      isSorted: sortColumn === 'mobilePhone',
      isSortedDescending: sortColumn === 'mobilePhone' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'jobTitle',
      name: 'Job Title',
      fieldName: 'jobTitle',
      minWidth: 150,
      maxWidth: 200,
      isResizable: true,
      isSorted: sortColumn === 'jobTitle',
      isSortedDescending: sortColumn === 'jobTitle' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'address1City',
      name: 'City',
      fieldName: 'address1City',
      minWidth: 120,
      maxWidth: 150,
      isResizable: true,
      isSorted: sortColumn === 'address1City',
      isSortedDescending: sortColumn === 'address1City' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'address1StateOrProvince',
      name: 'State/Province',
      fieldName: 'address1StateOrProvince',
      minWidth: 120,
      maxWidth: 150,
      isResizable: true,
      isSorted: sortColumn === 'address1StateOrProvince',
      isSortedDescending: sortColumn === 'address1StateOrProvince' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'address1PostalCode',
      name: 'Postal Code',
      fieldName: 'address1PostalCode',
      minWidth: 100,
      maxWidth: 120,
      isResizable: true,
      isSorted: sortColumn === 'address1PostalCode',
      isSortedDescending: sortColumn === 'address1PostalCode' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'address1Country',
      name: 'Country',
      fieldName: 'address1Country',
      minWidth: 100,
      maxWidth: 150,
      isResizable: true,
      isSorted: sortColumn === 'address1Country',
      isSortedDescending: sortColumn === 'address1Country' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
  ];

  const orderedColumns = currentView.columnOrder.map(key => allColumns.find(col => col.key === key)).filter(Boolean) as IColumn[];
  const columns = orderedColumns.filter((col) => currentView.columnVisibility[col.key]);

  const commandBarItems: ICommandBarItemProps[] = [
    {
      key: 'new',
      text: 'New',
      iconProps: { iconName: 'Add' },
      onClick: handleNew,
    },
    {
      key: 'edit',
      text: 'Edit',
      iconProps: { iconName: 'Edit' },
      disabled: !selectedContact,
      onClick: handleEdit,
    },
    {
      key: 'delete',
      text: 'Delete',
      iconProps: { iconName: 'Delete' },
      disabled: !selectedContact,
      onClick: handleDelete,
    },
    {
      key: 'refresh',
      text: 'Refresh',
      iconProps: { iconName: 'Refresh' },
      onClick: loadContacts,
    },
    {
      key: 'export',
      text: 'Export to Excel',
      iconProps: { iconName: 'ExcelDocument' },
      onClick: () => setIsExportDialogOpen(true),
    },
    {
      key: 'import',
      text: 'Import from Excel',
      iconProps: { iconName: 'ExcelLogoInverse' },
      onClick: () => document.getElementById('contacts-import-input')?.click(),
    },
    {
      key: 'mergeDuplicates',
      text: 'Merge Duplicates',
      iconProps: { iconName: 'Merge' },
      onClick: () => navigate('/duplicates?entity=D365Contacts'),
    },
  ];

  const commandBarFarItems: ICommandBarItemProps[] = [
    {
      key: 'search',
      onRender: () => (
        <SearchBox
          placeholder="Search all columns..."
          value={searchText}
          onChange={(_, value) => setSearchText(value || '')}
          onClear={() => setSearchText('')}
          styles={{ root: { width: 300 } }}
        />
      ),
    },
  ];

  if (isFormOpen) {
    return (
      <Stack styles={{ root: { height: '100vh', overflow: 'hidden' } }}>
        <D365ContactForm
          contact={selectedContact}
          onDismiss={() => {
            setIsFormOpen(false);
            setSelectedContact(undefined);
          }}
          onSave={() => {
            loadContacts();
            setIsFormOpen(false);
            setSelectedContact(undefined);
          }}
          onDelete={selectedContact ? () => {
            setIsFormOpen(false);
            handleDelete();
          } : undefined}
        />
      </Stack>
    );
  }

  return (
    <Stack tokens={{ childrenGap: 16 }}>
      <Text variant="xxLarge">D365 Contacts</Text>

      <CommandBar items={commandBarItems} farItems={commandBarFarItems} />

      <input
        id="contacts-import-input"
        type="file"
        accept=".xlsx,.xls"
        style={{ display: 'none' }}
        onChange={handleImport}
      />

      {error && (
        <MessageBar messageBarType={MessageBarType.error} onDismiss={() => setError(null)}>
          {error}
        </MessageBar>
      )}

      <Stack
        horizontal
        verticalAlign="center"
        tokens={{ childrenGap: 8 }}
        styles={{
          root: {
            padding: '8px 12px',
            backgroundColor: '#faf9f8',
            borderBottom: '1px solid #edebe9',
          },
        }}
      >
        <ViewManager
          views={views}
          currentView={currentView}
          onViewChange={handleViewChange}
          onSaveView={handleSaveView}
          onDeleteView={handleDeleteView}
          onSetDefaultView={handleSetDefaultView}
        />

        <IconButton
          iconProps={{ iconName: 'ColumnOptions' }}
          title="Column Settings"
          ariaLabel="Column Settings"
          onClick={() => setIsColumnPanelOpen(true)}
        />

        <IconButton
          iconProps={{ iconName: 'Filter' }}
          title="Filter"
          ariaLabel="Filter"
          onClick={() => setIsFilterBuilderOpen(true)}
        />

        <Separator vertical styles={{ root: { height: 24 } }} />

        <Text variant="medium" styles={{ root: { marginLeft: 8 } }}>
          {filteredContacts.length} {filteredContacts.length === 1 ? 'contact' : 'contacts'}
        </Text>
      </Stack>

      {loading ? (
        <Stack horizontalAlign="center" tokens={{ padding: 40 }}>
          <Spinner size={SpinnerSize.large} label="Loading contacts..." />
        </Stack>
      ) : (
        <>
          <div style={{ overflowX: 'auto', overflowY: 'visible' }}>
            <DetailsList
              items={paginatedContacts}
              columns={columns}
              layoutMode={DetailsListLayoutMode.justified}
              constrainMode={ConstrainMode.unconstrained}
              selection={selection}
              selectionPreservedOnEmptyClick
              onItemInvoked={handleRowDoubleClick}
              styles={{
                root: {
                  selectors: {
                    '.ms-DetailsRow': {
                      cursor: 'pointer',
                    },
                  },
                },
              }}
            />
          </div>
          <Pagination
            currentPage={currentPage}
            pageSize={pageSize}
            totalRecords={filteredContacts.length}
            onPageChange={setCurrentPage}
            onPageSizeChange={setPageSize}
          />
        </>
      )}

      <Panel
        isOpen={isColumnPanelOpen}
        onDismiss={() => setIsColumnPanelOpen(false)}
        headerText="Column Settings"
        closeButtonAriaLabel="Close"
      >
        <Stack tokens={{ childrenGap: 16 }}>
          <Text variant="medium">Show/Hide Columns</Text>
          {currentView.columnOrder.map((columnKey) => {
            const column = allColumns.find((col) => col.key === columnKey);
            if (!column) return null;

            return (
              <Stack key={columnKey} horizontal verticalAlign="center" tokens={{ childrenGap: 8 }}>
                <Checkbox
                  label={column.name}
                  checked={currentView.columnVisibility[columnKey]}
                  onChange={(_, checked) => {
                    updateCurrentViewColumns(
                      { ...currentView.columnVisibility, [columnKey]: !!checked },
                      currentView.columnOrder
                    );
                  }}
                  styles={{ root: { flex: 1 } }}
                />
                <IconButton
                  iconProps={{ iconName: 'Up' }}
                  title="Move up"
                  ariaLabel="Move up"
                  onClick={() => moveColumnUp(columnKey)}
                  disabled={currentView.columnOrder.indexOf(columnKey) === 0}
                />
                <IconButton
                  iconProps={{ iconName: 'Down' }}
                  title="Move down"
                  ariaLabel="Move down"
                  onClick={() => moveColumnDown(columnKey)}
                  disabled={
                    currentView.columnOrder.indexOf(columnKey) ===
                    currentView.columnOrder.length - 1
                  }
                />
              </Stack>
            );
          })}
        </Stack>
      </Panel>

      <FilterBuilder
        isOpen={isFilterBuilderOpen}
        onDismiss={() => setIsFilterBuilderOpen(false)}
        filters={currentView.filters || []}
        onFiltersChange={handleFiltersChange}
        availableFields={availableFields}
      />

      {isExportDialogOpen && (
        <Panel
          isOpen={isExportDialogOpen}
          onDismiss={() => setIsExportDialogOpen(false)}
          headerText="Export to Excel"
          closeButtonAriaLabel="Close"
        >
          <Stack tokens={{ childrenGap: 16 }}>
            <Text>Choose what to export:</Text>
            <Stack tokens={{ childrenGap: 8 }}>
              <button
                onClick={handleExportAll}
                style={{
                  padding: '10px 16px',
                  backgroundColor: '#0078d4',
                  color: 'white',
                  border: 'none',
                  borderRadius: '2px',
                  cursor: 'pointer',
                }}
              >
                Export All ({filteredContacts.length} contacts)
              </button>
              <button
                onClick={handleExportSelected}
                disabled={selection.getSelectedCount() === 0}
                style={{
                  padding: '10px 16px',
                  backgroundColor:
                    selection.getSelectedCount() === 0 ? '#f3f2f1' : '#0078d4',
                  color: selection.getSelectedCount() === 0 ? '#a19f9d' : 'white',
                  border: 'none',
                  borderRadius: '2px',
                  cursor: selection.getSelectedCount() === 0 ? 'not-allowed' : 'pointer',
                }}
              >
                Export Selected ({selection.getSelectedCount()} contacts)
              </button>
            </Stack>
          </Stack>
        </Panel>
      )}

      <DeleteDialog
        isOpen={isDeleteDialogOpen}
        title="Delete Contact"
        message={`Are you sure you want to delete "${contactToDelete?.fullName}"?`}
        onConfirm={confirmDelete}
        onCancel={() => setIsDeleteDialogOpen(false)}
      />
    </Stack>
  );
};

frontend/src/components/SaleRepresentati.content:
import { useState, useEffect } from 'react';
import {
  Stack,
  Text,
  TextField,
  MessageBar,
  MessageBarType,
  DefaultButton,
  CommandBar,
} from '@fluentui/react';
import type { ICommandBarItemProps } from '@fluentui/react';
import { saleRepresentativeService } from '../services';
import type { SaleRepresentative } from '../types/millennium';

interface SaleRepresentativeFormProps {
  saleRepresentative?: SaleRepresentative;
  onDismiss: () => void;
  onSave: () => void;
  onDelete?: () => void;
}

export const SaleRepresentativeForm = ({
  saleRepresentative,
  onDismiss,
  onSave,
  onDelete,
}: SaleRepresentativeFormProps) => {
  const [activeTab, setActiveTab] = useState<string>('basic');
  const [formData, setFormData] = useState<Partial<SaleRepresentative>>({
    name: '',
    cellNumber: '',
    emailAddress: '',
    employeeNo: '',
    newEmployeeFile: '',
  });
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (saleRepresentative) {
      setFormData({
        name: saleRepresentative.name || '',
        cellNumber: saleRepresentative.cellNumber || '',
        emailAddress: saleRepresentative.emailAddress || '',
        employeeNo: saleRepresentative.employeeNo || '',
        newEmployeeFile: saleRepresentative.newEmployeeFile || '',
      });
    }
    setError(null);
  }, [saleRepresentative]);

  const handleSubmit = async () => {
    try {
      setSaving(true);
      setError(null);

      if (saleRepresentative) {
        await saleRepresentativeService.update(saleRepresentative.id, formData);
      } else {
        await saleRepresentativeService.create(formData);
      }

      onSave();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save sale representative');
      setSaving(false);
    }
  };

  const handleSaveAndNew = async () => {
    try {
      setSaving(true);
      setError(null);

      if (saleRepresentative) {
        await saleRepresentativeService.update(saleRepresentative.id, formData);
      } else {
        await saleRepresentativeService.create(formData);
      }

      setFormData({
        name: '',
        cellNumber: '',
        emailAddress: '',
        employeeNo: '',
        newEmployeeFile: '',
      });
      setSaving(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save sale representative');
      setSaving(false);
    }
  };

  const commandBarItems: ICommandBarItemProps[] = [
    {
      key: 'save',
      text: 'Save',
      iconProps: { iconName: 'Save' },
      onClick: handleSubmit,
      disabled: saving,
    },
    {
      key: 'saveAndNew',
      text: 'Save & New',
      iconProps: { iconName: 'SaveAndClose' },
      onClick: handleSaveAndNew,
      disabled: saving,
    },
    ...(saleRepresentative && onDelete
      ? [
          {
            key: 'delete',
            text: 'Delete',
            iconProps: { iconName: 'Delete' },
            onClick: onDelete,
            disabled: saving,
          },
        ]
      : []),
    {
      key: 'cancel',
      text: 'Cancel',
      iconProps: { iconName: 'Cancel' },
      onClick: onDismiss,
      disabled: saving,
    },
  ];

  return (
    <Stack tokens={{ childrenGap: 16 }} styles={{ root: { height: '100%' } }}>
      <Text variant="xxLarge" styles={{ root: { padding: '20px 20px 0 20px' } }}>
        {saleRepresentative ? 'Edit Sale Representative' : 'New Sale Representative'}
      </Text>

      <CommandBar items={commandBarItems} />

      <Stack styles={{ root: { flex: 1, overflowY: 'auto', padding: '0 20px 20px 20px' } }}>
        {error && (
          <MessageBar messageBarType={MessageBarType.error} onDismiss={() => setError(null)}>
            {error}
          </MessageBar>
        )}

        <Stack styles={{ root: { flex: 1, display: 'flex', flexDirection: 'column' } }}>
          <Stack horizontal styles={{ root: { borderBottom: '1px solid #edebe9' } }}>
            <DefaultButton
              text="Basic Information"
              iconProps={{ iconName: 'Info' }}
              onClick={() => setActiveTab('basic')}
              styles={{
                root: {
                  height: 48,
                  padding: '0 24px',
                  borderRadius: 0,
                  border: 'none',
                  backgroundColor: activeTab === 'basic' ? '#0078d4' : 'transparent',
                  color: activeTab === 'basic' ? 'white' : '#323130',
                  fontWeight: activeTab === 'basic' ? 600 : 400,
                },
                rootHovered: {
                  backgroundColor: activeTab === 'basic' ? '#106ebe' : '#f3f2f1',
                  color: activeTab === 'basic' ? 'white' : '#323130',
                },
              }}
            />
            <DefaultButton
              text="Contact Information"
              iconProps={{ iconName: 'Contact' }}
              onClick={() => setActiveTab('contact')}
              styles={{
                root: {
                  height: 48,
                  padding: '0 24px',
                  borderRadius: 0,
                  border: 'none',
                  backgroundColor: activeTab === 'contact' ? '#0078d4' : 'transparent',
                  color: activeTab === 'contact' ? 'white' : '#323130',
                  fontWeight: activeTab === 'contact' ? 600 : 400,
                },
                rootHovered: {
                  backgroundColor: activeTab === 'contact' ? '#106ebe' : '#f3f2f1',
                  color: activeTab === 'contact' ? 'white' : '#323130',
                },
              }}
            />
            <DefaultButton
              text="Additional"
              iconProps={{ iconName: 'DocumentSet' }}
              onClick={() => setActiveTab('additional')}
              styles={{
                root: {
                  height: 48,
                  padding: '0 24px',
                  borderRadius: 0,
                  border: 'none',
                  backgroundColor: activeTab === 'additional' ? '#0078d4' : 'transparent',
                  color: activeTab === 'additional' ? 'white' : '#323130',
                  fontWeight: activeTab === 'additional' ? 600 : 400,
                },
                rootHovered: {
                  backgroundColor: activeTab === 'additional' ? '#106ebe' : '#f3f2f1',
                  color: activeTab === 'additional' ? 'white' : '#323130',
                },
              }}
            />
          </Stack>

          <Stack styles={{ root: { flex: 1, overflowY: 'auto', padding: '20px 0' } }}>
            {activeTab === 'basic' && (
              <Stack tokens={{ childrenGap: 16 }} styles={{ root: { maxWidth: 600 } }}>
                <TextField
                  label="Name"
                  required
                  value={formData.name}
                  onChange={(_, value) => setFormData({ ...formData, name: value || '' })}
                />

                <TextField
                  label="Employee No"
                  value={formData.employeeNo}
                  onChange={(_, value) => setFormData({ ...formData, employeeNo: value || '' })}
                />
              </Stack>
            )}

            {activeTab === 'contact' && (
              <Stack tokens={{ childrenGap: 16 }} styles={{ root: { maxWidth: 600 } }}>
                <TextField
                  label="Cell Number"
                  value={formData.cellNumber}
                  onChange={(_, value) => setFormData({ ...formData, cellNumber: value || '' })}
                />

                <TextField
                  label="Email Address"
                  type="email"
                  value={formData.emailAddress}
                  onChange={(_, value) =>
                    setFormData({ ...formData, emailAddress: value || '' })
                  }
                />
              </Stack>
            )}

            {activeTab === 'additional' && (
              <Stack tokens={{ childrenGap: 16 }} styles={{ root: { maxWidth: 600 } }}>
                <TextField
                  label="Employee File"
                  value={formData.newEmployeeFile}
                  onChange={(_, value) =>
                    setFormData({ ...formData, newEmployeeFile: value || '' })
                  }
                />
              </Stack>
            )}
          </Stack>
        </Stack>
      </Stack>
    </Stack>
  );
};

frontend/src/components/D365OrderForm.ts.content:
import { useState, useEffect } from 'react';
import {
  Stack,
  TextField,
  MessageBar,
  MessageBarType,
  DatePicker,
  Dropdown,
  Label,
  Pivot,
  PivotItem,
  Text,
} from '@fluentui/react';
import type { IDropdownOption, IColumn } from '@fluentui/react';
import { 
  d365OrderService, 
  accountService, 
  d365QuoteService,
  productionService,
  deliveryService,
  installationProgressService,
} from '../services/d365Services';
import { StandardLookupField, StandardFormHeader, type LookupOption } from './standards';
import { RelatedSubGrid } from './RelatedSubGrid';
import type { D365Order, Production, Delivery, InstallationProgress } from '../types/millennium';

interface D365OrderFormProps {
  order?: D365Order;
  onDismiss: () => void;
  onSave: () => void;
  onDelete?: () => void;
}

const stateCodeOptions: IDropdownOption[] = [
  { key: 0, text: 'Active' },
  { key: 1, text: 'Inactive' },
  { key: 2, text: 'Submitted' },
  { key: 3, text: 'Canceled' },
];

const statusCodeOptions: IDropdownOption[] = [
  { key: 1, text: 'New' },
  { key: 2, text: 'Pending' },
  { key: 3, text: 'In Progress' },
  { key: 4, text: 'No Money' },
  { key: 100000, text: 'Complete' },
  { key: 100001, text: 'Partial' },
  { key: 100002, text: 'Invoiced' },
  { key: 5, text: 'Canceled' },
];

export const D365OrderForm = ({
  order,
  onDismiss,
  onSave,
  onDelete,
}: D365OrderFormProps) => {
  const [activeTab, setActiveTab] = useState<string>('summary');
  const [formData, setFormData] = useState<Partial<D365Order>>({
    orderNumber: '',
    name: '',
    customerId: '',
    quoteId: '',
    dateFulfilled: '',
    requestDeliveryBy: '',
    totalAmount: 0,
    totalDiscountAmount: 0,
    totalLineItemAmount: 0,
    stateCode: 0,
    statusCode: 1,
    description: '',
    ownerId: '',
  });
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  const [selectedCustomerText, setSelectedCustomerText] = useState<string>('');
  const [selectedQuoteText, setSelectedQuoteText] = useState<string>('');

  useEffect(() => {
    if (order) {
      setFormData({
        orderNumber: order.orderNumber || '',
        name: order.name || '',
        customerId: order.customerId || '',
        quoteId: order.quoteId || '',
        dateFulfilled: order.dateFulfilled || '',
        requestDeliveryBy: order.requestDeliveryBy || '',
        totalAmount: order.totalAmount || 0,
        totalDiscountAmount: order.totalDiscountAmount || 0,
        totalLineItemAmount: order.totalLineItemAmount || 0,
        stateCode: order.stateCode ?? 0,
        statusCode: order.statusCode ?? 1,
        description: order.description || '',
        ownerId: order.ownerId || '',
      });

      loadLookupTexts(order);
    }
    setError(null);
  }, [order]);

  const loadLookupTexts = async (ord: D365Order) => {
    try {
      if (ord.customerId) {
        const accounts = await accountService.getAll();
        const account = accounts.find(a => a.id === ord.customerId);
        if (account) {
          setSelectedCustomerText(account.name || '');
        }
      }

      if (ord.quoteId) {
        const quotes = await d365QuoteService.getAll();
        const quote = quotes.find(q => q.id === ord.quoteId);
        if (quote) {
          setSelectedQuoteText(quote.quoteNumber ? `${quote.quoteNumber}${quote.name ? ' - ' + quote.name : ''}` : (quote.name || ''));
        }
      }
    } catch (err) {
      console.error('Failed to load lookup texts:', err);
    }
  };

  const handleSubmit = async () => {
    try {
      setSaving(true);
      setError(null);

      if (order) {
        await d365OrderService.update(order.id, formData);
      } else {
        await d365OrderService.create(formData);
      }

      onSave();
      setSaving(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save order');
      setSaving(false);
    }
  };

  const handleSaveAndExit = async () => {
    try {
      setSaving(true);
      setError(null);

      if (order) {
        await d365OrderService.update(order.id, formData);
      } else {
        await d365OrderService.create(formData);
      }

      onSave();
      onDismiss();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save order');
      setSaving(false);
    }
  };

  const handleSaveAndNew = async () => {
    try {
      setSaving(true);
      setError(null);

      if (order) {
        await d365OrderService.update(order.id, formData);
      } else {
        await d365OrderService.create(formData);
      }

      setFormData({
        orderNumber: '',
        name: '',
        customerId: '',
        quoteId: '',
        dateFulfilled: '',
        requestDeliveryBy: '',
        totalAmount: 0,
        totalDiscountAmount: 0,
        totalLineItemAmount: 0,
        stateCode: 0,
        statusCode: 1,
        description: '',
        ownerId: '',
      });
      setSelectedCustomerText('');
      setSelectedQuoteText('');
      setSaving(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save order');
      setSaving(false);
    }
  };

  const parseDate = (dateString?: string): Date | undefined => {
    if (!dateString) return undefined;
    const date = new Date(dateString);
    return isNaN(date.getTime()) ? undefined : date;
  };

  const formatDateForInput = (date?: Date): string => {
    if (!date) return '';
    return date.toISOString();
  };

  const formatCurrency = (amount?: number): string => {
    if (amount === undefined || amount === null) return 'R 0.00';
    return `R ${amount.toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const handleCustomerSearch = async (term: string): Promise<LookupOption[]> => {
    const accounts = await accountService.getAll();
    const search = term.toLowerCase();
    return accounts
      .filter(a => (a.name?.toLowerCase() || '').includes(search))
      .slice(0, 50)
      .map(a => ({ id: a.id, text: a.name || '' }));
  };

  const handleQuoteSearch = async (term: string): Promise<LookupOption[]> => {
    const quotes = await d365QuoteService.getAll();
    const search = term.toLowerCase();
    return quotes
      .filter(q => 
        (q.quoteNumber?.toLowerCase() || '').includes(search) ||
        (q.name?.toLowerCase() || '').includes(search)
      )
      .slice(0, 50)
      .map(q => ({
        id: q.id,
        text: q.quoteNumber ? `${q.quoteNumber}${q.name ? ' - ' + q.name : ''}` : (q.name || q.id)
      }));
  };

  const productionColumns: IColumn[] = [
    {
      key: 'name',
      name: 'Name',
      fieldName: 'name',
      minWidth: 150,
      maxWidth: 200,
      isResizable: true,
    },
    {
      key: 'customer',
      name: 'Customer',
      fieldName: 'customer',
      minWidth: 150,
      maxWidth: 200,
      isResizable: true,
    },
    {
      key: 'productionPlannedDate',
      name: 'Production Planned Date',
      fieldName: 'productionPlannedDate',
      minWidth: 150,
      maxWidth: 180,
      isResizable: true,
      onRender: (item: Production) => item.productionPlannedDate ? new Date(item.productionPlannedDate).toLocaleDateString() : '',
    },
    {
      key: 'productionComplete',
      name: 'Production Complete',
      fieldName: 'productionComplete',
      minWidth: 120,
      maxWidth: 150,
      isResizable: true,
      onRender: (item: Production) => item.productionComplete ? 'Yes' : 'No',
    },
  ];

  const deliveryColumns: IColumn[] = [
    {
      key: 'deliveryNo',
      name: 'Delivery No',
      fieldName: 'deliveryNo',
      minWidth: 120,
      maxWidth: 150,
      isResizable: true,
    },
    {
      key: 'customer',
      name: 'Customer',
      fieldName: 'customer',
      minWidth: 150,
      maxWidth: 200,
      isResizable: true,
    },
    {
      key: 'loadingDate',
      name: 'Delivery Date',
      fieldName: 'loadingDate',
      minWidth: 120,
      maxWidth: 150,
      isResizable: true,
      onRender: (item: Delivery) => item.loadingDate ? new Date(item.loadingDate).toLocaleDateString() : '',
    },
    {
      key: 'driver',
      name: 'Driver',
      fieldName: 'driver',
      minWidth: 120,
      maxWidth: 150,
      isResizable: true,
    },
  ];

  const installationColumns: IColumn[] = [
    {
      key: 'name',
      name: 'Name',
      fieldName: 'name',
      minWidth: 150,
      maxWidth: 200,
      isResizable: true,
    },
    {
      key: 'newInstallationOrderNo',
      name: 'Installation Order No',
      fieldName: 'newInstallationOrderNo',
      minWidth: 150,
      maxWidth: 180,
      isResizable: true,
    },
    {
      key: 'newPercentageComplete',
      name: 'Progress %',
      fieldName: 'newPercentageComplete',
      minWidth: 100,
      maxWidth: 120,
      isResizable: true,
      onRender: (item: InstallationProgress) => 
        item.newPercentageComplete !== undefined ? `${item.newPercentageComplete}%` : '0%',
    },
  ];

  const fetchProductionData = async (orderId: string): Promise<Production[]> => {
    return await productionService.getByOrderNo(orderId);
  };

  const fetchDeliveryData = async (orderId: string): Promise<Delivery[]> => {
    return await deliveryService.getByOrderNo(orderId);
  };

  const fetchInstallationData = async (orderId: string): Promise<InstallationProgress[]> => {
    const order = await d365OrderService.getAll();
    const currentOrder = order.find(o => o.id === orderId);
    if (!currentOrder?.orderNumber) return [];
    return await installationProgressService.getByOrderNo(currentOrder.orderNumber);
  };

  return (
    <Stack styles={{ root: { height: '100%', overflow: 'hidden' } }}>
      <StandardFormHeader
        title={order ? `Order: ${order.orderNumber || order.name || 'Untitled'}` : 'New Order'}
        onBack={onDismiss}
        onSave={handleSubmit}
        onSaveAndExit={handleSaveAndExit}
        onCancel={onDismiss}
        onDelete={order && onDelete ? onDelete : undefined}
        saving={saving}
        onSaveAndNew={order ? undefined : handleSaveAndNew}
      />

      <Stack styles={{ root: { flex: 1, overflowY: 'auto', padding: '0 20px 20px 20px' } }}>
        {error && (
          <MessageBar messageBarType={MessageBarType.error} onDismiss={() => setError(null)}>
            {error}
          </MessageBar>
        )}

        <Pivot
          selectedKey={activeTab}
          onLinkClick={(item) => setActiveTab(item?.props.itemKey || 'summary')}
          headersOnly
          styles={{ root: { marginTop: 10 } }}
        >
          <PivotItem headerText="Summary" itemKey="summary" />
          <PivotItem headerText="Financial" itemKey="financial" />
          <PivotItem headerText="Production" itemKey="production" />
          <PivotItem headerText="Ordering" itemKey="ordering" />
          <PivotItem headerText="Dispatch" itemKey="dispatch" />
          <PivotItem headerText="Installation" itemKey="installation" />
          <PivotItem headerText="Details" itemKey="details" />
        </Pivot>

        <Stack tokens={{ childrenGap: 16 }} styles={{ root: { marginTop: 20 } }}>
          {activeTab === 'summary' && (
            <Stack 
              horizontal 
              tokens={{ childrenGap: 20 }}
              wrap
              styles={{ 
                root: { 
                  selectors: {
                    '@media (max-width: 960px)': {
                      flexDirection: 'column'
                    }
                  }
                } 
              }}
            >
              {/* Left Column - Form Fields */}
              <Stack 
                tokens={{ childrenGap: 20 }} 
                styles={{ 
                  root: { 
                    flex: '0 0 400px',
                    minWidth: 320,
                    selectors: {
                      '@media (max-width: 960px)': {
                        flex: '1 1 100%',
                        minWidth: 'auto'
                      }
                    }
                  } 
                }}
              >
                <Stack tokens={{ childrenGap: 12 }}>
                  <Label styles={{ root: { fontWeight: 600, fontSize: 16 } }}>Order Information</Label>

                  <TextField
                    label="Order Number"
                    value={formData.orderNumber || ''}
                    onChange={(_, value) => setFormData({ ...formData, orderNumber: value })}
                    disabled={saving}
                  />

                  <TextField
                    label="Name"
                    value={formData.name || ''}
                    onChange={(_, value) => setFormData({ ...formData, name: value })}
                    disabled={saving}
                    required
                  />

                  <StandardLookupField
                    label="Customer"
                    value={formData.customerId || ''}
                    selectedText={selectedCustomerText}
                    entityName="Customer"
                    onSearch={handleCustomerSearch}
                    onChange={(id) => {
                      setFormData({ ...formData, customerId: id });
                      if (!id) setSelectedCustomerText('');
                    }}
                    onTextChange={(text) => setSelectedCustomerText(text)}
                    disabled={saving}
                  />

                  <StandardLookupField
                    label="Quote"
                    value={formData.quoteId || ''}
                    selectedText={selectedQuoteText}
                    entityName="Quote"
                    onSearch={handleQuoteSearch}
                    onChange={(id) => {
                      setFormData({ ...formData, quoteId: id });
                      if (!id) setSelectedQuoteText('');
                    }}
                    onTextChange={(text) => setSelectedQuoteText(text)}
                    disabled={saving}
                  />
                </Stack>

                <Stack tokens={{ childrenGap: 12 }}>
                  <Label styles={{ root: { fontWeight: 600, fontSize: 16 } }}>Dates</Label>

                  <DatePicker
                    label="Date Fulfilled"
                    value={parseDate(formData.dateFulfilled)}
                    onSelectDate={(date) => 
                      setFormData({ ...formData, dateFulfilled: formatDateForInput(date || undefined) })
                    }
                    disabled={saving}
                  />

                  <DatePicker
                    label="Request Delivery By"
                    value={parseDate(formData.requestDeliveryBy)}
                    onSelectDate={(date) => 
                      setFormData({ ...formData, requestDeliveryBy: formatDateForInput(date || undefined) })
                    }
                    disabled={saving}
                  />
                </Stack>

                <Stack tokens={{ childrenGap: 12 }}>
                  <Label styles={{ root: { fontWeight: 600, fontSize: 16 } }}>Status</Label>

                  <Dropdown
                    label="State Code"
                    selectedKey={formData.stateCode ?? 0}
                    options={stateCodeOptions}
                    onChange={(_, option) => 
                      setFormData({ ...formData, stateCode: option?.key as number })
                    }
                    disabled={saving}
                  />

                  <Dropdown
                    label="Status Code"
                    selectedKey={formData.statusCode ?? 1}
                    options={statusCodeOptions}
                    onChange={(_, option) => 
                      setFormData({ ...formData, statusCode: option?.key as number })
                    }
                    disabled={saving}
                  />
                </Stack>

                <Stack tokens={{ childrenGap: 12 }}>
                  <Label styles={{ root: { fontWeight: 600, fontSize: 16 } }}>Description</Label>

                  <TextField
                    multiline
                    rows={4}
                    value={formData.description || ''}
                    onChange={(_, value) => setFormData({ ...formData, description: value })}
                    disabled={saving}
                  />
                </Stack>

                <Stack 
                  horizontal 
                  tokens={{ childrenGap: 20 }}
                  styles={{ 
                    root: { 
                      padding: 16, 
                      backgroundColor: '#f3f2f1', 
                      borderRadius: 4,
                      border: '1px solid #edebe9'
                    } 
                  }}
                >
                  <Stack styles={{ root: { flex: 1 } }}>
                    <Text variant="small" styles={{ root: { color: '#605e5c', marginBottom: 4 } }}>
                      Total Amount
                    </Text>
                    <Text variant="large" styles={{ root: { fontWeight: 600 } }}>
                      {formatCurrency(formData.totalAmount)}
                    </Text>
                  </Stack>
                  <Stack styles={{ root: { flex: 1 } }}>
                    <Text variant="small" styles={{ root: { color: '#605e5c', marginBottom: 4 } }}>
                      Discount
                    </Text>
                    <Text variant="large" styles={{ root: { fontWeight: 600 } }}>
                      {formatCurrency(formData.totalDiscountAmount)}
                    </Text>
                  </Stack>
                  <Stack styles={{ root: { flex: 1 } }}>
                    <Text variant="small" styles={{ root: { color: '#605e5c', marginBottom: 4 } }}>
                      Line Item Total
                    </Text>
                    <Text variant="large" styles={{ root: { fontWeight: 600 } }}>
                      {formatCurrency(formData.totalLineItemAmount)}
                    </Text>
                  </Stack>
                </Stack>
              </Stack>

              {/* Right Column - Weather Widget */}
              <Stack 
                styles={{ 
                  root: { 
                    flex: 1, 
                    minHeight: 200,
                    minWidth: 400,
                    border: '1px solid #edebe9',
                    borderRadius: 4,
                    backgroundColor: '#87CEEB',
                    position: 'relative',
                    overflow: 'hidden',
                    backgroundImage: 'linear-gradient(180deg, #87CEEB 0%, #B0D9F1 100%)',
                    selectors: {
                      '@media (max-width: 960px)': {
                        minWidth: 'auto',
                        minHeight: 150
                      }
                    }
                  } 
                }}
              >
                {/* Weather Forecast Display */}
                <Stack 
                  horizontal 
                  horizontalAlign="space-around"
                  verticalAlign="center"
                  styles={{ root: { height: '100%', padding: '20px 16px' } }}
                  tokens={{ childrenGap: 8 }}
                >
                  {/* Weather for each day */}
                  {[...Array(7)].map((_, index) => {
                    const date = new Date();
                    date.setDate(date.getDate() + index);
                    const dayName = date.toLocaleDateString('en-US', { weekday: 'short' });
                    const dayNum = date.getDate();

                    return (
                      <Stack 
                        key={index}
                        horizontalAlign="center"
                        tokens={{ childrenGap: 8 }}
                        styles={{ root: { minWidth: 60 } }}
                      >
                        <Text 
                          variant="small" 
                          styles={{ root: { color: 'white', fontWeight: 600, textShadow: '0 1px 2px rgba(0,0,0,0.2)' } }}
                        >
                          {dayName}
                        </Text>
                        <Text 
                          variant="xSmall" 
                          styles={{ root: { color: 'white', opacity: 0.9 } }}
                        >
                          {dayNum}
                        </Text>
                        {/* Cloud icon */}
                        <div style={{
                          fontSize: 32,
                          lineHeight: 1,
                          filter: 'drop-shadow(0 2px 4px rgba(0,0,0,0.15))'
                        }}>
                          ☁️
                        </div>
                        <Text 
                          variant="small" 
                          styles={{ root: { color: 'white', fontWeight: 600, textShadow: '0 1px 2px rgba(0,0,0,0.2)' } }}
                        >
                          {18 + Math.floor(Math.random() * 8)}°
                        </Text>
                      </Stack>
                    );
                  })}
                </Stack>
              </Stack>
            </Stack>
          )}

          {activeTab === 'financial' && (
            <Stack tokens={{ childrenGap: 16 }}>
              <Label styles={{ root: { fontWeight: 600, fontSize: 18 } }}>Financial Information</Label>

              <TextField
                label="Total Amount"
                type="number"
                value={formData.totalAmount?.toString() || '0'}
                onChange={(_, value) => setFormData({ ...formData, totalAmount: parseFloat(value || '0') })}
                disabled={saving}
                prefix="R"
              />

              <TextField
                label="Total Discount Amount"
                type="number"
                value={formData.totalDiscountAmount?.toString() || '0'}
