frontend/src/components/InstallationProg.content:
import { useState, useEffect } from 'react';
import {
  Stack,
  Text,
  TextField,
  MessageBar,
  MessageBarType,
  DefaultButton,
  CommandBar,
} from '@fluentui/react';
import type { ICommandBarItemProps } from '@fluentui/react';
import { installationProgressService } from '../services';
import type { InstallationProgress } from '../types/millennium';

interface InstallationProgressFormProps {
  installationProgress?: InstallationProgress;
  onDismiss: () => void;
  onSave: () => void;
  onDelete?: () => void;
}

export const InstallationProgressForm = ({
  installationProgress,
  onDismiss,
  onSave,
  onDelete,
}: InstallationProgressFormProps) => {
  const [activeTab, setActiveTab] = useState<string>('basic');
  const [formData, setFormData] = useState<Partial<InstallationProgress>>({
    name: '',
    newInstallationOrderNo: '',
    newPercentageComplete: 0,
  });
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (installationProgress) {
      setFormData({
        name: installationProgress.name || '',
        newInstallationOrderNo: installationProgress.newInstallationOrderNo || '',
        newPercentageComplete: installationProgress.newPercentageComplete || 0,
      });
    }
    setError(null);
  }, [installationProgress]);

  const handleSubmit = async () => {
    try {
      setSaving(true);
      setError(null);

      if (installationProgress) {
        await installationProgressService.update(installationProgress.id, formData);
      } else {
        await installationProgressService.create(formData);
      }

      onSave();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save installation progress');
      setSaving(false);
    }
  };

  const handleSaveAndNew = async () => {
    try {
      setSaving(true);
      setError(null);

      if (installationProgress) {
        await installationProgressService.update(installationProgress.id, formData);
      } else {
        await installationProgressService.create(formData);
      }

      setFormData({
        name: '',
        newInstallationOrderNo: '',
        newPercentageComplete: 0,
      });
      setSaving(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save installation progress');
      setSaving(false);
    }
  };

  const commandBarItems: ICommandBarItemProps[] = [
    {
      key: 'save',
      text: 'Save',
      iconProps: { iconName: 'Save' },
      onClick: handleSubmit,
      disabled: saving,
    },
    {
      key: 'saveAndNew',
      text: 'Save & New',
      iconProps: { iconName: 'SaveAndClose' },
      onClick: handleSaveAndNew,
      disabled: saving,
    },
    ...(installationProgress && onDelete
      ? [
          {
            key: 'delete',
            text: 'Delete',
            iconProps: { iconName: 'Delete' },
            onClick: onDelete,
            disabled: saving,
          },
        ]
      : []),
    {
      key: 'cancel',
      text: 'Cancel',
      iconProps: { iconName: 'Cancel' },
      onClick: onDismiss,
      disabled: saving,
    },
  ];

  return (
    <Stack tokens={{ childrenGap: 16 }} styles={{ root: { height: '100%' } }}>
      <Text variant="xxLarge" styles={{ root: { padding: '20px 20px 0 20px' } }}>
        {installationProgress ? 'Edit Installation Progress' : 'New Installation Progress'}
      </Text>

      <CommandBar items={commandBarItems} />

      <Stack styles={{ root: { flex: 1, overflowY: 'auto', padding: '0 20px 20px 20px' } }}>
        {error && (
          <MessageBar messageBarType={MessageBarType.error} onDismiss={() => setError(null)}>
            {error}
          </MessageBar>
        )}

        <Stack styles={{ root: { flex: 1, display: 'flex', flexDirection: 'column' } }}>
          <Stack horizontal styles={{ root: { borderBottom: '1px solid #edebe9' } }}>
            <DefaultButton
              text="Basic Information"
              iconProps={{ iconName: 'Info' }}
              onClick={() => setActiveTab('basic')}
              styles={{
                root: {
                  height: 48,
                  padding: '0 24px',
                  borderRadius: 0,
                  border: 'none',
                  backgroundColor: activeTab === 'basic' ? '#0078d4' : 'transparent',
                  color: activeTab === 'basic' ? 'white' : '#323130',
                  fontWeight: activeTab === 'basic' ? 600 : 400,
                },
                rootHovered: {
                  backgroundColor: activeTab === 'basic' ? '#106ebe' : '#f3f2f1',
                  color: activeTab === 'basic' ? 'white' : '#323130',
                },
              }}
            />
          </Stack>

          <Stack styles={{ root: { flex: 1, overflowY: 'auto', padding: '20px 0' } }}>
            {activeTab === 'basic' && (
              <Stack tokens={{ childrenGap: 16 }} styles={{ root: { marginTop: 16, maxWidth: 600 } }}>
                <TextField
                  label="Name"
                  required
                  value={formData.name}
                  onChange={(_, value) => setFormData({ ...formData, name: value || '' })}
                />

                <TextField
                  label="Installation Order No"
                  value={formData.newInstallationOrderNo}
                  onChange={(_, value) =>
                    setFormData({ ...formData, newInstallationOrderNo: value || '' })
                  }
                />

                <TextField
                  label="Percentage Complete"
                  type="number"
                  suffix="%"
                  value={String(formData.newPercentageComplete || '')}
                  onChange={(_, value) =>
                    setFormData({ ...formData, newPercentageComplete: Number(value) || 0 })
                  }
                />
              </Stack>
            )}
          </Stack>
        </Stack>
      </Stack>
    </Stack>
  );
};

frontend/src/components/D365QuoteForm.ts.content:
import { useState, useEffect } from 'react';
import {
  Stack,
  TextField,
  MessageBar,
  MessageBarType,
  DefaultButton,
  DatePicker,
} from '@fluentui/react';
import { d365QuoteService, lookupService } from '../services/d365Services';
import { StandardLookupField, StandardFormHeader, type LookupOption } from './standards';
import type { D365Quote } from '../types/millennium';

interface D365QuoteFormProps {
  quote?: D365Quote;
  onDismiss: () => void;
  onSave: () => void;
  onDelete?: () => void;
}

export const D365QuoteForm = ({
  quote,
  onDismiss,
  onSave,
  onDelete,
}: D365QuoteFormProps) => {
  const [activeTab, setActiveTab] = useState<string>('basic');
  const [formData, setFormData] = useState<Partial<D365Quote>>({
    quoteNumber: '',
    name: '',
    customerId: '',
    effectiveFrom: '',
    effectiveTo: '',
    totalAmount: 0,
    totalDiscountAmount: 0,
    totalLineItemAmount: 0,
    stateCode: 0,
    statusCode: 0,
    description: '',
    ownerId: '',
  });
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [selectedCustomerText, setSelectedCustomerText] = useState<string>('');

  const searchAccounts = async (searchTerm: string): Promise<LookupOption[]> => {
    try {
      const results = await lookupService.searchAccounts(searchTerm);
      return results.map(r => ({ id: r.id, text: r.text }));
    } catch (error) {
      console.error('Error searching accounts:', error);
      return [];
    }
  };

  useEffect(() => {
    if (quote) {
      setFormData({
        quoteNumber: quote.quoteNumber || '',
        name: quote.name || '',
        customerId: quote.customerId || '',
        effectiveFrom: quote.effectiveFrom || '',
        effectiveTo: quote.effectiveTo || '',
        totalAmount: quote.totalAmount || 0,
        totalDiscountAmount: quote.totalDiscountAmount || 0,
        totalLineItemAmount: quote.totalLineItemAmount || 0,
        stateCode: quote.stateCode || 0,
        statusCode: quote.statusCode || 0,
        description: quote.description || '',
        ownerId: quote.ownerId || '',
      });

      if (quote.customerId) {
        loadCustomerText(quote.customerId);
      }
    }
    setError(null);
  }, [quote]);

  const loadCustomerText = async (customerId: string) => {
    try {
      const results = await lookupService.searchAccounts('');
      const customer = results.find(r => r.id === customerId);
      if (customer) {
        setSelectedCustomerText(customer.text);
      }
    } catch (err) {
      console.error('Failed to load customer text:', err);
    }
  };

  const handleSave = async () => {
    try {
      setSaving(true);
      setError(null);

      if (quote) {
        await d365QuoteService.update(quote.id, formData);
      } else {
        await d365QuoteService.create(formData);
      }

      onSave();
      setSaving(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save quote');
      setSaving(false);
    }
  };

  const handleSaveAndExit = async () => {
    try {
      setSaving(true);
      setError(null);

      if (quote) {
        await d365QuoteService.update(quote.id, formData);
      } else {
        await d365QuoteService.create(formData);
      }

      onSave();
      onDismiss();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save quote');
      setSaving(false);
    }
  };

  const handleDelete = () => {
    if (onDelete) {
      onDelete();
    }
  };

  const tabStyles = (isActive: boolean) => ({
    root: {
      height: 40,
      padding: '0 16px',
      borderRadius: 0,
      border: 'none',
      borderBottom: isActive ? '2px solid #0078d4' : '2px solid transparent',
      backgroundColor: 'transparent',
      color: isActive ? '#0078d4' : '#323130',
      fontWeight: isActive ? '600' : '400',
    },
    rootHovered: {
      backgroundColor: '#f3f2f1',
      color: '#0078d4',
    },
  });

  const parseDate = (dateString?: string): Date | undefined => {
    if (!dateString) return undefined;
    const date = new Date(dateString);
    return isNaN(date.getTime()) ? undefined : date;
  };

  return (
    <Stack tokens={{ childrenGap: 0 }} styles={{ root: { height: '100%', backgroundColor: 'white' } }}>
      <StandardFormHeader
        title={quote ? (quote.name || 'Edit Quote') : 'New Quote'}
        subtitle="Quote"
        onBack={onDismiss}
        onSave={handleSave}
        onSaveAndExit={handleSaveAndExit}
        onDelete={quote && onDelete ? handleDelete : undefined}
        onCancel={onDismiss}
        saving={saving}
        isNew={!quote}
      />

      {error && (
        <MessageBar messageBarType={MessageBarType.error} onDismiss={() => setError(null)}>
          {error}
        </MessageBar>
      )}

      <Stack horizontal styles={{ root: { borderBottom: '1px solid #edebe9', backgroundColor: '#faf9f8' } }}>
        <DefaultButton text="Quote Information" onClick={() => setActiveTab('basic')} styles={tabStyles(activeTab === 'basic')} />
        <DefaultButton text="Customer Details" onClick={() => setActiveTab('customer')} styles={tabStyles(activeTab === 'customer')} />
        <DefaultButton text="Amounts" onClick={() => setActiveTab('amounts')} styles={tabStyles(activeTab === 'amounts')} />
      </Stack>

      <Stack styles={{ root: { flex: 1, overflowY: 'auto', padding: 20 } }}>
        {activeTab === 'basic' && (
          <Stack horizontal tokens={{ childrenGap: 20 }}>
            <Stack tokens={{ childrenGap: 16 }} styles={{ root: { width: '60%', flexShrink: 0 } }}>
                  <TextField
                    label="Quote Number"
                    required
                    value={formData.quoteNumber}
                    onChange={(_, value) =>
                      setFormData({ ...formData, quoteNumber: value || '' })
                    }
                  />

                  <TextField
                    label="Quote Name"
                    required
                    value={formData.name}
                    onChange={(_, value) => setFormData({ ...formData, name: value || '' })}
                  />

                  <TextField
                    label="Description"
                    multiline
                    rows={3}
                    value={formData.description}
                    onChange={(_, value) =>
                      setFormData({ ...formData, description: value || '' })
                    }
                  />
            </Stack>

            <Stack tokens={{ childrenGap: 16 }} styles={{ root: { width: '40%' } }}>
              <DatePicker
                    label="Effective From"
                    value={parseDate(formData.effectiveFrom)}
                    onSelectDate={(date) =>
                      setFormData({ ...formData, effectiveFrom: date?.toISOString() || '' })
                    }
                  />

                  <DatePicker
                    label="Effective To"
                    value={parseDate(formData.effectiveTo)}
                    onSelectDate={(date) =>
                      setFormData({ ...formData, effectiveTo: date?.toISOString() || '' })
                    }
                  />

                  <TextField
                    label="State Code"
                    type="number"
                    value={String(formData.stateCode)}
                    onChange={(_, value) =>
                      setFormData({ ...formData, stateCode: Number(value) || 0 })
                    }
                  />

              <TextField
                label="Status Code"
                type="number"
                value={String(formData.statusCode)}
                onChange={(_, value) =>
                  setFormData({ ...formData, statusCode: Number(value) || 0 })
                }
              />
            </Stack>
          </Stack>
        )}

        {activeTab === 'customer' && (
          <Stack tokens={{ childrenGap: 16 }} styles={{ root: { maxWidth: 600 } }}>
            <StandardLookupField
              label="Customer"
              value={formData.customerId}
              selectedText={selectedCustomerText}
              entityName="Account"
              onChange={(id) => {
                setFormData({ ...formData, customerId: id });
                if (!id) setSelectedCustomerText('');
              }}
              onTextChange={(text) => setSelectedCustomerText(text)}
              onSearch={searchAccounts}
            />

            <TextField
              label="Owner ID"
              value={formData.ownerId}
              onChange={(_, value) => setFormData({ ...formData, ownerId: value || '' })}
            />
          </Stack>
        )}

        {activeTab === 'amounts' && (
          <Stack tokens={{ childrenGap: 16 }} styles={{ root: { maxWidth: 600 } }}>
            <TextField
              label="Total Amount"
              type="number"
              value={String(formData.totalAmount)}
              onChange={(_, value) =>
                setFormData({ ...formData, totalAmount: Number(value) || 0 })
              }
              prefix="R"
            />

            <TextField
              label="Total Discount Amount"
              type="number"
              value={String(formData.totalDiscountAmount)}
              onChange={(_, value) =>
                setFormData({ ...formData, totalDiscountAmount: Number(value) || 0 })
              }
              prefix="R"
            />

            <TextField
              label="Total Line Item Amount"
              type="number"
              value={String(formData.totalLineItemAmount)}
              onChange={(_, value) =>
                setFormData({ ...formData, totalLineItemAmount: Number(value) || 0 })
              }
              prefix="R"
            />
          </Stack>
        )}
      </Stack>
    </Stack>
  );
};

frontend/src/components/VehiclesForm.tsx.content:
import { useState, useEffect } from 'react';
import {
  Stack,
  Text,
  TextField,
  Checkbox,
  MessageBar,
  MessageBarType,
  DefaultButton,
  CommandBar,
  DatePicker,
  Dropdown,
} from '@fluentui/react';
import type { ICommandBarItemProps, IDropdownOption } from '@fluentui/react';
import { vehicleService, employeeService } from '../services';
import type { Vehicle, Employee } from '../types/millennium';

interface VehiclesFormProps {
  vehicle?: Vehicle;
  onDismiss: () => void;
  onSave: () => void;
  onDelete?: () => void;
}

export const VehiclesForm = ({
  vehicle,
  onDismiss,
  onSave,
  onDelete,
}: VehiclesFormProps) => {
  const [activeTab, setActiveTab] = useState<string>('basic');
  const [formData, setFormData] = useState<Partial<Vehicle>>({
    name: '',
    make: '',
    model: '',
    registrationNumber: '',
    yearModel: '',
    approvedDriver: '',
    cofInOrder: false,
    licenseRenewalDate: '',
  });
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [employees, setEmployees] = useState<Employee[]>([]);

  useEffect(() => {
    loadEmployees();
  }, []);

  const loadEmployees = async () => {
    try {
      const data = await employeeService.getAll();
      setEmployees(data);
    } catch (err) {
      console.error('Failed to load employees:', err);
    }
  };

  const employeeOptions: IDropdownOption[] = [
    { key: '', text: '(None)' },
    ...employees.map((e) => ({ key: e.id, text: e.name })),
  ];

  useEffect(() => {
    if (vehicle) {
      setFormData({
        name: vehicle.name || '',
        make: vehicle.make || '',
        model: vehicle.model || '',
        registrationNumber: vehicle.registrationNumber || '',
        yearModel: vehicle.yearModel || '',
        approvedDriver: vehicle.approvedDriver || '',
        cofInOrder: vehicle.cofInOrder || false,
        licenseRenewalDate: vehicle.licenseRenewalDate || '',
      });
    }
    setError(null);
  }, [vehicle]);

  const handleSubmit = async () => {
    try {
      setSaving(true);
      setError(null);

      if (vehicle) {
        await vehicleService.update(vehicle.id, formData);
      } else {
        await vehicleService.create(formData);
      }

      onSave();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save vehicle');
      setSaving(false);
    }
  };

  const handleSaveAndNew = async () => {
    try {
      setSaving(true);
      setError(null);

      if (vehicle) {
        await vehicleService.update(vehicle.id, formData);
      } else {
        await vehicleService.create(formData);
      }

      setFormData({
        name: '',
        make: '',
        model: '',
        registrationNumber: '',
        yearModel: '',
        approvedDriver: '',
        cofInOrder: false,
        licenseRenewalDate: '',
      });
      setSaving(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save vehicle');
      setSaving(false);
    }
  };

  const commandBarItems: ICommandBarItemProps[] = [
    {
      key: 'save',
      text: 'Save',
      iconProps: { iconName: 'Save' },
      onClick: handleSubmit,
      disabled: saving,
