                <TextField
                  label="Notes"
                  multiline
                  rows={4}
                  value={formData.newNotes}
                  onChange={(_, value) => setFormData({ ...formData, newNotes: value || '' })}
                />
              </Stack>
            )}
          </Stack>
        </Stack>
      </Stack>
    </Stack>

      <AdvancedSearchDialog
        isOpen={showCustomerSearch}
        onDismiss={() => setShowCustomerSearch(false)}
