import { useState, useEffect } from 'react';
import {
  Stack,
  Text,
  TextField,
  MessageBar,
  MessageBarType,
  DefaultButton,
  CommandBar,
  DatePicker,
} from '@fluentui/react';
import type { ICommandBarItemProps } from '@fluentui/react';
import { d365AppointmentService } from '../services/d365Services';
import type { D365Appointment } from '../types/millennium';

interface D365AppointmentFormProps {
  appointment?: D365Appointment;
  onDismiss: () => void;
  onSave: () => void;
  onDelete?: () => void;
}

export const D365AppointmentForm = ({
  appointment,
  onDismiss,
  onSave,
  onDelete,
}: D365AppointmentFormProps) => {
  const [activeTab, setActiveTab] = useState<string>('basic');
  const [formData, setFormData] = useState<Partial<D365Appointment>>({
    subject: '',
    location: '',
    scheduledStart: '',
    scheduledEnd: '',
    actualDurationMinutes: 0,
    scheduledDurationMinutes: 0,
    description: '',
    regardingObjectId: '',
    ownerId: '',
    stateCode: 0,
    statusCode: 0,
  });
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (appointment) {
      setFormData({
        subject: appointment.subject || '',
        location: appointment.location || '',
        scheduledStart: appointment.scheduledStart || '',
        scheduledEnd: appointment.scheduledEnd || '',
        actualDurationMinutes: appointment.actualDurationMinutes || 0,
        scheduledDurationMinutes: appointment.scheduledDurationMinutes || 0,
        description: appointment.description || '',
        regardingObjectId: appointment.regardingObjectId || '',
        ownerId: appointment.ownerId || '',
        stateCode: appointment.stateCode || 0,
        statusCode: appointment.statusCode || 0,
      });
    }
    setError(null);
  }, [appointment]);

  const handleSubmit = async () => {
    try {
      setSaving(true);
      setError(null);

      if (appointment) {
        await d365AppointmentService.update(appointment.id, formData);
      } else {
        await d365AppointmentService.create(formData);
      }

      onSave();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save appointment');
      setSaving(false);
    }
  };

  const handleSaveAndNew = async () => {
    try {
      setSaving(true);
      setError(null);

      if (appointment) {
        await d365AppointmentService.update(appointment.id, formData);
      } else {
        await d365AppointmentService.create(formData);
      }

      setFormData({
        subject: '',
        location: '',
        scheduledStart: '',
        scheduledEnd: '',
        actualDurationMinutes: 0,
        scheduledDurationMinutes: 0,
        description: '',
        regardingObjectId: '',
        ownerId: '',
        stateCode: 0,
        statusCode: 0,
      });
      setSaving(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save appointment');
      setSaving(false);
    }
  };

  const commandBarItems: ICommandBarItemProps[] = [
    {
      key: 'save',
      text: 'Save',
      iconProps: { iconName: 'Save' },
      onClick: handleSubmit,
      disabled: saving,
    },
    {
      key: 'saveAndNew',
      text: 'Save & New',
      iconProps: { iconName: 'SaveAndClose' },
      onClick: handleSaveAndNew,
      disabled: saving,
    },
    ...(appointment && onDelete
      ? [
          {
            key: 'delete',
            text: 'Delete',
            iconProps: { iconName: 'Delete' },
            onClick: onDelete,
            disabled: saving,
          },
        ]
      : []),
    {
      key: 'cancel',
      text: 'Cancel',
      iconProps: { iconName: 'Cancel' },
      onClick: onDismiss,
      disabled: saving,
    },
  ];

  const parseDate = (dateString?: string): Date | undefined => {
    if (!dateString) return undefined;
    const date = new Date(dateString);
    return isNaN(date.getTime()) ? undefined : date;
  };

  return (
    <Stack tokens={{ childrenGap: 16 }} styles={{ root: { height: '100%' } }}>
      <Text variant="xxLarge" styles={{ root: { padding: '20px 20px 0 20px' } }}>
        {appointment ? 'Edit Appointment' : 'New Appointment'}
      </Text>

      <CommandBar items={commandBarItems} />

      <Stack styles={{ root: { flex: 1, overflowY: 'auto', padding: '0 20px 20px 20px' } }}>
        {error && (
          <MessageBar messageBarType={MessageBarType.error} onDismiss={() => setError(null)}>
            {error}
          </MessageBar>
        )}

        <Stack styles={{ root: { flex: 1, display: 'flex', flexDirection: 'column' } }}>
          <Stack horizontal styles={{ root: { borderBottom: '1px solid #edebe9' } }}>
            <DefaultButton
              text="Appointment Information"
              iconProps={{ iconName: 'Calendar' }}
              onClick={() => setActiveTab('basic')}
              styles={{
                root: {
                  height: 48,
                  padding: '0 24px',
                  borderRadius: 0,
                  border: 'none',
                  backgroundColor: activeTab === 'basic' ? '#0078d4' : 'transparent',
                  color: activeTab === 'basic' ? 'white' : '#323130',
                  fontWeight: activeTab === 'basic' ? 600 : 400,
                },
                rootHovered: {
                  backgroundColor: activeTab === 'basic' ? '#106ebe' : '#f3f2f1',
                  color: activeTab === 'basic' ? 'white' : '#323130',
                },
              }}
            />
            <DefaultButton
              text="Scheduling"
              iconProps={{ iconName: 'DateTime' }}
              onClick={() => setActiveTab('scheduling')}
              styles={{
                root: {
                  height: 48,
                  padding: '0 24px',
                  borderRadius: 0,
                  border: 'none',
                  backgroundColor: activeTab === 'scheduling' ? '#0078d4' : 'transparent',
                  color: activeTab === 'scheduling' ? 'white' : '#323130',
                  fontWeight: activeTab === 'scheduling' ? 600 : 400,
                },
                rootHovered: {
                  backgroundColor: activeTab === 'scheduling' ? '#106ebe' : '#f3f2f1',
                  color: activeTab === 'scheduling' ? 'white' : '#323130',
                },
              }}
            />
          </Stack>

          <Stack styles={{ root: { flex: 1, overflowY: 'auto', padding: '20px 0' } }}>
            {activeTab === 'basic' && (
              <Stack
                horizontal
                tokens={{ childrenGap: 32 }}
                styles={{ root: { marginTop: 16, overflowY: 'auto' } }}
              >
                <Stack tokens={{ childrenGap: 16 }} styles={{ root: { flex: 1 } }}>
                  <TextField
                    label="Subject"
                    required
                    value={formData.subject}
                    onChange={(_, value) => setFormData({ ...formData, subject: value || '' })}
                  />

                  <TextField
                    label="Location"
                    value={formData.location}
                    onChange={(_, value) => setFormData({ ...formData, location: value || '' })}
                  />

                  <TextField
                    label="Description"
                    multiline
                    rows={4}
                    value={formData.description}
                    onChange={(_, value) =>
                      setFormData({ ...formData, description: value || '' })
                    }
                  />
                </Stack>

                <Stack tokens={{ childrenGap: 16 }} styles={{ root: { flex: 1 } }}>
                  <TextField
                    label="Regarding Object ID"
                    value={formData.regardingObjectId}
                    onChange={(_, value) =>
                      setFormData({ ...formData, regardingObjectId: value || '' })
                    }
                  />

                  <TextField
                    label="Owner ID"
                    value={formData.ownerId}
                    onChange={(_, value) => setFormData({ ...formData, ownerId: value || '' })}
                  />

                  <TextField
                    label="State Code"
                    type="number"
                    value={String(formData.stateCode)}
                    onChange={(_, value) =>
                      setFormData({ ...formData, stateCode: Number(value) || 0 })
                    }
                  />

                  <TextField
                    label="Status Code"
                    type="number"
                    value={String(formData.statusCode)}
                    onChange={(_, value) =>
                      setFormData({ ...formData, statusCode: Number(value) || 0 })
                    }
                  />
                </Stack>
              </Stack>
            )}

            {activeTab === 'scheduling' && (
              <Stack
                tokens={{ childrenGap: 16 }}
                styles={{ root: { marginTop: 16, maxWidth: 600 } }}
              >
                <DatePicker
                  label="Scheduled Start"
                  value={parseDate(formData.scheduledStart)}
                  onSelectDate={(date) =>
                    setFormData({ ...formData, scheduledStart: date?.toISOString() || '' })
                  }
                />

                <DatePicker
                  label="Scheduled End"
                  value={parseDate(formData.scheduledEnd)}
                  onSelectDate={(date) =>
                    setFormData({ ...formData, scheduledEnd: date?.toISOString() || '' })
                  }
                />

                <TextField
                  label="Scheduled Duration (Minutes)"
                  type="number"
                  value={String(formData.scheduledDurationMinutes)}
                  onChange={(_, value) =>
                    setFormData({ ...formData, scheduledDurationMinutes: Number(value) || 0 })
                  }
                />

                <TextField
                  label="Actual Duration (Minutes)"
                  type="number"
                  value={String(formData.actualDurationMinutes)}
                  onChange={(_, value) =>
                    setFormData({ ...formData, actualDurationMinutes: Number(value) || 0 })
                  }
                />
              </Stack>
            )}
          </Stack>
        </Stack>
      </Stack>
    </Stack>
  );
};

frontend/src/pages/D365AppointmentsPage..content:
import { useState, useEffect } from 'react';
import {
  Stack,
  Text,
  DetailsList,
  DetailsListLayoutMode,
  ConstrainMode,
  Selection,
  CommandBar,
  MessageBar,
  MessageBarType,
  Spinner,
  SpinnerSize,
  SearchBox,
  Panel,
  Checkbox,
  IconButton,
  Separator,
} from '@fluentui/react';
import type { IColumn, ICommandBarItemProps } from '@fluentui/react';
import { d365AppointmentService } from '../services/d365Services';
import type { D365Appointment } from '../types/millennium';
import type { GridView, GridFilter } from '../types/gridView';
import { D365AppointmentForm } from '../components/D365AppointmentForm';
import { DeleteDialog } from '../components/DeleteDialog';
import { ViewManager } from '../components/ViewManager';
import { FilterBuilder } from '../components/FilterBuilder';
import * as XLSX from 'xlsx';

export const D365AppointmentsPage = () => {
  const [appointments, setAppointments] = useState<D365Appointment[]>([]);
  const [filteredAppointments, setFilteredAppointments] = useState<D365Appointment[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedAppointment, setSelectedAppointment] = useState<D365Appointment | undefined>();
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [appointmentToDelete, setAppointmentToDelete] = useState<D365Appointment | undefined>();
  const [searchText, setSearchText] = useState('');
  const [isColumnPanelOpen, setIsColumnPanelOpen] = useState(false);
  const [isExportDialogOpen, setIsExportDialogOpen] = useState(false);
  const [isFilterBuilderOpen, setIsFilterBuilderOpen] = useState(false);
  const [sortColumn, setSortColumn] = useState<string>('');
  const [isSortedDescending, setIsSortedDescending] = useState(false);

  const defaultVisibleColumns: { [key: string]: boolean } = {
    subject: true,
    location: true,
    scheduledStart: true,
    scheduledEnd: true,
    scheduledDurationMinutes: true,
    description: false,
    actualDurationMinutes: false,
  };

  const defaultColumnOrder = [
    'subject', 'location', 'scheduledStart', 'scheduledEnd', 'scheduledDurationMinutes',
    'description', 'actualDurationMinutes'
  ];

  const defaultView: GridView = {
    id: 'default-view',
    name: 'All Appointments',
    isDefault: true,
    entityType: 'd365appointment',
    columnVisibility: defaultVisibleColumns,
    columnOrder: defaultColumnOrder,
    filters: [],
  };

  const loadViews = (): GridView[] => {
    try {
      const saved = localStorage.getItem('d365appointments-views');
      if (saved) {
        const views = JSON.parse(saved);
        return views.length > 0 ? views : [defaultView];
      }
    } catch (err) {
      console.warn('Failed to load views:', err);
    }
    return [defaultView];
  };

  const [views, setViews] = useState<GridView[]>(loadViews());
  const [currentView, setCurrentView] = useState<GridView>(
    views.find(v => v.isDefault) || defaultView
  );

  const [selection] = useState(
    new Selection({
      onSelectionChanged: () => {
        const selected = selection.getSelection()[0] as D365Appointment | undefined;
        setSelectedAppointment(selected);
      },
    })
  );

  useEffect(() => {
    loadAppointments();
  }, []);

  useEffect(() => {
    applyFilters();
  }, [appointments, searchText, currentView, sortColumn, isSortedDescending]);

  const loadAppointments = async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await d365AppointmentService.getAll();
      setAppointments(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load appointments');
    } finally {
      setLoading(false);
    }
  };

  const applyFilters = () => {
    let filtered = [...appointments];

    if (searchText) {
      const search = searchText.toLowerCase();
      filtered = filtered.filter((appointment) => {
        return Object.values(appointment).some((value) =>
          String(value).toLowerCase().includes(search)
        );
      });
    }

    if (currentView.filters && currentView.filters.length > 0) {
      filtered = filtered.filter((appointment) => {
        let result = true;
        let currentLogic: 'AND' | 'OR' = 'AND';

        for (let i = 0; i < currentView.filters.length; i++) {
          const filter = currentView.filters[i];
          const fieldValue = appointment[filter.field as keyof D365Appointment];
          const value = String(fieldValue ?? '').toLowerCase();
          const filterValue = filter.value.toLowerCase();

          let filterResult = false;
          switch (filter.operator) {
            case 'equals':
              filterResult = value === filterValue;
              break;
            case 'notEquals':
              filterResult = value !== filterValue;
              break;
            case 'contains':
              filterResult = value.includes(filterValue);
              break;
            case 'notContains':
              filterResult = !value.includes(filterValue);
              break;
            case 'beginsWith':
              filterResult = value.startsWith(filterValue);
              break;
            case 'endsWith':
              filterResult = value.endsWith(filterValue);
              break;
            case 'isEmpty':
              filterResult = !value;
              break;
            case 'isNotEmpty':
              filterResult = !!value;
              break;
            default:
              filterResult = true;
          }

          if (i === 0) {
            result = filterResult;
          } else {
            if (currentLogic === 'AND') {
              result = result && filterResult;
            } else {
              result = result || filterResult;
            }
          }

          currentLogic = filter.logicOperator || 'AND';
        }

        return result;
      });
    }

    if (sortColumn) {
      filtered.sort((a, b) => {
        let aValue: any = a[sortColumn as keyof D365Appointment];
        let bValue: any = b[sortColumn as keyof D365Appointment];

        if (aValue === undefined || aValue === null) {
          aValue = typeof bValue === 'boolean' ? false : typeof bValue === 'number' ? 0 : '';
        }
        if (bValue === undefined || bValue === null) {
          bValue = typeof aValue === 'boolean' ? false : typeof aValue === 'number' ? 0 : '';
        }

        let comparison = 0;
        if (typeof aValue === 'string' && typeof bValue === 'string') {
          comparison = aValue.localeCompare(bValue);
        } else if (typeof aValue === 'number' && typeof bValue === 'number') {
          comparison = aValue - bValue;
        } else if (typeof aValue === 'boolean' && typeof bValue === 'boolean') {
          comparison = (aValue ? 1 : 0) - (bValue ? 1 : 0);
        }

        if (comparison === 0 && sortColumn !== 'subject') {
          const aSubject = a.subject || '';
          const bSubject = b.subject || '';
          comparison = aSubject.localeCompare(bSubject);
        }

        return isSortedDescending ? -comparison : comparison;
      });
    }

    setFilteredAppointments(filtered);
  };

  const handleNew = () => {
    setSelectedAppointment(undefined);
    setIsFormOpen(true);
  };

  const handleEdit = () => {
    if (selectedAppointment) {
      setIsFormOpen(true);
    }
  };

  const handleRowDoubleClick = (appointment: D365Appointment) => {
    setSelectedAppointment(appointment);
    setIsFormOpen(true);
  };

  const handleDelete = () => {
    if (selectedAppointment) {
      setAppointmentToDelete(selectedAppointment);
      setIsDeleteDialogOpen(true);
    }
  };

  const confirmDelete = async () => {
    if (appointmentToDelete) {
      try {
        await d365AppointmentService.delete(appointmentToDelete.id);
        setIsDeleteDialogOpen(false);
        setAppointmentToDelete(undefined);
        await loadAppointments();
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to delete appointment');
      }
    }
  };

  const exportToExcel = (appointmentsToExport: D365Appointment[]) => {
    const exportData = appointmentsToExport.map((appointment) => ({
      'Subject': appointment.subject || '',
      'Location': appointment.location || '',
      'Scheduled Start': appointment.scheduledStart || '',
      'Scheduled End': appointment.scheduledEnd || '',
      'Scheduled Duration (min)': appointment.scheduledDurationMinutes || 0,
      'Actual Duration (min)': appointment.actualDurationMinutes || 0,
      'Description': appointment.description || '',
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Appointments');
    XLSX.writeFile(wb, `D365_Appointments_Export_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleExportSelected = () => {
    const selected = selection.getSelection() as D365Appointment[];
    if (selected.length > 0) {
      exportToExcel(selected);
    }
    setIsExportDialogOpen(false);
  };

  const handleExportAll = () => {
    exportToExcel(filteredAppointments);
    setIsExportDialogOpen(false);
  };

  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet);
        console.log('Imported data:', jsonData);
      } catch (err) {
        setError('Failed to import Excel file');
      }
    };
    reader.readAsBinaryString(file);
    event.target.value = '';
  };

  const handleViewChange = (view: GridView) => {
    setCurrentView(view);
  };

  const handleSaveView = (view: GridView) => {
    const updatedViews = views.find(v => v.id === view.id)
      ? views.map(v => v.id === view.id ? view : v)
      : [...views, view];

    setViews(updatedViews);
    setCurrentView(view);
    localStorage.setItem('d365appointments-views', JSON.stringify(updatedViews));
  };

  const handleDeleteView = (viewId: string) => {
    const updatedViews = views.filter(v => v.id !== viewId);
    setViews(updatedViews);
    localStorage.setItem('d365appointments-views', JSON.stringify(updatedViews));
  };

  const handleSetDefaultView = (viewId: string) => {
    const updatedViews = views.map(v => ({
      ...v,
      isDefault: v.id === viewId,
    }));
    setViews(updatedViews);
    localStorage.setItem('d365appointments-views', JSON.stringify(updatedViews));
  };

  const handleFiltersChange = (filters: GridFilter[]) => {
    const updatedView = { ...currentView, filters };
    setCurrentView(updatedView);
  };

  const updateCurrentViewColumns = (visibility: { [key: string]: boolean }, order: string[]) => {
    const updatedView = {
      ...currentView,
      columnVisibility: visibility,
      columnOrder: order,
    };
    setCurrentView(updatedView);
  };

  const moveColumnUp = (columnKey: string) => {
    const currentIndex = currentView.columnOrder.indexOf(columnKey);
    if (currentIndex > 0) {
      const newOrder = [...currentView.columnOrder];
      [newOrder[currentIndex - 1], newOrder[currentIndex]] = [newOrder[currentIndex], newOrder[currentIndex - 1]];
      updateCurrentViewColumns(currentView.columnVisibility, newOrder);
    }
  };

  const moveColumnDown = (columnKey: string) => {
    const currentIndex = currentView.columnOrder.indexOf(columnKey);
    if (currentIndex < currentView.columnOrder.length - 1) {
      const newOrder = [...currentView.columnOrder];
      [newOrder[currentIndex], newOrder[currentIndex + 1]] = [newOrder[currentIndex + 1], newOrder[currentIndex]];
      updateCurrentViewColumns(currentView.columnVisibility, newOrder);
    }
  };

  const onColumnClick = (ev?: React.MouseEvent<HTMLElement>, column?: IColumn) => {
    if (!column) return;

    const columnKey = column.key;
    if (sortColumn === columnKey) {
      setIsSortedDescending(!isSortedDescending);
    } else {
      setSortColumn(columnKey);
      setIsSortedDescending(false);
    }
  };

  const availableFields = [
    { key: 'subject', name: 'Subject', type: 'text' as const },
    { key: 'location', name: 'Location', type: 'text' as const },
    { key: 'scheduledStart', name: 'Scheduled Start', type: 'text' as const },
    { key: 'scheduledDurationMinutes', name: 'Duration (min)', type: 'number' as const },
  ];

  const allColumns: IColumn[] = [
    {
      key: 'subject',
      name: 'Subject',
      fieldName: 'subject',
      minWidth: 150,
      maxWidth: 250,
      isResizable: true,
      isSorted: sortColumn === 'subject',
      isSortedDescending: sortColumn === 'subject' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'location',
      name: 'Location',
      fieldName: 'location',
      minWidth: 120,
      maxWidth: 200,
      isResizable: true,
      isSorted: sortColumn === 'location',
      isSortedDescending: sortColumn === 'location' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'scheduledStart',
      name: 'Scheduled Start',
      fieldName: 'scheduledStart',
      minWidth: 130,
      maxWidth: 160,
      isResizable: true,
      isSorted: sortColumn === 'scheduledStart',
      isSortedDescending: sortColumn === 'scheduledStart' && isSortedDescending,
      onColumnClick: onColumnClick,
      onRender: (item: D365Appointment) => <Text>{item.scheduledStart ? new Date(item.scheduledStart).toLocaleDateString() : '-'}</Text>,
    },
    {
      key: 'scheduledEnd',
      name: 'Scheduled End',
      fieldName: 'scheduledEnd',
      minWidth: 130,
      maxWidth: 160,
      isResizable: true,
      isSorted: sortColumn === 'scheduledEnd',
      isSortedDescending: sortColumn === 'scheduledEnd' && isSortedDescending,
      onColumnClick: onColumnClick,
      onRender: (item: D365Appointment) => <Text>{item.scheduledEnd ? new Date(item.scheduledEnd).toLocaleDateString() : '-'}</Text>,
    },
    {
      key: 'scheduledDurationMinutes',
      name: 'Duration (min)',
      fieldName: 'scheduledDurationMinutes',
      minWidth: 110,
      maxWidth: 130,
      isResizable: true,
      isSorted: sortColumn === 'scheduledDurationMinutes',
      isSortedDescending: sortColumn === 'scheduledDurationMinutes' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'description',
      name: 'Description',
      fieldName: 'description',
      minWidth: 200,
      maxWidth: 300,
      isResizable: true,
      isSorted: sortColumn === 'description',
      isSortedDescending: sortColumn === 'description' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
    {
      key: 'actualDurationMinutes',
      name: 'Actual Duration (min)',
      fieldName: 'actualDurationMinutes',
      minWidth: 130,
      maxWidth: 150,
      isResizable: true,
      isSorted: sortColumn === 'actualDurationMinutes',
      isSortedDescending: sortColumn === 'actualDurationMinutes' && isSortedDescending,
      onColumnClick: onColumnClick,
    },
  ];

  const orderedColumns = currentView.columnOrder.map(key => allColumns.find(col => col.key === key)).filter(Boolean) as IColumn[];
  const columns = orderedColumns.filter((col) => currentView.columnVisibility[col.key]);

  const commandBarItems: ICommandBarItemProps[] = [
    {
      key: 'new',
      text: 'New',
      iconProps: { iconName: 'Add' },
      onClick: handleNew,
    },
    {
      key: 'edit',
      text: 'Edit',
      iconProps: { iconName: 'Edit' },
      disabled: !selectedAppointment,
      onClick: handleEdit,
    },
    {
      key: 'delete',
      text: 'Delete',
      iconProps: { iconName: 'Delete' },
      disabled: !selectedAppointment,
      onClick: handleDelete,
    },
    {
      key: 'refresh',
      text: 'Refresh',
      iconProps: { iconName: 'Refresh' },
      onClick: loadAppointments,
    },
    {
      key: 'export',
      text: 'Export to Excel',
      iconProps: { iconName: 'ExcelDocument' },
      onClick: () => setIsExportDialogOpen(true),
    },
    {
      key: 'import',
      text: 'Import from Excel',
      iconProps: { iconName: 'ExcelLogoInverse' },
      onClick: () => document.getElementById('appointments-import-input')?.click(),
    },
  ];

  const commandBarFarItems: ICommandBarItemProps[] = [
    {
      key: 'search',
      onRender: () => (
        <SearchBox
          placeholder="Search all columns..."
          value={searchText}
          onChange={(_, value) => setSearchText(value || '')}
          onClear={() => setSearchText('')}
          styles={{ root: { width: 300 } }}
        />
      ),
    },
  ];

  if (isFormOpen) {
    return (
      <Stack styles={{ root: { height: '100vh', overflow: 'hidden' } }}>
        <D365AppointmentForm
          appointment={selectedAppointment}
          onDismiss={() => {
            setIsFormOpen(false);
            setSelectedAppointment(undefined);
          }}
          onSave={() => {
            loadAppointments();
            setIsFormOpen(false);
            setSelectedAppointment(undefined);
          }}
          onDelete={selectedAppointment ? () => {
            setIsFormOpen(false);
            handleDelete();
          } : undefined}
        />
      </Stack>
    );
  }

  return (
    <Stack tokens={{ childrenGap: 16 }}>
      <Text variant="xxLarge">D365 Appointments</Text>

      <CommandBar items={commandBarItems} farItems={commandBarFarItems} />

      <input
        id="appointments-import-input"
        type="file"
        accept=".xlsx,.xls"
        style={{ display: 'none' }}
        onChange={handleImport}
      />

      {error && (
        <MessageBar messageBarType={MessageBarType.error} onDismiss={() => setError(null)}>
          {error}
        </MessageBar>
      )}

      <Stack
        horizontal
        verticalAlign="center"
        tokens={{ childrenGap: 8 }}
        styles={{
          root: {
            padding: '8px 12px',
            backgroundColor: '#faf9f8',
            borderBottom: '1px solid #edebe9',
          },
        }}
      >
        <ViewManager
          views={views}
          currentView={currentView}
          onViewChange={handleViewChange}
          onSaveView={handleSaveView}
          onDeleteView={handleDeleteView}
          onSetDefaultView={handleSetDefaultView}
        />

        <IconButton
          iconProps={{ iconName: 'ColumnOptions' }}
          title="Column Settings"
          ariaLabel="Column Settings"
          onClick={() => setIsColumnPanelOpen(true)}
        />

        <IconButton
          iconProps={{ iconName: 'Filter' }}
          title="Filter"
          ariaLabel="Filter"
          onClick={() => setIsFilterBuilderOpen(true)}
        />

        <Separator vertical styles={{ root: { height: 24 } }} />

        <Text variant="medium" styles={{ root: { marginLeft: 8 } }}>
          {filteredAppointments.length} {filteredAppointments.length === 1 ? 'appointment' : 'appointments'}
        </Text>
      </Stack>

      {loading ? (
        <Stack horizontalAlign="center" tokens={{ padding: 40 }}>
          <Spinner size={SpinnerSize.large} label="Loading appointments..." />
        </Stack>
      ) : (
        <div style={{ overflowX: 'auto', overflowY: 'visible' }}>
          <DetailsList
            items={filteredAppointments}
            columns={columns}
            layoutMode={DetailsListLayoutMode.justified}
            constrainMode={ConstrainMode.unconstrained}
            selection={selection}
            selectionPreservedOnEmptyClick
            onItemInvoked={handleRowDoubleClick}
            styles={{
              root: {
                selectors: {
                  '.ms-DetailsRow': {
                    cursor: 'pointer',
                  },
                },
              },
            }}
          />
        </div>
      )}

      <Panel
        isOpen={isColumnPanelOpen}
        onDismiss={() => setIsColumnPanelOpen(false)}
        headerText="Column Settings"
        closeButtonAriaLabel="Close"
      >
        <Stack tokens={{ childrenGap: 16 }}>
          <Text variant="medium">Show/Hide Columns</Text>
          {currentView.columnOrder.map((columnKey) => {
            const column = allColumns.find((col) => col.key === columnKey);
            if (!column) return null;

            return (
              <Stack key={columnKey} horizontal verticalAlign="center" tokens={{ childrenGap: 8 }}>
                <Checkbox
                  label={column.name}
                  checked={currentView.columnVisibility[columnKey]}
                  onChange={(_, checked) => {
                    updateCurrentViewColumns(
                      { ...currentView.columnVisibility, [columnKey]: !!checked },
                      currentView.columnOrder
                    );
                  }}
                  styles={{ root: { flex: 1 } }}
                />
                <IconButton
                  iconProps={{ iconName: 'Up' }}
                  title="Move up"
                  ariaLabel="Move up"
                  onClick={() => moveColumnUp(columnKey)}
                  disabled={currentView.columnOrder.indexOf(columnKey) === 0}
                />
                <IconButton
                  iconProps={{ iconName: 'Down' }}
                  title="Move down"
                  ariaLabel="Move down"
                  onClick={() => moveColumnDown(columnKey)}
                  disabled={
                    currentView.columnOrder.indexOf(columnKey) ===
                    currentView.columnOrder.length - 1
                  }
                />
              </Stack>
            );
          })}
        </Stack>
      </Panel>

      <FilterBuilder
        isOpen={isFilterBuilderOpen}
        onDismiss={() => setIsFilterBuilderOpen(false)}
        filters={currentView.filters || []}
        onFiltersChange={handleFiltersChange}
        availableFields={availableFields}
      />

      {isExportDialogOpen && (
        <Panel
          isOpen={isExportDialogOpen}
          onDismiss={() => setIsExportDialogOpen(false)}
          headerText="Export to Excel"
          closeButtonAriaLabel="Close"
        >
          <Stack tokens={{ childrenGap: 16 }}>
            <Text>Choose what to export:</Text>
            <Stack tokens={{ childrenGap: 8 }}>
              <button
                onClick={handleExportAll}
                style={{
                  padding: '10px 16px',
                  backgroundColor: '#0078d4',
                  color: 'white',
                  border: 'none',
                  borderRadius: '2px',
                  cursor: 'pointer',
                }}
              >
                Export All ({filteredAppointments.length} appointments)
              </button>
              <button
                onClick={handleExportSelected}
                disabled={selection.getSelectedCount() === 0}
                style={{
                  padding: '10px 16px',
                  backgroundColor:
                    selection.getSelectedCount() === 0 ? '#f3f2f1' : '#0078d4',
                  color: selection.getSelectedCount() === 0 ? '#a19f9d' : 'white',
                  border: 'none',
                  borderRadius: '2px',
                  cursor: selection.getSelectedCount() === 0 ? 'not-allowed' : 'pointer',
                }}
              >
                Export Selected ({selection.getSelectedCount()} appointments)
              </button>
            </Stack>
          </Stack>
        </Panel>
      )}

      <DeleteDialog
        isOpen={isDeleteDialogOpen}
        title="Delete Appointment"
        message={`Are you sure you want to delete "${appointmentToDelete?.subject}"?`}
        onConfirm={confirmDelete}
        onCancel={() => setIsDeleteDialogOpen(false)}
      />
    </Stack>
  );
};

frontend/src/components/AdvancedSearchDi.content:
import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogType,
  DialogFooter,
  PrimaryButton,
  DefaultButton,
  Stack,
  DetailsList,
  DetailsListLayoutMode,
  Selection,
  SelectionMode,
  SearchBox,
  Spinner,
  SpinnerSize,
  Text
} from '@fluentui/react';
import type { IColumn } from '@fluentui/react';
import type { LookupOption } from './LookupField';

interface AdvancedSearchDialogProps {
  isOpen: boolean;
  onDismiss: () => void;
  onSelect: (option: LookupOption) => void;
  entityName: string;
  columns: IColumn[];
  items: any[];
  onSearch?: (query: string) => void;
  isLoading?: boolean;
}

export const AdvancedSearchDialog: React.FC<AdvancedSearchDialogProps> = ({
  isOpen,
  onDismiss,
  onSelect,
  entityName,
  columns,
  items,
  onSearch,
  isLoading = false
}) => {
  const [selectedItem, setSelectedItem] = useState<any>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const selection = new Selection({
    onSelectionChanged: () => {
      const selected = selection.getSelection()[0];
      setSelectedItem(selected || null);
    }
  });

  useEffect(() => {
    if (!isOpen) {
      setSelectedItem(null);
      setSearchQuery('');
    }
  }, [isOpen]);

  const handleSelect = () => {
    if (selectedItem) {
      onSelect({
        id: selectedItem.id,
        text: selectedItem.text || selectedItem.name || selectedItem.id,
        record: selectedItem
      });
      onDismiss();
    }
  };

  const handleSearchChange = (_event?: React.ChangeEvent<HTMLInputElement>, newValue?: string) => {
    setSearchQuery(newValue || '');
    if (onSearch) {
      onSearch(newValue || '');
    }
  };

  return (
    <Dialog
      hidden={!isOpen}
      onDismiss={onDismiss}
      dialogContentProps={{
        type: DialogType.largeHeader,
        title: `Advanced Search: ${entityName}`,
        subText: `Search and select a ${entityName.toLowerCase()} record`
      }}
      modalProps={{
        isBlocking: false,
        styles: { main: { maxWidth: 800, minWidth: 600 } }
      }}
    >
      <Stack tokens={{ childrenGap: 16 }}>
        <SearchBox
          placeholder={`Search ${entityName}...`}
          value={searchQuery}
          onChange={handleSearchChange}
          autoFocus
        />

        {isLoading ? (
          <Stack horizontal horizontalAlign="center" tokens={{ padding: 40 }}>
            <Spinner size={SpinnerSize.large} label={`Loading ${entityName}...`} />
          </Stack>
        ) : items.length === 0 ? (
          <Stack horizontalAlign="center" tokens={{ padding: 40 }}>
            <Text variant="mediumPlus" styles={{ root: { color: '#605e5c' } }}>
              No {entityName.toLowerCase()} records found
            </Text>
          </Stack>
        ) : (
          <div style={{ maxHeight: 400, overflow: 'auto' }}>
            <DetailsList
              items={items}
              columns={columns}
              selection={selection}
              selectionMode={SelectionMode.single}
              layoutMode={DetailsListLayoutMode.justified}
              isHeaderVisible={true}
              selectionPreservedOnEmptyClick={true}
            />
          </div>
        )}

        <Stack horizontal tokens={{ childrenGap: 8 }}>
          <Text variant="small" styles={{ root: { color: '#605e5c', marginTop: 8 } }}>
            {items.length} record{items.length !== 1 ? 's' : ''} found
            {selectedItem && ` • Selected: ${selectedItem.text || selectedItem.name || selectedItem.id}`}
          </Text>
        </Stack>
      </Stack>

      <DialogFooter>
        <PrimaryButton
          onClick={handleSelect}
          text="Select"
          disabled={!selectedItem}
        />
        <DefaultButton onClick={onDismiss} text="Cancel" />
      </DialogFooter>
    </Dialog>
  );
};

frontend/src/components/LookupField.tsx.content:
import React, { useState, useEffect, useRef } from 'react';
import {
  TextField,
  IconButton,
  Callout,
  DirectionalHint,
  Stack,
  Text,
  Spinner,
  SpinnerSize,
  Icon,
  DefaultButton,
  PrimaryButton,
  ChoiceGroup,
  Separator
} from '@fluentui/react';
import { useId, useBoolean } from '@fluentui/react-hooks';

export interface LookupOption {
  id: string;
  text: string;
  subText?: string;
  record?: any;
}

interface LookupFieldProps {
  label: string;
  value?: string;
  selectedText?: string;
  options: LookupOption[];
  onChange: (id: string | undefined, text: string | undefined, record?: any) => void;
  onSearch?: (query: string) => Promise<LookupOption[]>;
  placeholder?: string;
  required?: boolean;
  disabled?: boolean;
  error?: string;
  onCreateNew?: () => void;
  onAdvancedSearch?: () => void;
  showPeekView?: boolean;
  peekViewContent?: React.ReactNode;
  entityName?: string;
}

export const LookupField: React.FC<LookupFieldProps> = ({
  label,
  value,
  selectedText,
  options,
  onChange,
  onSearch,
  placeholder,
  required,
  disabled,
  error,
  onCreateNew,
  onAdvancedSearch,
  showPeekView,
  peekViewContent,
  entityName = 'Record'
}) => {
  const [searchText, setSearchText] = useState(selectedText || '');
  const [filteredOptions, setFilteredOptions] = useState<LookupOption[]>([]);
  const [isCalloutVisible, { setTrue: showCallout, setFalse: hideCallout }] = useBoolean(false);
  const [isSearching, setIsSearching] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const [showPeek, { setTrue: openPeek, setFalse: closePeek }] = useBoolean(false);
  const [createMode, setCreateMode] = useState(false);

  const textFieldRef = useRef<HTMLDivElement>(null);
  const calloutId = useId('callout');
  const peekButtonId = useId('peek-button');

  // Filter options based on search text (only for client-side filtering)
  useEffect(() => {
    // Skip client-side filtering if async search is available
    if (onSearch) {
      return;
    }

    if (!searchText.trim()) {
      setFilteredOptions(options);
      return;
    }

    const searchLower = searchText.toLowerCase();
    const filtered = options.filter(
      opt => 
        opt.text.toLowerCase().includes(searchLower) ||
        opt.subText?.toLowerCase().includes(searchLower)
    );

    setFilteredOptions(filtered);
  }, [searchText, options, onSearch]);

  // Update search text when selectedText prop changes
  useEffect(() => {
    if (selectedText !== undefined) {
      setSearchText(selectedText);
    }
  }, [selectedText]);

  const handleSearchChange = async (_event: React.FormEvent<HTMLInputElement | HTMLTextAreaElement>, newValue?: string) => {
    const value = newValue || '';
    setSearchText(value);
    setSelectedIndex(-1);

    if (!isCalloutVisible) {
      showCallout();
    }

    // If onSearch callback provided, use it for async search
    if (onSearch && value.trim()) {
      setIsSearching(true);
      try {
        const results = await onSearch(value);
        setFilteredOptions(results);
      } catch (err) {
        console.error('Search error:', err);
      } finally {
        setIsSearching(false);
      }
    }
  };

  const handleOptionSelect = (option: LookupOption) => {
    setSearchText(option.text);
    onChange(option.id, option.text, option.record);
    hideCallout();
    setCreateMode(false);
  };

  const handleClear = () => {
    setSearchText('');
    onChange(undefined, undefined);
    setCreateMode(false);
  };

  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (!isCalloutVisible) {
      if (event.key === 'ArrowDown' || event.key === 'Enter') {
        showCallout();
        event.preventDefault();
      }
      return;
    }

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        setSelectedIndex(prev => Math.min(prev + 1, filteredOptions.length - 1));
        break;
      case 'ArrowUp':
        event.preventDefault();
        setSelectedIndex(prev => Math.max(prev - 1, -1));
        break;
      case 'Enter':
        event.preventDefault();
        if (selectedIndex >= 0 && filteredOptions[selectedIndex]) {
          handleOptionSelect(filteredOptions[selectedIndex]);
        }
        break;
      case 'Escape':
        event.preventDefault();
        hideCallout();
        break;
    }
  };

  const handleFocus = () => {
    showCallout();
  };

  const handleCreateNewClick = () => {
    if (onCreateNew) {
      hideCallout();
      onCreateNew();
    }
  };

  const handleAdvancedSearchClick = () => {
    if (onAdvancedSearch) {
      hideCallout();
      onAdvancedSearch();
    }
  };

  const renderNoResults = () => {
    if (isSearching) {
      return (
        <Stack horizontal horizontalAlign="center" tokens={{ padding: 20 }}>
          <Spinner size={SpinnerSize.small} label="Searching..." />
        </Stack>
      );
    }

    if (!onCreateNew) {
      return (
        <Stack tokens={{ padding: 20 }}>
          <Text variant="small" styles={{ root: { color: '#605e5c' } }}>
            No records found
          </Text>
        </Stack>
      );
    }

    return (
      <Stack tokens={{ padding: 20, childrenGap: 12 }}>
        <Stack horizontal tokens={{ childrenGap: 8 }}>
          <Icon iconName="Info" styles={{ root: { color: '#605e5c', fontSize: 16, marginTop: 2 } }} />
          <Text variant="small" styles={{ root: { color: '#605e5c' } }}>
            No records found matching "{searchText}"
          </Text>
        </Stack>

        <Separator />

        <Stack tokens={{ childrenGap: 8 }}>
          <ChoiceGroup
            options={[
              { key: 'create', text: `Create new ${entityName}` }
            ]}
            selectedKey={createMode ? 'create' : undefined}
            onChange={() => setCreateMode(true)}
          />

          {createMode && (
            <Stack horizontal tokens={{ childrenGap: 8 }}>
              <PrimaryButton
                text="Create"
                iconProps={{ iconName: 'Add' }}
                onClick={handleCreateNewClick}
              />
              <DefaultButton
                text="Cancel"
                onClick={() => setCreateMode(false)}
              />
            </Stack>
          )}
        </Stack>
      </Stack>
    );
  };

  return (
    <Stack tokens={{ childrenGap: 4 }}>
      <Stack horizontal tokens={{ childrenGap: 8 }} verticalAlign="end">
        <Stack.Item grow>
          <div ref={textFieldRef}>
            <TextField
              label={label}
              value={searchText}
              onChange={handleSearchChange}
              onKeyDown={handleKeyDown}
              onFocus={handleFocus}
              placeholder={placeholder || `Search for ${entityName}...`}
              required={required}
              disabled={disabled}
              errorMessage={error}
              iconProps={searchText ? { iconName: 'Clear', onClick: handleClear } : undefined}
              styles={{
                root: { position: 'relative' },
                field: { paddingRight: onAdvancedSearch ? 60 : 30 }
              }}
            />
          </div>
        </Stack.Item>

        {onAdvancedSearch && (
          <IconButton
            iconProps={{ iconName: 'Search' }}
            title="Advanced Search"
            ariaLabel="Advanced Search"
            onClick={handleAdvancedSearchClick}
            styles={{ 
              root: { 
                height: 32, 
                marginBottom: error ? 20 : 0 
              } 
            }}
          />
        )}

        {showPeekView && value && peekViewContent && (
          <IconButton
            id={peekButtonId}
            iconProps={{ iconName: 'RedEye' }}
            title="Preview"
            ariaLabel="Preview record"
            onClick={openPeek}
            styles={{ 
              root: { 
                height: 32, 
                marginBottom: error ? 20 : 0 
              } 
            }}
          />
        )}
      </Stack>

      {isCalloutVisible && textFieldRef.current && (
        <Callout
          id={calloutId}
          target={textFieldRef.current}
          onDismiss={hideCallout}
          directionalHint={DirectionalHint.bottomLeftEdge}
          isBeakVisible={false}
          styles={{ 
            root: { 
              minWidth: textFieldRef.current.offsetWidth,
              maxWidth: 400,
              maxHeight: 300,
              overflow: 'auto'
            } 
          }}
        >
          {filteredOptions.length === 0 ? (
            renderNoResults()
          ) : (
            <Stack>
              {filteredOptions.map((option, index) => (
                <Stack
                  key={option.id}
                  onClick={() => handleOptionSelect(option)}
                  tokens={{ padding: '8px 12px' }}
                  styles={{
                    root: {
                      cursor: 'pointer',
                      backgroundColor: index === selectedIndex ? '#f3f2f1' : 'transparent',
                      ':hover': {
                        backgroundColor: '#f3f2f1'
                      }
                    }
                  }}
                >
                  <Text variant="medium">{option.text}</Text>
                  {option.subText && (
                    <Text variant="small" styles={{ root: { color: '#605e5c' } }}>
                      {option.subText}
                    </Text>
                  )}
                </Stack>
              ))}
            </Stack>
          )}
        </Callout>
      )}

      {showPeek && (
        <Callout
          target={`#${peekButtonId}`}
          onDismiss={closePeek}
          directionalHint={DirectionalHint.bottomRightEdge}
          isBeakVisible={true}
          styles={{ 
            root: { 
              padding: 20,
              minWidth: 300,
              maxWidth: 400
            } 
          }}
        >
          {peekViewContent}
        </Callout>
      )}
    </Stack>
  );
};

frontend/src/components/SubGrid.tsx.content:
import React, { useState, useEffect, useMemo } from 'react';
import {
  Stack,
  Text,
  DetailsList,
  DetailsListLayoutMode,
  SelectionMode,
  Selection,
  CommandBar,
  MessageBar,
  MessageBarType,
  ShimmeredDetailsList,
  IconButton,
  Dropdown
} from '@fluentui/react';
import type { IColumn, ICommandBarItemProps, IDropdownOption } from '@fluentui/react';

export interface SubGridColumn {
  key: string;
  name: string;
  fieldName: string;
  minWidth: number;
  maxWidth?: number;
  isResizable?: boolean;
  onRender?: (item: any) => React.ReactNode;
}

interface SubGridProps {
  title: string;
  items: any[];
  columns: SubGridColumn[];
  loading?: boolean;
  error?: string;
  onRefresh?: () => void;
  onAdd?: () => void;
  onItemClick?: (item: any) => void;
  onDelete?: (item: any) => void;
  emptyMessage?: string;
  maxHeight?: number;
  pageSize?: number;
}

export const SubGrid: React.FC<SubGridProps> = ({
  title,
  items,
  columns,
  loading = false,
  error,
  onRefresh,
  onAdd,
  onItemClick,
  onDelete,
  emptyMessage = 'No records found',
  maxHeight = 300,
  pageSize = 10
}) => {
  const [currentPage, setCurrentPage] = useState(0);
  const [selectedItem, setSelectedItem] = useState<any | null>(null);
  const [selectedPageSize, setSelectedPageSize] = useState<number>(pageSize);

  // Memoized Selection object for stable selection handling
  const selection = useMemo(
    () =>
      new Selection({
        onSelectionChanged: () => {
          const selected = selection.getSelection()[0];
          setSelectedItem(selected || null);
        }
      }),
    []
  );

  // Reset to first page when items change
  useEffect(() => {
    setCurrentPage(0);
    selection.setAllSelected(false);
    setSelectedItem(null);
  }, [items.length, selectedPageSize, selection]);

  // Clear selection when page changes
  useEffect(() => {
    selection.setAllSelected(false);
    setSelectedItem(null);
  }, [currentPage, selection]);

  const commandBarItems: ICommandBarItemProps[] = [
    ...(onAdd ? [{
      key: 'add',
      text: 'Add',
      iconProps: { iconName: 'Add' },
      onClick: onAdd
    }] : []),
    ...(onRefresh ? [{
      key: 'refresh',
      text: 'Refresh',
      iconProps: { iconName: 'Refresh' },
      onClick: onRefresh
    }] : []),
    ...(onDelete && selectedItem ? [{
      key: 'delete',
      text: 'Remove',
      iconProps: { iconName: 'Delete' },
      onClick: () => {
        if (selectedItem && onDelete) {
          onDelete(selectedItem);
          setSelectedItem(null);
        }
      }
    }] : [])
  ];

  const handleRowClick = (item: any) => {
    if (onItemClick) {
      onItemClick(item);
    }
  };

  const gridColumns: IColumn[] = columns.map((col, index) => ({
    key: col.key,
    name: col.name,
    fieldName: col.fieldName,
    minWidth: col.minWidth,
    maxWidth: col.maxWidth,
    isResizable: col.isResizable !== false,
    onRender: col.onRender || ((item: any) => {
      const value = item[col.fieldName];
      // Add single-click navigation to first column
      if (index === 0 && onItemClick) {
        return (
          <span
            onClick={(e) => {
              e.stopPropagation();
              handleRowClick(item);
            }}
            style={{ 
              cursor: 'pointer', 
              color: '#0078d4',
              textDecoration: 'underline'
            }}
          >
            {value}
          </span>
        );
      }
      return <span>{value}</span>;
    })
  }));

  const pageSizeOptions: IDropdownOption[] = [
    { key: 5, text: '5' },
    { key: 10, text: '10' },
    { key: 25, text: '25' },
    { key: 50, text: '50' },
    { key: 100, text: '100' }
  ];

  const effectivePageSize = selectedPageSize;
  const effectiveTotalPages = Math.ceil(items.length / effectivePageSize);
  const effectiveStartIndex = currentPage * effectivePageSize;
  const effectiveEndIndex = Math.min(effectiveStartIndex + effectivePageSize, items.length);
  const effectivePaginatedItems = items.slice(effectiveStartIndex, effectiveEndIndex);

  return (
    <Stack 
      tokens={{ childrenGap: 8 }} 
      styles={{ 
        root: { 
          border: '1px solid #edebe9',
          borderRadius: 4,
          padding: 16,
          backgroundColor: '#ffffff'
        } 
      }}
    >
      {/* Header with title and count */}
      <Stack horizontal horizontalAlign="space-between" verticalAlign="center">
        <Text variant="mediumPlus" styles={{ root: { fontWeight: 600, color: '#323130' } }}>
          {title} ({items.length})
        </Text>
      </Stack>

      {/* Command bar */}
      {commandBarItems.length > 0 && (
        <CommandBar
          items={commandBarItems}
          styles={{
            root: {
              padding: 0,
              height: 44
            }
          }}
        />
      )}

      {/* Error message */}
      {error && (
        <MessageBar messageBarType={MessageBarType.error}>
          {error}
        </MessageBar>
      )}

      {/* Grid */}
      <div style={{ 
        maxHeight, 
        overflowY: 'auto',
        overflowX: 'auto',
        border: '1px solid #edebe9',
        borderRadius: 4
      }}>
        {loading ? (
          <ShimmeredDetailsList
            items={[]}
            columns={gridColumns}
            layoutMode={DetailsListLayoutMode.justified}
            selectionMode={SelectionMode.single}
            enableShimmer={true}
            shimmerLines={5}
          />
        ) : items.length === 0 ? (
          <Stack
            horizontalAlign="center"
            verticalAlign="center"
            tokens={{ padding: 40 }}
          >
            <Text variant="medium" styles={{ root: { color: '#605e5c' } }}>
              {emptyMessage}
            </Text>
          </Stack>
        ) : (
          <DetailsList
            items={effectivePaginatedItems}
            columns={gridColumns}
            layoutMode={DetailsListLayoutMode.justified}
            selectionMode={SelectionMode.single}
            selection={selection}
            onItemInvoked={handleRowClick}
            onActiveItemChanged={(item) => {
              if (item) {
                setSelectedItem(item);
              }
            }}
            styles={{
              root: {
                '& [role=grid]': {
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'start'
                }
              }
            }}
          />
        )}
      </div>

      {/* Pagination controls */}
      {items.length > 0 && (
        <Stack horizontal horizontalAlign="space-between" verticalAlign="center" tokens={{ childrenGap: 12 }}>
          <Stack horizontal tokens={{ childrenGap: 8 }} verticalAlign="center">
            <Text variant="small">Rows per page:</Text>
            <Dropdown
              options={pageSizeOptions}
              selectedKey={selectedPageSize}
              onChange={(_, option) => option && setSelectedPageSize(option.key as number)}
              styles={{ dropdown: { width: 70 } }}
            />
          </Stack>

          <Stack horizontal tokens={{ childrenGap: 8 }} verticalAlign="center">
            <Text variant="small">
              {effectiveStartIndex + 1}-{effectiveEndIndex} of {items.length}
            </Text>
            <IconButton
              iconProps={{ iconName: 'ChevronLeft' }}
              disabled={currentPage === 0}
              onClick={() => setCurrentPage(currentPage - 1)}
              title="Previous page"
            />
            <Text variant="small">
              Page {currentPage + 1} of {effectiveTotalPages}
            </Text>
            <IconButton
              iconProps={{ iconName: 'ChevronRight' }}
              disabled={currentPage >= effectiveTotalPages - 1}
              onClick={() => setCurrentPage(currentPage + 1)}
              title="Next page"
            />
          </Stack>
        </Stack>
      )}
    </Stack>
  );
};

