import React from 'react';
import { Stack, Text, Separator } from '@fluentui/react';

interface PeekViewField {
  label: string;
  value?: string | number | boolean | null;
  render?: () => React.ReactNode;
}

interface PeekViewProps {
  title: string;
  fields: PeekViewField[];
}

export const PeekView: React.FC<PeekViewProps> = ({ title, fields }) => {
  const formatValue = (value?: string | number | boolean | null): string => {
    if (value === null || value === undefined) return '-';
    if (typeof value === 'boolean') return value ? 'Yes' : 'No';
    if (typeof value === 'number') return value.toLocaleString();
    return value.toString();
  };

  return (
    <Stack tokens={{ childrenGap: 12 }}>
      <Text variant="mediumPlus" styles={{ root: { fontWeight: 600, color: '#323130' } }}>
        {title}
      </Text>

      <Separator />

      <Stack tokens={{ childrenGap: 8 }}>
        {fields.map((field, index) => (
          <Stack key={index} tokens={{ childrenGap: 2 }}>
            <Text variant="small" styles={{ root: { color: '#605e5c', fontWeight: 600 } }}>
              {field.label}
            </Text>
            {field.render ? (
              field.render()
            ) : (
              <Text variant="medium" styles={{ root: { color: '#323130' } }}>
                {formatValue(field.value)}
              </Text>
            )}
          </Stack>
        ))}
      </Stack>
    </Stack>
  );
};

frontend/src/hooks/useLookupData.ts.content:
import { useState, useEffect } from 'react';
import { employeeService } from '../services/millenniumServices';
import { accountService, d365OrderService, d365ContactService } from '../services/d365Services';
import type { Employee, Account, D365Order, D365Contact } from '../types/millennium';

interface LookupData {
  employees: Map<string, string>;
  customers: Map<string, string>;
  salesOrders: Map<string, string>;
  contacts: Map<string, string>;
  loading: boolean;
}

export function useLookupData(): LookupData {
  const [lookupData, setLookupData] = useState<LookupData>({
    employees: new Map(),
    customers: new Map(),
    salesOrders: new Map(),
    contacts: new Map(),
    loading: true,
  });

  useEffect(() => {
    const loadLookupData = async () => {
      try {
        const [employees, customers, salesOrders, contacts] = await Promise.all([
          employeeService.getAll().catch(() => [] as Employee[]),
          accountService.getAll().catch(() => [] as Account[]),
          d365OrderService.getAll().catch(() => [] as D365Order[]),
          d365ContactService.getAll().catch(() => [] as D365Contact[]),
        ]);

        const employeeMap = new Map<string, string>(
          employees
            .filter((e: Employee) => e.id)
            .map((e: Employee) => [e.id.toLowerCase(), e.name || 'Unknown Employee'])
        );

        const customerMap = new Map<string, string>(
          customers
            .filter((c: Account) => c.id)
            .map((c: Account) => [c.id.toLowerCase(), c.name || 'Unknown Customer'])
        );

        const salesOrderMap = new Map<string, string>(
          salesOrders
            .filter((o: D365Order) => o.id)
            .map((o: D365Order) => [o.id.toLowerCase(), o.orderNumber || o.name || 'Unknown Order'])
        );

        const contactMap = new Map<string, string>(
          contacts
            .filter((c: D365Contact) => c.id)
            .map((c: D365Contact) => [c.id.toLowerCase(), c.fullName || `${c.firstName} ${c.lastName}`.trim() || 'Unknown Contact'])
        );

        setLookupData({
          employees: employeeMap,
          customers: customerMap,
          salesOrders: salesOrderMap,
          contacts: contactMap,
          loading: false,
        });
      } catch (error) {
        console.error('Failed to load lookup data:', error);
        setLookupData((prev) => ({ ...prev, loading: false }));
      }
    };

    loadLookupData();
  }, []);

  return lookupData;
}

export function resolveLookup(
  guid: string | null | undefined,
  lookupMap: Map<string, string>
): string {
  if (!guid) return '-';
  const name = lookupMap.get(guid.toLowerCase());
  return name || guid.substring(0, 8) + '...';
}

frontend/src/hooks/usePagination.ts.content:
import { useState, useEffect, useMemo } from 'react';

interface UsePaginationProps<T> {
  items: T[];
  initialPageSize?: number;
}

interface UsePaginationReturn<T> {
  currentPage: number;
  pageSize: number;
  paginatedItems: T[];
  totalPages: number;
  setCurrentPage: (page: number) => void;
  setPageSize: (size: number) => void;
}

export function usePagination<T>({
  items,
  initialPageSize = 50,
}: UsePaginationProps<T>): UsePaginationReturn<T> {
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(initialPageSize);

  const totalPages = useMemo(
    () => Math.max(1, Math.ceil(items.length / pageSize)),
    [items.length, pageSize]
  );

  useEffect(() => {
    if (currentPage > totalPages) {
      setCurrentPage(totalPages);
    }
  }, [currentPage, totalPages]);

  const paginatedItems = useMemo(() => {
    const startIndex = (currentPage - 1) * pageSize;
    const endIndex = startIndex + pageSize;
    return items.slice(startIndex, endIndex);
  }, [items, currentPage, pageSize]);

  return {
    currentPage,
    pageSize,
    paginatedItems,
    totalPages,
    setCurrentPage,
    setPageSize,
  };
}

frontend/src/components/Pagination.tsx.content:
import React from 'react';
import { Stack, IconButton, Dropdown, Text } from '@fluentui/react';
import type { IDropdownOption } from '@fluentui/react';

interface PaginationProps {
  currentPage: number;
  pageSize: number;
  totalRecords: number;
  onPageChange: (page: number) => void;
  onPageSizeChange: (pageSize: number) => void;
}

export const Pagination: React.FC<PaginationProps> = ({
  currentPage,
  pageSize,
  totalRecords,
  onPageChange,
  onPageSizeChange,
}) => {
  const totalPages = Math.max(1, Math.ceil(totalRecords / pageSize));
  const startRecord = totalRecords === 0 ? 0 : (currentPage - 1) * pageSize + 1;
  const endRecord = Math.min(currentPage * pageSize, totalRecords);

  const pageSizeOptions: IDropdownOption[] = [
    { key: 50, text: '50 per page' },
    { key: 100, text: '100 per page' },
  ];

  const handlePageSizeChange = (_: React.FormEvent<HTMLDivElement>, option?: IDropdownOption) => {
    if (option) {
      onPageSizeChange(option.key as number);
      onPageChange(1);
    }
  };

  const handlePreviousPage = () => {
    if (currentPage > 1) {
      onPageChange(currentPage - 1);
    }
  };

  const handleNextPage = () => {
    if (currentPage < totalPages) {
      onPageChange(currentPage + 1);
    }
  };

  return (
    <Stack
      horizontal
      horizontalAlign="space-between"
      verticalAlign="center"
      styles={{
        root: {
          padding: '12px 16px',
          borderTop: '1px solid #edebe9',
          backgroundColor: '#faf9f8',
        },
      }}
    >
      <Stack horizontal tokens={{ childrenGap: 12 }} verticalAlign="center">
        <Dropdown
          options={pageSizeOptions}
          selectedKey={pageSize}
          onChange={handlePageSizeChange}
          styles={{
            dropdown: { width: 130 },
          }}
        />
        <Text variant="small" styles={{ root: { color: '#605e5c' } }}>
          Showing {startRecord}-{endRecord} of {totalRecords} records
        </Text>
      </Stack>

      <Stack horizontal tokens={{ childrenGap: 8 }} verticalAlign="center">
        <IconButton
          iconProps={{ iconName: 'ChevronLeft' }}
          title="Previous page"
          disabled={currentPage === 1}
          onClick={handlePreviousPage}
          styles={{
            root: { height: 32 },
            rootDisabled: { backgroundColor: 'transparent' },
          }}
        />
        <Text variant="small" styles={{ root: { minWidth: 80, textAlign: 'center' } }}>
          Page {currentPage} of {totalPages}
        </Text>
        <IconButton
          iconProps={{ iconName: 'ChevronRight' }}
          title="Next page"
          disabled={currentPage === totalPages || totalPages === 0}
          onClick={handleNextPage}
          styles={{
            root: { height: 32 },
            rootDisabled: { backgroundColor: 'transparent' },
          }}
        />
      </Stack>
    </Stack>
  );
};

