import React, { useState, useEffect, useRef } from 'react';
import {
  TextField,
  IconButton,
  Stack,
  Text,
  Dialog,
  DialogFooter,
  DefaultButton,
  DetailsList,
  SelectionMode,
  SearchBox,
  Spinner,
