export const StandardLookupField: React.FC<StandardLookupFieldProps> = ({
  label,
  value,
  selectedText,
  entityName,
  onChange,
  onSearch,
  onNavigate,
  onTextChange,
  disabled = false,
  required = false,
  error,
}) => {
  const [searchText, setSearchText] = useState('');
  const [suggestions, setSuggestions] = useState<LookupOption[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const [isSearching, setIsSearching] = useState(false);
  const [isDialogOpen, { setTrue: openDialog, setFalse: closeDialog }] = useBoolean(false);
  const [dialogSearchText, setDialogSearchText] = useState('');
  const [allOptions, setAllOptions] = useState<LookupOption[]>([]);
  const [filteredDialogOptions, setFilteredDialogOptions] = useState<LookupOption[]>([]);

  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLDivElement>(null);
  const suggestionRefs = useRef<(HTMLDivElement | null)[]>([]);
  const calloutId = useId('standard-lookup-callout');

  const debouncedSearchText = useDebounce(searchText, 300);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    const performSearch = async () => {
      if (!debouncedSearchText.trim() || !onSearch) {
        setSuggestions([]);
        return;
      }

      setIsSearching(true);
      try {
        const results = await onSearch(debouncedSearchText);
        setSuggestions(results.slice(0, 3));
      } catch (err) {
        console.error('Search error:', err);
        setSuggestions([]);
      } finally {
        setIsSearching(false);
      }
    };

    performSearch();
  }, [debouncedSearchText, onSearch]);

  useEffect(() => {
    if (selectedIndex >= 0 && suggestionRefs.current[selectedIndex]) {
      suggestionRefs.current[selectedIndex]?.scrollIntoView({
        block: 'nearest',
      });
    }
  }, [selectedIndex]);

  const loadAllOptions = async () => {
    if (!onSearch) return;

    setIsSearching(true);
    try {
      const results = await onSearch('');
      setAllOptions(results);
      setFilteredDialogOptions(results);
    } catch (err) {
      console.error('Failed to load options:', err);
      setAllOptions([]);
      setFilteredDialogOptions([]);
    } finally {
      setIsSearching(false);
    }
  };

  const handleAdvancedSearchClick = () => {
    loadAllOptions();
    openDialog();
  };

  const handleDialogSearchChange = (_: any, newValue?: string) => {
    const searchValue = newValue || '';
    setDialogSearchText(searchValue);

    if (!searchValue.trim()) {
      setFilteredDialogOptions(allOptions);
      return;
    }

    const searchLower = searchValue.toLowerCase();
    const filtered = allOptions.filter(opt => 
      opt.text.toLowerCase().includes(searchLower)
    );
    setFilteredDialogOptions(filtered);
  };

  const handleOptionSelect = (option: LookupOption) => {
    onChange(option.id);
    onTextChange?.(option.text);
    setSearchText('');
    setShowSuggestions(false);
    setSuggestions([]);
    setSelectedIndex(-1);
  };

  const handleDialogSelect = (option: LookupOption) => {
    onChange(option.id);
    onTextChange?.(option.text);
    setDialogSearchText('');
    closeDialog();
  };

  const handleClear = () => {
    onChange(undefined);
    onTextChange?.('');
    setSearchText('');
    setSuggestions([]);
    setShowSuggestions(false);
  };

  const handleSearchChange = (_: any, newValue?: string) => {
    setSearchText(newValue || '');
    setShowSuggestions(true);
    setSelectedIndex(-1);
  };

  const handleFocus = () => {
    if (searchText.trim()) {
      setShowSuggestions(true);
    }
  };

  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (!showSuggestions) {
      if (event.key === 'ArrowDown') {
        setShowSuggestions(true);
        event.preventDefault();
      }
      return;
    }

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        setSelectedIndex(prev => Math.min(prev + 1, suggestions.length - 1));
        break;
      case 'ArrowUp':
        event.preventDefault();
        setSelectedIndex(prev => Math.max(prev - 1, -1));
        break;
      case 'Enter':
        event.preventDefault();
        if (selectedIndex >= 0 && suggestions[selectedIndex]) {
          handleOptionSelect(suggestions[selectedIndex]);
        }
        break;
      case 'Escape':
        event.preventDefault();
        setShowSuggestions(false);
        setSelectedIndex(-1);
        break;
      case 'Tab':
        setShowSuggestions(false);
        setSelectedIndex(-1);
        break;
    }
  };

  const highlightText = (text: string, searchTerm: string): React.ReactNode => {
    if (!searchTerm.trim()) return text;

    const regex = new RegExp(`(${searchTerm})`, 'gi');
    const parts = text.split(regex);

    return parts.map((part, index) => 
      regex.test(part) ? (
        <span key={index} className={styles.highlightedText}>{part}</span>
      ) : (
        <span key={index}>{part}</span>
      )
    );
  };

  const dialogColumns: IColumn[] = [
    {
      key: 'text',
      name: entityName,
      fieldName: 'text',
      minWidth: 200,
      maxWidth: 400,
      isResizable: true,
      onRender: (item: LookupOption) => (
        <Stack 
          onClick={() => handleDialogSelect(item)}
          styles={{ root: { cursor: 'pointer', padding: '4px 0' } }}
        >
          <Text>{item.text}</Text>
        </Stack>
      ),
    },
  ];

  return (
    <div ref={containerRef} style={{ position: 'relative' }}>
      <Stack tokens={{ childrenGap: 4 }}>
        <Stack.Item grow>
          <div>
            <label className={styles.fieldLabel}>
              {label}
              {required && <span className={styles.fieldLabelRequired}>*</span>}
            </label>

            <div 
              ref={inputRef}
              className={`${styles.customFieldContainer} ${
                disabled ? styles.customFieldContainerDisabled : ''
              } ${error ? styles.customFieldContainerError : ''}`}
              style={{ paddingRight: value && selectedText ? '8px' : '36px' }}
            >
              {value && selectedText ? (
                <div className={`${styles.chip} ${onNavigate ? styles.chipClickable : ''}`}>
                  <span 
                    className={styles.chipText} 
                    title={selectedText}
                    onClick={() => onNavigate && value && onNavigate(value)}
                    style={{ cursor: onNavigate ? 'pointer' : 'default' }}
                  >
                    {selectedText}
                  </span>
                  <button
                    className={styles.chipRemoveButton}
                    onClick={(e) => {
                      e.stopPropagation();
                      handleClear();
                    }}
                    disabled={disabled}
                    title="Remove"
                    aria-label="Remove selection"
                    type="button"
                  >
                    <span style={{ fontSize: '12px', lineHeight: 1 }}>×</span>
                  </button>
                </div>
              ) : (
                <TextField
                  value={searchText}
                  onChange={handleSearchChange}
                  onFocus={handleFocus}
                  onKeyDown={handleKeyDown}
                  placeholder={`Search ${entityName}...`}
                  disabled={disabled}
                  borderless
                  styles={{
                    root: { width: '100%' },
                    fieldGroup: { 
                      border: 'none',
                      minHeight: '22px',
                      height: '22px',
                    },
                    field: {
                      padding: 0,
                      fontSize: '14px',
                    },
                    wrapper: { 
                      selectors: {
                        '&::after': { display: 'none' }
                      }
                    }
                  }}
                  iconProps={
                    searchText && !disabled
                      ? { 
                          iconName: 'Clear', 
                          onClick: () => setSearchText(''),
                          styles: { root: { fontSize: '12px' } }
                        }
                      : { 
                          iconName: 'Search',
                          styles: { root: { fontSize: '12px' } }
                        }
                  }
                  aria-expanded={showSuggestions}
                  aria-controls={calloutId}
                  aria-autocomplete="list"
                />
              )}
            </div>

            {error && <span className={styles.errorMessage}>{error}</span>}
          </div>
        </Stack.Item>

        {showSuggestions && searchText.trim() && !value && (
          <div id={calloutId} className={styles.suggestionsContainer} role="listbox">
            {isSearching ? (
              <div className={styles.loadingContainer}>
                <Spinner size={SpinnerSize.small} label="Searching..." />
              </div>
            ) : suggestions.length > 0 ? (
              <>
                {suggestions.map((option, index) => (
                  <div
                    key={option.id}
                    ref={(el) => (suggestionRefs.current[index] = el)}
                    className={`${styles.suggestionItem} ${
                      index === selectedIndex ? styles.suggestionItemSelected : ''
                    }`}
                    onClick={() => handleOptionSelect(option)}
                    role="option"
                    aria-selected={index === selectedIndex}
                  >
                    <Text variant="medium">
                      {highlightText(option.text, searchText)}
                    </Text>
                  </div>
                ))}
                <div
                  className={styles.advancedSearchButton}
                  onClick={handleAdvancedSearchClick}
                  role="button"
                  tabIndex={0}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      handleAdvancedSearchClick();
                    }
                  }}
                >
                  Advanced Search
                </div>
              </>
            ) : (
              <div className={styles.noResults}>
                <Text variant="small">No results found</Text>
                <div
                  className={styles.advancedSearchButton}
                  onClick={handleAdvancedSearchClick}
                  role="button"
                  tabIndex={0}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      handleAdvancedSearchClick();
                    }
                  }}
                  style={{ marginTop: '8px' }}
                >
                  Advanced Search
                </div>
              </div>
            )}
          </div>
        )}
      </Stack>

      <Dialog
        hidden={!isDialogOpen}
        onDismiss={closeDialog}
        dialogContentProps={{
          title: `Search ${entityName}`,
          subText: `Select a ${entityName.toLowerCase()} from the list below`,
        }}
        modalProps={{
          isBlocking: false,
          styles: { main: { maxWidth: 600, minWidth: 500 } },
        }}
      >
        <Stack tokens={{ childrenGap: 16 }} className={styles.dialogContent}>
          <SearchBox
            placeholder={`Search ${entityName}...`}
            value={dialogSearchText}
            onChange={handleDialogSearchChange}
            autoFocus
          />

          {isSearching ? (
            <div className={styles.loadingContainer}>
              <Spinner size={SpinnerSize.medium} label="Loading..." />
            </div>
          ) : (
            <DetailsList
              items={filteredDialogOptions}
              columns={dialogColumns}
              selectionMode={SelectionMode.none}
              isHeaderVisible={true}
              compact={false}
              styles={{
                root: {
                  maxHeight: '300px',
                  overflowY: 'auto',
                },
              }}
            />
          )}
        </Stack>

        <DialogFooter>
          <DefaultButton onClick={closeDialog} text="Cancel" />
        </DialogFooter>
      </Dialog>
    </div>
  );
};

import { TextField } from '@fluentui/react';

interface StandardPhoneFieldProps {
  label: string;
  value?: string;
  onChange: (phone: string) => void;
  required?: boolean;
  error?: string;
  disabled?: boolean;
}

export const StandardPhoneField = ({
  label,
  value = '',
  onChange,
  required = false,
  error,
  disabled = false,
}: StandardPhoneFieldProps) => {
  // Extract digits only from any phone input format (for display purposes)
  const parsePhoneValue = (input: string): string => {
    // Remove all non-digit characters except + at the start
    let cleaned = input.replace(/[\s\-()]/g, '');

    if (!cleaned) {
      return '';
    }

    // If starts with +27, extract just the digits after it
    if (cleaned.startsWith('+27')) {
      const digits = cleaned.substring(3).replace(/\D/g, '');
      return digits;
    }

    // Remove all non-digit characters
    cleaned = cleaned.replace(/\D/g, '');

    if (!cleaned) {
      return '';
    }

    // If starts with 27 (country code without +)
    if (cleaned.startsWith('27') && cleaned.length > 2) {
      return cleaned.substring(2);
    }

    // Remove leading 0 if present
    if (cleaned.startsWith('0')) {
      return cleaned.substring(1);
    }

    return cleaned;
  };

  // Format digits for display as "+27 XX XXX XXXX"
  const formatPhoneDisplay = (digits: string): string => {
    if (!digits) {
      return '';
    }

    const parts: string[] = ['+27'];

    if (digits.length > 0) {
      parts.push(digits.substring(0, Math.min(2, digits.length)));
    }
    if (digits.length > 2) {
      parts.push(digits.substring(2, Math.min(5, digits.length)));
    }
    if (digits.length > 5) {
      parts.push(digits.substring(5, Math.min(9, digits.length)));
    }

    return parts.join(' ');
  };

  const handleChange = (_: any, newValue?: string) => {
    if (!newValue) {
      onChange('');
      return;
    }

    // Parse to get clean digits
    const cleanDigits = parsePhoneValue(newValue);

    // Pass E.164 format (+27 + digits) to parent
    if (cleanDigits.length > 0) {
      onChange(`+27${cleanDigits}`);
    } else {
      onChange('');
    }
  };

  // Display the formatted version with +27
  const displayValue = formatPhoneDisplay(parsePhoneValue(value));

  return (
    <TextField
      label={label}
      value={displayValue}
      onChange={handleChange}
      required={required}
      disabled={disabled}
      errorMessage={error}
      placeholder="+27 XX XXX XXXX"
    />
  );
};

