    setIsEditing(false);
    setLineItemFormData({
      productId: undefined,
      productName: '',
      description: '',
      quantity: 1,
      pricePerUnit: 0,
      manualDiscountAmount: 0,
      tax: 0,
      baseAmount: 0,
      extendedAmount: 0,
    });
    setProductLookupName('');
  };

