          if (rolloverChild.wipId) {
            await teamWorkItemService.batchUpdate([{
              id: rolloverChild.wipId,
              data: {
                overtimeEnabled: false,
                dayEndMinutes: 1020 // WORKING_END - standard 17:00
              }
            }]);
