                  onChange={(_, value) => updateStaffHours('factoryStaff', 'saturday', value || '')}
                  styles={{ root: { width: 150 } }}
                  placeholder="(not working)"
                />
                <TextField 
                  label="Sunday" 
                  value={settings.workingHours?.factoryStaff?.sunday || ''}
