using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace MillenniumERP.Domain.Entities;

[Table("system_settings")]
public class SystemSetting
{
    [Key]
    [Column("id")]
    public int Id { get; set; }

    [Column("setting_key")]
    [MaxLength(100)]
    [Required]
    public string SettingKey { get; set; } = string.Empty;

    [Column("setting_value")]
    public string? SettingValue { get; set; }

    [Column("category")]
    [MaxLength(50)]
    public string? Category { get; set; }

    [Column("description")]
    [MaxLength(500)]
    public string? Description { get; set; }

    [Column("created_on")]
    public DateTime? CreatedOn { get; set; }

    [Column("modified_on")]
    public DateTime? ModifiedOn { get; set; }
}

frontend/src/components/ProductionPlanne.content:
import { Stack, Text } from '@fluentui/react';
import { useMemo, memo } from 'react';

interface Job {
  id: string;
  name: string;
  orderNumber: string;
  customer: string;
  estimatedEFinks: number;
  plannedDateStr: string | null;
  jigId: string | null;
  productionComplete: boolean;
}

interface Jig {
  id: string;
  name: string;
  averageEfinks?: number;
}

interface WeekViewProps {
  daysInView: string[];
  jobs: Job[];
  jigTeams: Jig[];
  onDragStart: (jobId: string) => void;
  onDragOver: (e: React.DragEvent) => void;
  onDrop: (dateStr: string, jigId: string | null) => void;
  onJobDoubleClick: (jobId: string) => void;
  onDayClick: (dayStr: string) => void;
  onTeamDoubleClick: (teamId: string) => void;
}

const WeekViewComponent: React.FC<WeekViewProps> = ({
  daysInView,
  jobs,
  jigTeams,
  onDragStart,
  onDragOver,
  onDrop,
  onJobDoubleClick,
  onDayClick,
  onTeamDoubleClick
}) => {
  const jobsByDateAndJig = useMemo(() => {
    const map = new Map<string, Job[]>();
    for (const job of jobs) {
      if (job.plannedDateStr && job.jigId) {
        const key = `${job.plannedDateStr}|${job.jigId}`;
        const existing = map.get(key) || [];
        existing.push(job);
        map.set(key, existing);
      }
    }
    return map;
  }, [jobs]);

  const unallocatedByDate = useMemo(() => {
    const map = new Map<string, Job[]>();
    for (const job of jobs) {
      if (job.plannedDateStr && !job.jigId) {
        const existing = map.get(job.plannedDateStr) || [];
        existing.push(job);
        map.set(job.plannedDateStr, existing);
      }
    }
    return map;
  }, [jobs]);

  const efinksByDate = useMemo(() => {
    const map = new Map<string, number>();
    for (const job of jobs) {
      if (job.plannedDateStr) {
        const current = map.get(job.plannedDateStr) || 0;
        map.set(job.plannedDateStr, current + job.estimatedEFinks);
      }
    }
    return map;
  }, [jobs]);

  const getJobsForDateAndJig = (dateStr: string, jigId: string) => {
    return jobsByDateAndJig.get(`${dateStr}|${jigId}`) || [];
  };

  const getUnallocatedJobsForDate = (dateStr: string) => {
    return unallocatedByDate.get(dateStr) || [];
  };

  const getTotalEFinksForDate = (dateStr: string): number => {
    return efinksByDate.get(dateStr) || 0;
  };

  const formatDate = (dateStr: string): string => {
    const date = new Date(dateStr);
    const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    return `${days[date.getDay()]} ${date.getDate()}/${date.getMonth() + 1}`;
  };

  const sortDaysForGrid = (days: string[]): string[] => {
    return [...days].sort((a, b) => {
      const dayA = new Date(a).getDay();
      const dayB = new Date(b).getDay();
      const orderA = dayA === 0 ? 7 : dayA;
      const orderB = dayB === 0 ? 7 : dayB;
      return orderA - orderB;
    });
  };

  const sortedDays = sortDaysForGrid(daysInView);

  const row1Days = sortedDays.slice(0, 3);
  const row2Days = sortedDays.slice(3, 6);
  const row3Days = sortedDays.slice(6, 7);

  const renderDayCard = (dateStr: string) => {
    const totalEFinks = getTotalEFinksForDate(dateStr);
    const capacity = jigTeams.reduce((sum, team) => sum + (team.averageEfinks || 80), 0);
    const utilizationPercent = capacity > 0 ? (totalEFinks / capacity) * 100 : 0;
    const isFullyBooked = utilizationPercent >= 90;
    const isNearlyFull = utilizationPercent >= 75;

    const date = new Date(dateStr);
    const dayOfWeek = date.getDay();
    const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

    const unallocatedJobs = getUnallocatedJobsForDate(dateStr);
    const hasUnallocated = unallocatedJobs.length > 0;
    const unallocatedEFinks = unallocatedJobs.reduce((sum, j) => sum + j.estimatedEFinks, 0);

    return (
      <Stack
        key={`day-${dateStr}`}
        styles={{
          root: {
            border: '2px solid #ddd',
            borderRadius: 4,
            backgroundColor: isWeekend ? '#e8e8e8' : 'white',
            opacity: isWeekend ? 0.7 : 1,
            display: 'flex',
            flexDirection: 'column',
            height: '100%',
            minHeight: 0
          }
        }}
      >
        <Stack
          horizontal
          horizontalAlign="space-between"
          onClick={() => onDayClick(dateStr)}
          styles={{
            root: {
              padding: '10px 15px',
              backgroundColor: isWeekend ? '#999' : '#0078d4',
              color: 'white',
              cursor: 'pointer',
              flexShrink: 0,
              ':hover': {
                opacity: 0.9
              }
            }
          }}
        >
          <Stack horizontal verticalAlign="center" tokens={{ childrenGap: 6 }}>
            <Text variant="medium" styles={{ root: { color: 'white', fontWeight: 600 } }}>
              {formatDate(dateStr)}
            </Text>
            {(isFullyBooked || isNearlyFull) && (
              <Text 
                variant="medium" 
                styles={{ 
                  root: { 
                    color: 'rgba(255,255,255,0.8)', 
                    fontWeight: 600
                  } 
                }}
                title={isFullyBooked ? 'Fully booked (≥90%)' : 'Nearly full (≥75%)'}
              >
                !
              </Text>
            )}
          </Stack>
          <Text variant="small" styles={{ root: { color: 'white', fontWeight: 600 } }}>
            {totalEFinks} E-Finks
          </Text>
        </Stack>

        <div 
          onDragOver={onDragOver}
          onDrop={() => onDrop(dateStr, null)}
          style={{ 
            display: 'flex', 
            gap: 1, 
            backgroundColor: '#ddd',
            padding: 1,
            flex: 1
          }}
        >
          {hasUnallocated && (
            <Stack
              onDragOver={onDragOver}
              onDrop={(e) => { e.stopPropagation(); onDrop(dateStr, null); }}
              styles={{
                root: {
                  backgroundColor: '#ffebee',
                  padding: 8,
                  flex: 1,
                  minWidth: 0,
                  overflow: 'hidden'
                }
              }}
            >
              <Text variant="small" block styles={{ root: { fontWeight: 600, color: '#c62828', marginBottom: 8 } }}>
                Unallocated ({unallocatedEFinks})
              </Text>
              <Stack tokens={{ childrenGap: 6 }}>
                {unallocatedJobs.map(job => (
                  <div
                    key={job.id}
                    draggable
                    onDragStart={() => onDragStart(job.id)}
                    onDoubleClick={() => onJobDoubleClick(job.id)}
                    style={{
                      padding: 6,
                      background: job.productionComplete 
                        ? 'linear-gradient(135deg, rgba(180, 180, 180, 0.85), rgba(200, 200, 200, 0.75))' 
                        : 'linear-gradient(135deg, rgba(198, 40, 40, 0.85), rgba(160, 30, 30, 0.75))',
                      borderRadius: 6,
                      border: job.productionComplete ? '1px solid rgba(180, 180, 180, 0.6)' : '1px solid rgba(255, 255, 255, 0.3)',
                      cursor: 'grab',
                      boxShadow: job.productionComplete 
                        ? '0 2px 6px rgba(0,0,0,0.12), inset 0 1px 0 rgba(255,255,255,0.3)' 
                        : '0 2px 8px rgba(198, 40, 40, 0.3), inset 0 1px 0 rgba(255,255,255,0.25)',
                      opacity: job.productionComplete ? 0.8 : 1
                    }}
                  >
                    <Text variant="tiny" block styles={{ root: { fontWeight: 600, wordBreak: 'break-word', color: 'white' } }}>
                      {job.orderNumber}{job.name?.includes('(Rollover)') || job.name?.includes('(Roll Over)') ? ' (Rollover)' : ''}{job.productionComplete ? ' (Complete)' : ''}
                    </Text>
                    <Text variant="tiny" block styles={{ root: { wordBreak: 'break-word', color: 'rgba(255,255,255,0.9)' } }}>
                      {job.customer}
                    </Text>
                    <Text variant="tiny" block styles={{ root: { color: 'rgba(255,255,255,0.8)' } }}>
                      {job.estimatedEFinks} E-Finks
                    </Text>
                  </div>
                ))}
              </Stack>
            </Stack>
          )}

          {jigTeams.map(jigInfo => {
            const jigJobs = getJobsForDateAndJig(dateStr, jigInfo.id);
            const jigEFinks = jigJobs.reduce((sum, j) => sum + j.estimatedEFinks, 0);
            const jigUtilization = (jigEFinks / 90) * 100;
            const jigFullyBooked = jigUtilization >= 90;
            const jigNearlyFull = jigUtilization >= 75;

            return (
              <Stack
                key={jigInfo.id}
                onDragOver={onDragOver}
                onDrop={(e) => { e.stopPropagation(); onDrop(dateStr, jigInfo.id); }}
                styles={{
                  root: {
                    backgroundColor: '#faf9f8',
                    padding: 8,
                    flex: 1,
                    minWidth: 0,
                    overflow: 'hidden'
                  }
                }}
              >
                <Stack horizontal verticalAlign="center" tokens={{ childrenGap: 4 }}>
                  <Text 
                    variant="small" 
                    block 
                    onDoubleClick={() => onTeamDoubleClick(jigInfo.id)}
                    styles={{ root: { fontWeight: 600, color: '#323130', marginBottom: 8, cursor: 'pointer' } }}
                  >
                    {jigInfo.name} ({jigEFinks})
                  </Text>
                  {(jigFullyBooked || jigNearlyFull) && (
                    <Text 
                      variant="small" 
                      styles={{ 
                        root: { 
                          color: '#666', 
                          fontWeight: 600,
                          marginBottom: 8
                        } 
                      }}
                      title={jigFullyBooked ? 'Fully booked (≥90%)' : 'Nearly full (≥75%)'}
                    >
                      !
                    </Text>
                  )}
                </Stack>
                <Stack tokens={{ childrenGap: 6 }}>
                  {jigJobs.map(job => (
                    <div
                      key={job.id}
                      draggable
                      onDragStart={() => onDragStart(job.id)}
                      onDoubleClick={() => onJobDoubleClick(job.id)}
                      style={{
                        padding: 6,
                        background: job.productionComplete 
                          ? 'linear-gradient(135deg, rgba(180, 180, 180, 0.85), rgba(200, 200, 200, 0.75))' 
                          : 'linear-gradient(135deg, rgba(0, 120, 212, 0.85), rgba(0, 90, 180, 0.75))',
                        borderRadius: 6,
                        border: job.productionComplete ? '1px solid rgba(180, 180, 180, 0.6)' : '1px solid rgba(255, 255, 255, 0.3)',
                        cursor: 'grab',
                        boxShadow: job.productionComplete 
                          ? '0 2px 6px rgba(0,0,0,0.12), inset 0 1px 0 rgba(255,255,255,0.3)' 
                          : '0 2px 8px rgba(0, 120, 212, 0.3), inset 0 1px 0 rgba(255,255,255,0.25)',
                        opacity: job.productionComplete ? 0.8 : 1
                      }}
                    >
                      <Text variant="tiny" block styles={{ root: { fontWeight: 600, wordBreak: 'break-word', color: 'white' } }}>
                        {job.orderNumber}{job.name?.includes('(Rollover)') || job.name?.includes('(Roll Over)') ? ' (Rollover)' : ''}{job.productionComplete ? ' (Complete)' : ''}
                      </Text>
                      <Text variant="tiny" block styles={{ root: { wordBreak: 'break-word', color: 'rgba(255,255,255,0.9)' } }}>
                        {job.customer}
                      </Text>
                      <Text variant="tiny" block styles={{ root: { color: 'rgba(255,255,255,0.8)' } }}>
                        {job.estimatedEFinks} E-Finks
                      </Text>
                    </div>
                  ))}
                </Stack>
              </Stack>
            );
          })}
        </div>
      </Stack>
    );
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 12,
        padding: '0 12px 12px 0'
      }}
    >
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(3, 1fr)',
          gap: 12
        }}
      >
        {row1Days.map(dateStr => renderDayCard(dateStr))}
      </div>

      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(3, 1fr)',
          gap: 12
        }}
      >
        {row2Days.map(dateStr => renderDayCard(dateStr))}
      </div>

      {row3Days.length > 0 && (
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(3, 1fr)',
            gap: 12
          }}
        >
          {row3Days.map(dateStr => renderDayCard(dateStr))}
        </div>
      )}
    </div>
  );
};

export const WeekView = memo(WeekViewComponent);

import { Stack, Text } from '@fluentui/react';
import { useMemo, memo } from 'react';

interface Job {
  id: string;
  name: string;
  orderNumber: string;
  customer: string;
  estimatedEFinks: number;
  plannedDateStr: string | null;
  jigId: string | null;
  productionComplete: boolean;
}

interface Jig {
  id: string;
  name: string;
  averageEfinks?: number;
}

interface MonthViewProps {
  daysInView: string[];
  jobs: Job[];
  jigTeams: Jig[];
  currentMonth: string;
  onDragStart: (jobId: string) => void;
  onDragOver: (e: React.DragEvent) => void;
  onDrop: (dateStr: string) => void;
  onJobDoubleClick: (jobId: string) => void;
  onWeekClick: (weekStartDate: string) => void;
  onDayClick: (dateStr: string) => void;
}

const MonthViewComponent: React.FC<MonthViewProps> = ({
  daysInView,
  jobs,
  jigTeams,
  currentMonth,
  onDragStart,
  onDragOver,
  onDrop,
  onJobDoubleClick,
  onWeekClick,
  onDayClick
}) => {
  const currentMonthDate = new Date(currentMonth + 'T00:00:00Z');
  const currentMonthNum = currentMonthDate.getUTCMonth();

  const jobsByDate = useMemo(() => {
    const map = new Map<string, Job[]>();
    for (const job of jobs) {
      if (job.plannedDateStr) {
        const existing = map.get(job.plannedDateStr) || [];
        existing.push(job);
        map.set(job.plannedDateStr, existing);
      }
    }
    return map;
  }, [jobs]);

  const efinksByDate = useMemo(() => {
    const map = new Map<string, number>();
    for (const job of jobs) {
      if (job.plannedDateStr) {
        const current = map.get(job.plannedDateStr) || 0;
        map.set(job.plannedDateStr, current + job.estimatedEFinks);
      }
    }
    return map;
  }, [jobs]);

  const getJobsForDate = (dateStr: string) => {
    return jobsByDate.get(dateStr) || [];
  };

  const getTotalEFinksForDate = (dateStr: string): number => {
    return efinksByDate.get(dateStr) || 0;
  };

  const formatDate = (dateStr: string): string => {
    const date = new Date(dateStr + 'T00:00:00Z');
    const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    return `${days[date.getUTCDay()]} ${date.getUTCDate()}`;
  };

  const isCurrentMonth = (dateStr: string): boolean => {
    const date = new Date(dateStr + 'T00:00:00Z');
    return date.getUTCMonth() === currentMonthNum;
  };

  const getISOWeekNumber = (dateStr: string): number => {
    const date = new Date(dateStr + 'T00:00:00Z');
    const tempDate = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
    const dayNum = tempDate.getUTCDay() || 7;
    tempDate.setUTCDate(tempDate.getUTCDate() + 4 - dayNum);
    const yearStart = new Date(Date.UTC(tempDate.getUTCFullYear(), 0, 1));
    const weekNum = Math.ceil((((tempDate.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
    return weekNum;
  };

  const getMondayOfWeek = (dateStr: string): string => {
    const date = new Date(dateStr + 'T00:00:00Z');
    const dayOfWeek = date.getUTCDay();
    const daysToMonday = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
    const monday = new Date(date);
    monday.setUTCDate(date.getUTCDate() + daysToMonday);
    return monday.toISOString().split('T')[0];
  };

  const groupDaysByWeek = () => {
    const weeks: string[][] = [];
    for (let i = 0; i < daysInView.length; i += 7) {
      weeks.push(daysInView.slice(i, i + 7));
    }
    return weeks;
  };

  const weeks = groupDaysByWeek();

  return (
    <Stack>
      {weeks.map((weekDays, weekIndex) => {
        const midWeekDay = weekDays[3] || weekDays[0];
        const weekNumber = getISOWeekNumber(midWeekDay);
        const weekMonday = getMondayOfWeek(midWeekDay);
        const weekTotalEFinks = weekDays.reduce((sum, dateStr) => sum + getTotalEFinksForDate(dateStr), 0);

        return (
          <Stack key={`week-${weekIndex}`} styles={{ root: { marginBottom: 20 } }}>
            <Stack
              horizontal
              horizontalAlign="space-between"
              verticalAlign="center"
              styles={{
                root: {
                  padding: '10px 15px',
                  backgroundColor: '#0078d4',
                  color: 'white',
                  cursor: 'pointer',
                  borderRadius: '4px 4px 0 0',
                  ':hover': {
                    backgroundColor: '#106ebe'
                  }
                }
              }}
              onClick={() => onWeekClick(weekMonday)}
            >
              <Text variant="medium" styles={{ root: { color: 'white', fontWeight: 600 } }}>
                Week {weekNumber}
              </Text>
              <Text variant="small" styles={{ root: { color: 'white', fontWeight: 600 } }}>
                {weekTotalEFinks} E-Finks
              </Text>
            </Stack>

            <div
              style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(7, 1fr)',
                gap: 10,
                padding: 15,
                backgroundColor: '#f3f2f1',
                borderRadius: '0 0 4px 4px'
              }}
            >
              {weekDays.map(dateStr => {
                const dayJobs = getJobsForDate(dateStr);
                const totalEFinks = getTotalEFinksForDate(dateStr);
                const capacity = jigTeams.reduce((sum, team) => sum + (team.averageEfinks || 80), 0);
                const utilizationPercent = capacity > 0 ? (totalEFinks / capacity) * 100 : 0;
                const isFullyBooked = utilizationPercent >= 90;

                const date = new Date(dateStr + 'T00:00:00Z');
                const dayOfWeek = date.getUTCDay();
                const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
                const isOtherMonth = !isCurrentMonth(dateStr);

                return (
                  <Stack
                    key={dateStr}
                    onDragOver={onDragOver}
                    onDrop={() => onDrop(dateStr)}
                    styles={{
                      root: {
                        border: '2px solid #ddd',
                        borderRadius: 4,
                        backgroundColor: isOtherMonth ? '#f5f5f5' : (isWeekend ? '#e8e8e8' : 'white'),
                        overflow: 'hidden',
                        minHeight: 150,
                        opacity: isOtherMonth ? 0.5 : (isWeekend ? 0.7 : 1)
                      }
                    }}
                  >
                    <Stack
                      horizontal
                      horizontalAlign="space-between"
                      verticalAlign="center"
                      onClick={() => onDayClick(dateStr)}
                      styles={{
                        root: {
                          padding: '8px 10px',
                          backgroundColor: isOtherMonth ? '#bbb' : (isWeekend ? '#999' : '#0078d4'),
                          color: 'white',
                          cursor: 'pointer',
                          ':hover': {
                            backgroundColor: isOtherMonth ? '#999' : (isWeekend ? '#777' : '#106ebe')
                          }
                        }
                      }}
                    >
                      <Stack>
                        <Text variant="small" styles={{ root: { color: 'white', fontWeight: 600 } }}>
                          {formatDate(dateStr)}
                        </Text>
                        <Text variant="tiny" styles={{ root: { color: 'white' } }}>
                          {totalEFinks} E-Finks
                        </Text>
                      </Stack>
                      {isFullyBooked && (
                        <Text styles={{ root: { color: '#ff4444', fontWeight: 700, fontSize: 16 } }}>!</Text>
                      )}
                    </Stack>

                    <Stack styles={{ root: { padding: 8, gap: 6, maxHeight: 306, overflowY: 'auto' } }}>
                      {dayJobs.map(job => (
                        <div
                          key={job.id}
                          draggable
                          onDragStart={() => onDragStart(job.id)}
                          onDoubleClick={() => onJobDoubleClick(job.id)}
                          style={{
                            padding: 6,
                            background: job.productionComplete 
                              ? 'linear-gradient(135deg, rgba(180, 180, 180, 0.85), rgba(200, 200, 200, 0.75))' 
                              : 'linear-gradient(135deg, rgba(0, 120, 212, 0.85), rgba(0, 90, 180, 0.75))',
                            borderRadius: 6,
                            border: job.productionComplete ? '1px solid rgba(180, 180, 180, 0.6)' : '1px solid rgba(255, 255, 255, 0.3)',
                            cursor: 'grab',
                            boxShadow: job.productionComplete 
                              ? '0 2px 6px rgba(0,0,0,0.12), inset 0 1px 0 rgba(255,255,255,0.3)' 
                              : '0 2px 8px rgba(0, 120, 212, 0.3), inset 0 1px 0 rgba(255,255,255,0.25)',
                            opacity: job.productionComplete ? 0.8 : 1
                          }}
                        >
                          <Text variant="tiny" block styles={{ root: { fontWeight: 600, color: 'white' } }}>
                            {job.orderNumber}{job.name?.includes('(Rollover)') || job.name?.includes('(Roll Over)') ? ' (Rollover)' : ''}{job.productionComplete ? ' (Complete)' : ''}
                          </Text>
                          <Text variant="tiny" block styles={{ root: { color: 'rgba(255,255,255,0.9)' } }}>
                            {job.customer}
                          </Text>
                          <Text variant="tiny" block styles={{ root: { color: 'rgba(255,255,255,0.8)' } }}>
                            {job.estimatedEFinks} E-Finks
                          </Text>
                        </div>
                      ))}
                    </Stack>
                  </Stack>
                );
              })}
            </div>
          </Stack>
        );
      })}
    </Stack>
  );
};

export const MonthView = memo(MonthViewComponent);

